import java.util.concurrent.*;

class Traveler {
    private volatile boolean asleep = false;

    void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    private void countSomeSheep() {
        System.out.println("Counting some sheep...");
    }
}

class DriftingThread implements Runnable {
    private Traveler traveler;

    DriftingThread(Traveler traveler) {
        this.traveler = traveler;
    }

    @Override
    public void run() {
        while (!traveler.isAsleep()) {
            traveler.countSomeSheep();
        }
    }
}

public class Main {
    private static final ExecutorService executor = Executors.newFixedThreadPool(3);
    private static final Traveler traveler = new Traveler();

    public static void main(String[] args) {
        Runnable runnable = () -> { traveler.tryToSleep(); };
        executor.submit(runnable);
        executor.submit(new DriftingThread(traveler));
        executor.shutdown();
    }
}

