import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.ConcurrentLinkedDeque;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.LockSupport;

public class Scout {
    private static final int NUM_THREADS = 3;
    private static final AtomicBoolean asleep = new AtomicBoolean(false);
    private static final AtomicInteger count = new AtomicInteger();
    private static final ConcurrentLinkedDeque<Runnable> tasks = new ConcurrentLinkedDeque<>();
    private static final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutorService(
            Executors.defaultThreadFactory().setDaemon(true).setPriority(Thread.NORM_PRIORITY), false);

    public static void main(String[] args) {
        scheduler.scheduleAtFixedRate(Scout::startDrifting, 0, 10, TimeUnit.MILLISECONDS);
        tasks.add(() -> {
            tryToSleep();
        });
        tasks.add(() -> {
            countSomeSheep();
        });
        for (int i = 2; I-- > 0; ) {
            Thread t = new Thread(() -> {
                while (!tasks.isEmpty()) {
                    Runnable task = tasks.pollFirst();
                    if (task != null) {
                        try {
                            task.run();
                        } catch (Throwable e) {
                            // Ignore exception and continue with next task
                        } finally {
                            Thread.yield();
                        }
                    }
                }
                Thread.yield();
            });
            t.setDaemon(true);
            t.start();
        }
        scheduler.shutdown();
        while (!scheduler.isTerminated()) {
            // Wait for thread pool to terminate
            LockSupport.parkNanos(1L);
        }
        System.out.println("Final count: " + count);
    }

    private static void startDrifting() {
        // Print drifting message periodically
        System.out.println("Drifting...");
    }

    private static void tryToSleep() {
        while (!asleep.get()) {
            boolean sleepResult = asleep.compareAndSet(false, true);
            if (sleepResult) {
                // Sleep for a bit before waking up
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    // Ignore interrupt and continue with sleep
                } finally {
                    asleep.set(false);
                }
            } else {
                LockSupport.parkNanos(50L);
            }
        }
    }

    private static void countSomeSheep() {
        int currentCount = count.getAndIncrement();
        System.out.println("Observed " + currentCount + " fireflies...");
        if (currentCount % 10 == 0) {
            tasks.add(() -> {
                tryToSleep();
            });
        }
    }
}

