import java.util.stream.Collectors;

public class CosmicCats {
    private static final String[] CAT_IDENTIFIERS = {"Whiskers-1", "Whiskers-2", "Whiskers-3", "Paws-1", "Paws-2", "Claw-1", "Claw-2"};

    private final Set<String> catIdentifiers;

    private CosmicCats(Set<String> catIdentifiers) {
        this.catIdentifiers = catIdentifiers;
    }

    public static CosmicCats create() {
        Set<String> catIdentifiers = new HashSet<>();
        for (int I = 0; I < CAT_IDENTIFIERS.length; i++) {
            String[] split = CAT_IDENTIFIERS[i].split("-");
            for (int j = 1; j <= Integer.parseInt(split[1]); j++) {
                catIdentifiers.add(String.format("%s-%d", split[0], j));
            }
        }
        return new CosmicCats(catIdentifiers);
    }

    public boolean contains(String identifier) {
        return catIdentifiers.contains(identifier);
    }

    public List<String> asList() {
        return new ArrayList<>(catIdentifiers);
    }

    public static void main(String[] args) throws Exception {
        CosmicCats cats = CosmicCats.create();
        Set<String> uniqueNames = new HashSet<>();
        ExecutorService executorService = Executors.newFixedThreadPool(3);

        BiConsumer<List<String>, List<String>> merge = (list1, list2) -> {
            for (String name : list2) {
                if (!uniqueNames.contains(name)) {
                    uniqueNames.add(name);
                }
            }
        };

        Function<List<String>, List<String>> removeDuplicates = list -> {
            return new ArrayList<>(new HashSet<>(list));
        };

        Future<?> task1 = executorService.submit(() -> {
            List<String> names1 = cats.asList().subList(0, 5);
            System.out.println("Names from CosmicCats: " + names1);
            return removeDuplicates.apply(names1);
        });

        Future<?> task2 = executorService.submit(() -> {
            List<String> names2 = Arrays.asList("Whiskers-3", "Paws-1", "Claw-2");
            System.out.println("Names from External Source: " + names2);
            return removeDuplicates.apply(names2);
        });

        Future<?> task3 = executorService.submit(() -> {
            List<String> names3 = Arrays.asList("Whiskers-4", "Paws-3", "Claw-3");
            System.out.println("Names from External Source: " + names3);
            return removeDuplicates.apply(names3);
        });

        executorService.shutdown();

        List<List<String>> results = Arrays.asList(task1.get(), task2.get(), task3.get());
        System.out.println("Merged and Unique Names: " + results.stream().flatMap(Function.identity()).sorted().collect(Collectors.toList()));

        TimeUnit.SECONDS.sleep(5);
    }
}

