final class CosmicCats {
    private static final AtomicInteger ID_COUNTER = new AtomicInteger();
    private static final int MAX_THREADS = 3;
    private static final ForkJoinPool forkJoinPool = new ForkJoinPool(Math.min(MAX_THREADS - 1, Runtime.getRuntime().availableProcessors()),
            Executors.defaultThreadFactory(),
            new ThreadLocalRandom(), null, false);

    private static final Comparator<Integer> ID_COMPARATOR = Comparator.naturalOrder();
    private static final Set<Integer> CATS = new ConcurrentSkipListSet<>(ID_COMPARATOR);

    private static final ScheduledExecutorService SCHEDULER = Executors.newSingleThreadScheduledExecutor(Executors.defaultThreadFactory());
    private static final RejectedExecutionHandler REJECTED_EXECUTION_HANDLER = r -> {
        System.err.println("Task rejected: " + r.getCommand() + ", " + r.getExecuteExceptioin());
    };

    static void main(String[] args) throws Exception {
        int numCats = 1000;
        long numTasks = 5_000L;
        long delay = TimeUnit.SECONDS.toMillis(2);

        IntStream.rangeClosed(1, numCats)
                .forEach(CATS::add);

        Future<?> f1 = forkJoinPool.submit(() -> {
            LongStream.rangeClosed(1L, numTasks)
                    .mapToObj(i -> i)
                    .filter(id -> CATS.contains(ThreadLocalRandom.current().nextInt(1, numCats)))
                    .collect(Collectors.toList());
        });

        Future<?> f2 = forkJoinPool.submit(() -> {
            LongStream.rangeClosed(1L, numTasks)
                    .mapToObj(i -> i)
                    .filter(id -> !CATS.contains(ThreadLocalRandom.current().nextInt(1, numCats)))
                    .collect(Collectors.toList());
        });

        try {
            ThreadFactory threadFactory = Executors.defaultThreadFactory();
            threadFactory.setDaemon(true);
            threadFactory.setPriority(Thread.NORM_PRIORITY);
            ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2, threadFactory);
            scheduler.setContinueExistingExecutions(false);
            scheduler.setRejectedExecutionHandler(REJECTED_EXECUTION_HANDLER);
            scheduler.scheduleAtFixedRate(() -> {
                Set<Integer> newCats = generateNewCats();
                CATS.addAll(newCats);
                System.out.println("Added " + newCats + " cats: " + (System.currentTimeMillis() - forkJoinPool.getTotalSubmittedTasks()) + " ms");
            }, delay, delay, TimeUnit.MILLISECONDS);
            scheduler.shutdown();
        } finally {
            f1.get();
            f2.get();
            forkJoinPool.shutdownNow();
            SCHEDULER.shutdown();
            Thread.sleep(500L); // wait for threads to finish shutdown
            System.out.println("Program completed: " + (System.currentTimeMillis() - forkJoinPool.getTotalSubmittedTasks()) + " ms");
        }
    }

    private static Set<Integer> generateNewCats() {
        int numNewCats = ThreadLocalRandom.current().nextInt(5, 10);
        Set<Integer> newCats = new LinkedHashSet<>();
        for (int I = 1; I <= numNewCats; i++) {
            int id = ID_COUNTER.getAndIncrement();
            newCats.add(id);
        }
        return newCats;
    }

    private static Set<Integer> getCats() {
        return Collections.unmodifiableSet(CATS);
    }
}

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.ConcurrentLinkedDeque;
import java.util.LinkedList;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

class CosmicCats {
    private final Set<Integer> catIds = Collections.unmodifiableSet(new LinkedHashSet<>(Collections.nCopies(3, 0)));

    static class CatInfo implements Runnable {
        int id;
        boolean isCat;
        Supplier<String> displaySupplier;

        public CatInfo(int id, boolean isCat, Supplier<String> displaySupplier) {
            this.id = id;
            this.isCat = isCat;
            this.displaySupplier = displaySupplier;
        }

        @Override
        public void run() {
            String catDisplay = displaySupplier.get();
            if (isCat) {
                System.out.println("Cat " + id + ": " + catDisplay);
            } else {
                System.out.println("Non-Cat " + id + ": " + catDisplay);
            }
        }
    }

    boolean isCat(int id) {
        return catIds.contains(id);
    }

    String displayAllCats() {
        Collection<String> displays = catIds.stream().map(this::display).collect(Collectors.toList());
        int nonCatCount = (3 - catIds.size()) * 2; // Each Cat has 2 paws and a whisker, so non-Cats need twice as many "faux" IDs.
        displays.addAll(IntStream.rangeClosed(catIds.size(), 3 + nonCatCount)
                .mapToObj(i -> String.format("Non-Cat %d: Whisker %d, Paw %d", i, I % 2, (I - catIds.size()) / 2))
                .collect(Collectors.toList()));
        return displays.toString();
    }

    private String display(int id) {
        int whisker = id; // The whisker ID is simply the Cat ID.
        int paw1 = whisker * 2 + 1; // Each Cat has two paws, and they're consecutive.
        int paw2 = whisker * 2; // The second paw for a given Cat is the first one plus one.
        return String.format("Whisker %d, Paw %d, Paw %d", whisker, paw1, paw2);
    }

    public static void main(String[] args) {
        CosmicCats cats = new CosmicCats();
        ExecutorService pool = Executors.newFixedThreadPool(3);
        ConcurrentLinkedDeque<Future<?>> tasks = new ConcurrentLinkedDeque<>();

        for (int i : cats.catIds) {
            Supplier<String> displaySupplier = () -> cats.display(i);
            CatInfo catTask = new CatInfo(i, true, displaySupplier);
            tasks.addLast(pool.submit(catTask));
        }

        for (int i : IntStream.rangeClosed(3 + cats.catIds.size(), 6)) {
            Supplier<String> displaySupplier = () -> String.format("Non-Cat %d: Whisker %d, Paw %d", i, I % 2, (I - cats.catIds.size()) / 2);
            CatInfo nonCatTask = new CatInfo(i, false, displaySupplier);
            tasks.addLast(pool.submit(nonCatTask));
        }

        ArrayList<String> displays = new ArrayList<>();
        while (!tasks.isEmpty()) {
            Future<?> task = tasks.pollFirst(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
            if (task != null && !task.isDone() && !task.isCancelled()) {
                displays.addAll(task.get().toString());
            }
        }

        String result = displays.stream().collect(Collectors.joining("\n"));
        System.out.println(result);
        pool.shutdown();
    }
}

