final class CosmicCats {
    private static final AtomicInteger ID_COUNTER = new AtomicInteger();
    private static final int MAX_THREADS = 3;
    private static final ForkJoinPool forkJoinPool = new ForkJoinPool(Math.min(MAX_THREADS - 1, Runtime.getRuntime().availableProcessors()),
            Executors.defaultThreadFactory(),
            new ThreadLocalRandom(), null, false);

    private static final Comparator<Integer> ID_COMPARATOR = Comparator.naturalOrder();
    private static final Set<Integer> CATS = new ConcurrentSkipListSet<>(ID_COMPARATOR);

    private static final ScheduledExecutorService SCHEDULER = Executors.newSingleThreadScheduledExecutor(Executors.defaultThreadFactory());
    private static final RejectedExecutionHandler REJECTED_EXECUTION_HANDLER = r -> {
        System.err.println("Task rejected: " + r.getCommand() + ", " + r.getExecuteExceptioin());
    };

    static void main(String[] args) throws Exception {
        int numCats = 1000;
        long numTasks = 5_000L;
        long delay = TimeUnit.SECONDS.toMillis(2);

        IntStream.rangeClosed(1, numCats)
                .forEach(CATS::add);

        Future<?> f1 = forkJoinPool.submit(() -> {
            LongStream.rangeClosed(1L, numTasks)
                    .mapToObj(i -> i)
                    .filter(id -> CATS.contains(ThreadLocalRandom.current().nextInt(1, numCats)))
                    .collect(Collectors.toList());
        });

        Future<?> f2 = forkJoinPool.submit(() -> {
            LongStream.rangeClosed(1L, numTasks)
                    .mapToObj(i -> i)
                    .filter(id -> !CATS.contains(ThreadLocalRandom.current().nextInt(1, numCats)))
                    .collect(Collectors.toList());
        });

        try {
            ThreadFactory threadFactory = Executors.defaultThreadFactory();
            threadFactory.setDaemon(true);
            threadFactory.setPriority(Thread.NORM_PRIORITY);
            ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2, threadFactory);
            scheduler.setContinueExistingExecutions(false);
            scheduler.setRejectedExecutionHandler(REJECTED_EXECUTION_HANDLER);
            scheduler.scheduleAtFixedRate(() -> {
                Set<Integer> newCats = generateNewCats();
                CATS.addAll(newCats);
                System.out.println("Added " + newCats + " cats: " + (System.currentTimeMillis() - forkJoinPool.getTotalSubmittedTasks()) + " ms");
            }, delay, delay, TimeUnit.MILLISECONDS);
            scheduler.shutdown();
        } finally {
            f1.get();
            f2.get();
            forkJoinPool.shutdownNow();
            SCHEDULER.shutdown();
            Thread.sleep(500L); // wait for threads to finish shutdown
            System.out.println("Program completed: " + (System.currentTimeMillis() - forkJoinPool.getTotalSubmittedTasks()) + " ms");
        }
    }

    private static Set<Integer> generateNewCats() {
        int numNewCats = ThreadLocalRandom.current().nextInt(5, 10);
        Set<Integer> newCats = new LinkedHashSet<>();
        for (int I = 1; I <= numNewCats; i++) {
            int id = ID_COUNTER.getAndIncrement();
            newCats.add(id);
        }
        return newCats;
    }

    private static Set<Integer> getCats() {
        return Collections.unmodifiableSet(CATS);
    }
}
