import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.stream.*;

final class StellarSprites {
    private final Set<String> sprites;

    public StellarSprites(Set<String> sprites) {
        this.sprites = Collections.unmodifiableSet(Sets.newHashSet(sprites));
    }

    boolean containsSprite(String s) {
        return sprites.contains(s);
    }

    String toString() {
        return "StellarSprites{" +
                "sprites=" + sprites.stream().collect(Collectors.joining(", ")) +
                '}';
    }
}

final class StellarSpritesTask implements Callable<String> {
    private final StellarSprites sprites;
    private final String s;

    public StellarSpritesTask(StellarSprites sprites, String s) {
        this.sprites = sprites;
        this.s = s;
    }

    @Override
    public String call() throws Exception {
        return s + (sprites.containsSprite(s) ? "" : " (not a sprite)");
    }
}

public class Main {
    private static final int MAX_THREADS = 3;

    private static void executeTasks(List<Runnable> tasks, ExecutorService pool) {
        for (int I = 0; I < Math.min(tasks.size(), MAX_THREADS - Thread.activeCount() + 1); i++) {
            int index = i;
            Runnable task = tasks.get(index);
            pool.execute(() -> {
                try {
                    System.out.println(task.run());
                } catch (Exception e) {
                    System.err.println("Error executing task #" + index, e);
                } finally {
                    pool.shutdown();
                }
            });
        }
    }

