                    try (Random random = ThreadLocalRandom.current()) {
                        String s = "Sprite#" + i;
                        System.out.println("Thread #" + Thread.currentThread().getId() + ": " + s);
                        return new StellarSpritesTask(stellarSprites, s);
                    }
                })
                .collect(Collectors.toList());

        ExecutorService pool = Executors.newFixedThreadPool(MAX_THREADS);
        executeTasks(tasks, pool);
        System.out.println("Main thread waiting for tasks...");
        try {
            boolean terminated = pool.awaitTermination(10L, TimeUnit.SECONDS);
            System.out.println("All tasks have completed: " + terminated);
        } catch (InterruptedException e) {
            System.err.println("Error awaiting termination", e);
        } finally {
            boolean shutdown = pool.shutdown();
            System.out.println("Main thread shutting down executor service: " + shutdown);
        }
        System.out.println(stellarSprites.toString());
    }
