public class DelegatingDeviceTracker {
    private final Map<String, Point> positions;
    private final ConcurrentMap<String, Future<?>> updateFutures = new ConcurrentHashMap<>();

    public DelegatingDeviceTracker(Map<String, Point> initialPositions) {
        this.positions = Collections.unmodifiableMap(new ConcurrentHashMap<>(initialPositions));
    }

    public void updatePosition(String deviceId, Point newPosition) {
        Future<?> future = executorService().submit(() -> {
            String id = deviceId;
            if (!positions.containsKey(id)) {
                throw new IllegalArgumentException("Unknown device: " + id);
            }
            Point oldPosition = positions.get(id);
            try {
                Thread.sleep(100); // Simulate long-running position update
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Interrupted during position update", e);
            }
            positions.put(id, newPosition);
        });
        updateFutures.put(deviceId, future);
    }

    public Point getPosition(String deviceId) {
        return positions.get(deviceId);
    }

    public Set<Point> allPositions() {
        return Collections.unmodifiableSet(positions.values());
    }

    public Map<String, Point> snapshot() {
        return new LinkedHashMap<>(positions); // Keep insertion order
    }

    private ExecutorService executorService() {
