public class DelegatingDeviceTracker {
    private final ConcurrentMap<String, Point> positions = new ConcurrentHashMap<>();

    // Add initial gadgets and their positions
    public DelegatingDeviceTracker(String... idsAndPositions) {
        Arrays.stream(idsAndPositions).map(splitIdPosition -> {
            String[] parts = splitIdPosition.split(":");
            return new Pair<>(parts[0], new Point(Double.parseDouble(parts[1]), Double.parseDouble(parts[2])));
        }).forEach(this::put);
    }

    // Get the current position of a gadget, throwing an exception if it's not found
    public Point getPosition(String id) {
        return positions.get(id);
    }

    // Update the position of an existing gadget, returning the old position or null if the ID wasn't found
    public Point updatePosition(String id, Point newPosition) {
        return positions.replace(id, newPosition);
    }

    // Get a view (i.e., copy) of all current gadget positions, backed by the original map
    public Map<String, Point> getAllPositions() {
        return positions;
    }

    // Get an unmodifiable snapshot of all current gadget positions as a new map
    public Map<String, Point> snapshot() {
        return new ImmutableDelegateMap<>(positions);
    }

    private static final class Pair<K, V> implements BiConsumer<K, V>, Function<Pair<? extends K, ? extends V>, Map.Entry<? extends K, ? extends V>> {
        private final K key;
        private final V value;

        public Pair(K key, V value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public void accept(K key, V value) {
            throw new UnsupportedOperationException();
        }

        @Override
        public Map.Entry<K, V> apply(Pair<? extends K, ? extends V> t) {
            return new AbstractMap.SimpleImmutableEntry<>(t.getKey(), t.getValue());
        }
    }

    private static final class ImmutableDelegateMap<K, V> extends DelegatedSynchronizedMap<K, V> {
        private final ConcurrentMap<K, V> delegate;

        public ImmutableDelegateMap(ConcurrentMap<K, V> delegate) {
            super(delegate);
            this.delegate = delegate;
        }
    }
}

