public class DelegatingDeviceTracker {

    private final Map<String, Point> gadgets = new ConcurrentHashMap<>(); // Using a ConcurrentHashMap to ensure thread safety without explicitly synchronizing methods
    private final ExecutorService executor = Executors.newFixedThreadPool(2); // Creating a fixed thread pool with 2 threads

    public DelegatingDeviceTracker(Map<String, Point> initialGadgets) {
        gadgets.putAll(initialGadgets); // Initializing the tracker with the given map of gadget IDs to their initial positions
    }

    public void updatePosition(String id, int x, int y) throws PositionNotFoundException {
        Point point = gadgets.getOrDefault(id, null); // Getting the current position of the gadget or null if it doesn't exist
        if (point != null && !gadgets.keySet().contains(id)) { // Checking if the gadget ID already exists in the map
            throw new PositionNotFoundException("Gadget with id " + id + " does not exist"); // Throwing an exception if it doesn't
        }
        gadgets.put(id, new Point(x, y)); // Updating the position of the gadget
    }

    public Collection<Point> getAllPositions() {
        return Collections.unmodifiableCollection(gadgets.values()); // Returning an unmodifiable view of all gadget positions using the values() method
    }

    public Map<String, Point> getStaticSnapshot() {
        Map<String, Point> snapshot = new LinkedHashMap<>(gadgets); // Creating a new map to store the static snapshot
        executor.submit(new Runnable() { // Submitting a runnable to the executor service that will update the positions of the gadgets and add them to the snapshot
            @Override
            public void run() {
                Collection<Point> points = getAllPositions(); // Getting all current positions using the getAllPositions() method
                snapshot.putAll(gadgets); // Adding the current positions to the snapshot
                points.forEach(point -> gadgets.remove(point.getId())); // Removing the current positions from the tracker to avoid concurrent modification
            }
        }).get(); // Waiting for the runnable to finish executing and returning the snapshot
        return Collections.unmodifiableMap(snapshot); // Returning an unmodifiable map of the static snapshot
    }

    public void fetchAllPositions(Consumer<Collection<Point>> consumer) {
        consumer.accept(getAllPositions()); // Calling the provided consumer with all current positions using the getAllPositions() method
    }

    private static class Point {
        private final int x;
        private final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public String getId() {
            return Integer.toString(x * y); // Returning a unique ID based on the coordinates to simplify the implementation of the tracker and the exception thrown by updatePosition()
        }
    }

