import java.util.*;
import java.util.concurrent.*;

public class DelegatingParcelTracker {
    private final ConcurrentHashMap<Long, AtomicReference<Position>> positions;
    private final Map<Long, Position> initialPositions;

    public DelegatingParcelTracker(Map<Long, Position> initialPositions) {
        this.initialPositions = new HashMap<>(initialPositions);
        this.positions = new ConcurrentHashMap<>();
        initialPositions.forEach((id, position) -> positions.putIfAbsent(id, new AtomicReference<>(position)));
    }

    public Position getPosition(Long id) {
        return positions.get(id).get();
    }

    public void setPosition(Long id, Position position) throws Exception {
        if (!initialPositions.containsKey(id)) {
            throw new Exception("Package with ID " + id + " does not exist");
        }

        final AtomicReference<Position> ref = positions.get(id);
        Position currentPosition = ref.get();
        Position newPosition = position;

        int attempts = 0;
        while (true) {
            attempts++;
            Position previousPosition = currentPosition;
            currentPosition = ref.updateAndGet((oldPosition) -> {
                if (!newPosition.equals(oldPosition)) {
                    throw new Exception("Failed to set position of package " + id);
                }
                return newPosition;
            });

            if (previousPosition == currentPosition || attempts > 10) {
                break;
            }
        }

        // Use a fixed thread pool to limit the number of threads
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> updateMaps());
        executor.shutdown();
    }

    private void updateMaps() {
        // Update all maps with the latest positions
        positions.forEach((id, ref) -> ref.updateAndGet(Position::get));
        initialPositions.replaceAll((id, position) -> getPosition(id));
    }

    public Map<Long, Position> getAllPositions() {
        // Return a live view of the positions map
        return positions;
    }

    public Map<Long, Position> getAllPositionsSnapshot() {
        // Return a static snapshot of the initialPositions and positions maps
        Map<Long, Position> result = new HashMap<>(initialPositions);
        result.putAll(positions);
        return Collections.unmodifiableMap(result);
    }

    public static void main(String[] args) {
        // Initialize the tracker with some initial positions
        Map<Long, Position> initialPositions = new HashMap<>();
        initialPositions.put(1L, new Position("A"));
        initialPositions.put(2L, new Position("B"));
        initialPositions.put(3L, new Position("C"));

        DelegatingParcelTracker tracker = new DelegatingParcelTracker(initialPositions);

        // Retrieve the positions of a package
        Long id1 = 1L;
        Position position1 = tracker.getPosition(id1);
        System.out.println("Package " + id1 + " is at: " + position1);

        // Update the position of another package
        try {
            Position newPosition2 = new Position("D");
            Long id2 = 3L;
            tracker.setPosition(id2, newPosition2);
            System.out.println("Package " + id2 + " is now at: " + newPosition2);
        } catch (Exception e) {
            // Handle the exception gracefully
            System.err.println("Error: " + e.getMessage());
        }

        // Retrieve all positions as a live view and a snapshot
        Map<Long, Position> livePositions = tracker.getAllPositions();
        Set<Long> packageIDs = livePositions.keySet();
        System.out.println("Live positions: " + packageIDs);

        Map<Long, Position> snapshotPositions = tracker.getAllPositionsSnapshot();
        System.out.println("Snapshot positions: " + snapshotPositions);
    }
}

