public class DelegatingParcelTracker {

    private final Map<String, AtomicReference<Position>> packagePositions = new ConcurrentHashMap<>();
    private final Set<String> initializedPackages = Sets.newCopyOnWriteSet();
    private final ExecutorService threadPool = Executors.newFixedThreadPool(3);

    public DelegatingParcelTracker(Map<String, Position> initialPositions) {
        for (Map.Entry<String, Position> entry : initialPositions.entrySet()) {
            packagePositions.put(entry.getKey(), new AtomicReference<>(entry.getValue()));
            initializedPackages.add(entry.getKey());
            threadPool.execute(() -> checkPackagePosition(entry.getKey()));
        }
    }

    public Position getPosition(String id) {
        return packagePositions.get(id).get();
    }

    public void setPosition(String id, Position position) {
        if (!initializedPackages.contains(id)) {
            throw new RuntimeException("Package not initialized: " + id);
        }
        AtomicReference<Position> ref = packagePositions.get(id);
        while (!ref.compareAndSet(position, ref.get())) { // atomic update with CAS
            Position current = ref.get();
            if (getCurrentPosition(current).equals(position)) { // check if concurrent update
                return; // avoid unnecessary thread contention
            }
            ref = packagePositions.get(id); // refresh reference
        }
    }

    public Collection<Position> getAllPositions() {
        return Collections.unmodifiableCollection(Maps.values(packagePositions));
    }

    public Map<String, Position> snapshot() {
        Map<String, Position> result = new LinkedHashMap<>(); // keep order of keys
        for (Map.Entry<String, AtomicReference<Position>> entry : packagePositions.entrySet()) {
            result.put(entry.getKey(), entry.getValue().get());
        }
        return Collections.unmodifiableMap(result);
    }

    private Position getCurrentPosition(Position position) { // helper method for setPosition()
        if (position instanceof TrackedPosition) {
            return ((TrackedPosition) position).getCurrentPosition();
        } else {
            return position;
        }
    }

    private void checkPackagePosition(String id) {
        while (true) { // poll until package is initialized or interrupted
            Position current = getPosition(id);
            if (!initializedPackages.contains(id)) { // package not initialized yet
                continue; // wait for initialization
            } else if (current instanceof TrackedPosition) { // position is being tracked
                Position newPosition = ((TrackedPosition) current).update();
                if (!getCurrentPosition(newPosition).equals(current)) { // update if necessary
                    setPosition(id, newPosition);
                }
            }
            return; // package position is up-to-date, no further action needed
        }
    }

    public static void main(String[] args) {
        Map<String, Position> initialPositions = Maps.newHashMap();
        initialPositions.put("P1", new FixedPosition(1));
        initialPositions.put("P2", new TrackedPosition(2));
        DelegatingParcelTracker tracker = new DelegatingParcelTracker(initialPositions);
        System.out.println("Initial positions: " + tracker.getAllPositions());
        Position p1Current = tracker.getPosition("P1");
        System.out.println("Get position (P1): " + p1Current);
        Position p2New = new FixedPosition(3); // should fail due to package not initialized yet
        try {
            tracker.setPosition("P2", p2New);
            fail(); // should not reach here due to exception
        } catch (RuntimeException e) {
            assertEquals("Package not initialized: P2", e.getMessage());
        }
        Position p2Current = tracker.getPosition("P2");
        System.out.println("Get position (P2): " + p2Current); // should return old position due to concurrent update detection
        tracker.threadPool.shutdown(); // shutdown thread pool at the end
    }
}

