class DelegatingParcelTracker implements ParcelTracker {
    final ConcurrentHashMap<Integer, Package> trackerMap = new ConcurrentHashMap<>();
    ExecutorService threadPool = Executors.newFixedThreadPool(2);

    @Override
    public void initTracker(int[] packageIds, Point[] initialPositions) {
        for (int I = 0; I < packageIds.length; i++) {
            trackerMap.put(packageIds[i], new Package(packageIds[i], initialPositions[i]));
        }
    }

    @Override
    public void assignPosition(int packageId, Point position) throws NoSuchElementException {
        Package oldValue = trackerMap.putIfAbsent(packageId, new Package(packageId, position));
        if (oldValue != null) {
            throw new NoSuchElementException("Package ID " + packageId + " does not exist");
        }
    }

    @Override
    public Collection<Point> getAllPositions() {
        return trackerMap.values().stream().map(Package::getPosition).collect(Collectors.toList());
    }

    @Override
    public Map<Integer, Point> getAllPositionsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(trackerMap));
    }

    class ThreadSafeGetter implements Callable<Collection<Point>> {
        Collection<Point> positions;

        ThreadSafeGetter(Collection<Package> packages) {
            this.positions = packages.stream().map(Package::getPosition).collect(Collectors.toList());
        }

        @Override
        public Collection<Point> call() throws Exception {
            return positions;
        }
    }

    @Override
    public Collection<Point> getAllPositionsLive() {
        Collection<Package> packages = trackerMap.values();
        Future<Collection<Point>> future = threadPool.submit(new ThreadSafeGetter(packages));
        try {
            return future.get();
        } catch (ExecutionException | InterruptedException e) {
            throw new RuntimeException("Failed to retrieve live positions", e);
        }
    }
}

class ParcelTracker {
    public interface ParcelTrackerFactory {
        ParcelTracker createTracker(int[] packageIds, Point[] initialPositions);
    }

    Map<Integer, Point> snapshot;
    ExecutorService threadPool = Executors.newFixedThreadPool(2);

    ParcelTracker(ParcelTrackerFactory factory) {
        this.snapshot = Collections.unmodifiableMap(factory.createTracker(new int[0], new Point[0]).getAllPositionsSnapshot());
    }

    Collection<Point> getAllPositions() {
        return snapshot.values();
    }

    Collection<Point> getAllPositionsLive() {
        Collection<Point> positions = threadPool.submit(() -> new DelegatingParcelTracker().getAllPositions()).tryLambda()
            .map(Function.identity())
            .orElseThrow(() -> new RuntimeException("Failed to retrieve live positions"));
        return Collections.unmodifiableCollection(positions);
    }
}

class ParcelTrackerExample {
    public static void main(String[] args) {
        int[] packageIds = { 1, 2, 3 };
        Point[] initialPositions = { new Point(0, 0), new Point(5, 7), new Point(8, 4) };
        ParcelTrackerFactory factory = (packageIds, initialPositions) -> {
            DelegatingParcelTracker tracker = new DelegatingParcelTracker();
            tracker.initTracker(packageIds, initialPositions);
            return tracker;
        };
        ParcelTracker parser = new ParcelTracker(factory);

        parser.assignPosition(1, new Point(2, 3)); // updates the tracker map and thread pool tasks
        Collection<Point> positions = parser.getAllPositions();
        System.out.println("Live positions: " + positions);
        System.out.println("Snapshot positions: " + parser.getAllPositions());
    }
}

