        }
    }

    @Override
    public void assignPosition(int packageId, Point position) throws NoSuchElementException {
        Package oldValue = trackerMap.putIfAbsent(packageId, new Package(packageId, position));
        if (oldValue != null) {
            throw new NoSuchElementException("Package ID " + packageId + " does not exist");
        }
    }

