public class DeadlockAvoidance {
    static final int MAX_PARCELS = 10;
    static final long LOCKER_TIMEOUT = TimeUnit.SECONDS.toNanos(3);
    static final long RANDOM_DELAY = TimeUnit.MILLISECONDS.toNanos(100);

    static class ParcelCount {
        int count;

        ParcelCount(int count) {
            this.count = count;
        }

        int addParcels(int parcels) {
            int newCount = count + parcels;
            if (newCount > MAX_PARCELS) {
                throw new NotEnoughItemsException("Source locker overflow");
            }
            return newCount;
        }
    }

    static class Locker implements Runnable {
        String name;
        Lock lock;
        int parcelCount;
        ExecutorService executor;

        Locker(String name, ExecutorService executor) {
            this.name = name;
            lock = new ReentrantLock();
            parcelCount = 0;
            this.executor = executor;
        }

        void moveParcels(Locker target, int quantity, long timeout) throws InterruptedException {
            boolean acquiredSource = false;
            boolean acquiredTarget = false;
            try {
                acquiredSource = lock.tryLock(timeout, TimeUnit.NANOSECONDS);
                if (!acquiredSource) {
                    return;
                }
                if (parcelCount < quantity) {
                    throw new NotEnoughItemsException("Not enough parcels in " + name);
                }
                acquiredTarget = target.lock.tryLock(timeout, TimeUnit.NANOSECONDS);
            } finally {
                if (acquiredSource && !acquiredTarget) {
                    lock.unlock();
                } else if (!acquiredSource && acquiredTarget) {
                    target.lock.unlock();
                }
            }
            if (acquiredSource && acquiredTarget) {
                int remaining = parcelCount - quantity;
                ParcelCount newParcelCount = new ParcelCount(remaining);
                lock.lock();
                try {
                    parcelCount = newParcelCount.addParcels(0);
                    target.parcelCount += quantity;
                } finally {
                    lock.unlock();
                }
                executor.execute(() -> moveParcels(target, remaining, timeout));
            }
        }

        void release() {
            executor.shutdownNow();
            lock.lock();
            try {
                parcelCount = 0;
            } finally {
                lock.unlock();
            }
        }
    }

    static class NotEnoughItemsException extends Exception {
        NotEnoughItemsException(String message) {
            super(message);
        }
    }

