        TimeUnit.SECONDS.sleep(2);
        sourceLocker.release();
        targetLocker.release();
    }

    static class StampedChronoLock extends StampedLock {
        long delay;

        StampedChronoLock(int fairnessLevel, TimeUnit timeUnit) {
            super(fairnessLevel, timeUnit);
            this.delay = 0;
        }

        void resetDelay() {
            delay = 0;
        }

