final class ParcelCount implements Serializable {
    private final int capacity;
    private int count;
    private final AtomicInteger pending = new AtomicInteger();

    public ParcelCount(int capacity) {
        this.capacity = capacity;
    }

    synchronized int take() {
        int c = count - 1;
        if (c < 0) throw new NoSuchElementException();
        count = c;
        return c;
    }

    synchronized void put(int qty) throws InterruptedException {
        int r = count + qty;
        int p = pending.getAndAdd(r > capacity ? (r - capacity) : 0);
        if (p > 0 || r <= capacity) {
            count = r;
            notifyAll();
        } else {
            LockSupport.parkNanos(this, nanos(1, MILLIS));
        }
    }

    int pending() { return pending.get(); }
}

final class Locker extends ReentrantLock {
    private final String name;
    private final ParcelCount count;

    public Locker(String name) {
        super();
        this.name = name;
        this.count = new ParcelCount(5);
    }

    synchronized int getCount() { return count.take(); }

    synchronized void putParcels(int qty) throws InterruptedException {
        count.put(qty);
        while (getPendingCount() > 0 && isHeldByCurrentThread()) {
            LockSupport.parkNanos(this, nanos(1, MILLIS));
        }
    }

    int getPendingCount() { return pending().asInt(); }
}

final class MoveTask implements Runnable {
    private final Locker src;
    private final Locker tar;
    private final int qty;
    private final long timeout;
    private final TimeUnit unit;
    private final Random rand = new Random(42L);

    public MoveTask(Locker src, Locker tar, int qty, long timeout, TimeUnit unit) {
        this.src = src;
        this.tar = tar;
        this.qty = qty;
        this.timeout = timeout;
        this.unit = unit;
    }

    @Override public void run() {
        long start = nanoTime();
        boolean success = false;
        try {
            Lock srcLock = this.src.tryLock(timeout, unit);
            Lock tarLock = this.tar.tryLock(timeout, unit);
            if (srcLock && tarLock) {
                int pending = Math.min(src.getPendingCount(), qty);
                int moved = src.getCount() - pending;
                if (moved >= qty) {
                    tar.putParcels(qty);
                    src.putParcels(pending);
                    success = true;
                } else {
                    throw new NotEnoughItemsException("source: " + moved + ", required: " + qty);
                }
            }
        } catch (InterruptedException | TimeoutException e) {
            // ignore
        } finally {
            if (!success && !isHeldByCurrentThread()) {
                Locker.unlockAll(Arrays.asList(src, tar));
            }
            long duration = nanoTime() - start;
            if (duration > 10_000_000L) {
                int delay = Math.max(0, (int)(rand.nextInt(256) * (duration / 100))) + 1;
                LockSupport.parkNanos(this, nanos(delay, MILLISECONDS));
            }
        }
    }
}

