        this.target = target;
        this.numElementsToSwap = numElementsToSwap;
        this.timeout = timeout;
        this.timeUnit = timeUnit;
        random = new Random();
    }

    @Override
    public void run() {
        boolean result = false;
        int fixedDelay = (int) Duration.ofSeconds(3).getSeconds();
        int randomDelay = (int) Math.round(random.nextDouble()) * 200;

        try (ExecutionService executor = Executors.newFixedThreadPool(2)) {
            Runnable originRunner = () -> {
                ElementCount elementCount = new ElementCount(origin.getElementCount());
                try {
                    executor.submit(() -> {
                        boolean success = false;
                        int attempts = 0;
                        do {
