                                try {
                                    if (origin.getElementCount() >= numElementsToSwap) {
                                        List<T> elementsToRemove = origin.elements.subList(0, numElementsToSwap);
                                        int originalSize = target.elements.size();
                                        target.addElementAll(elementsToRemove);
                                        int difference = target.elements.size() - originalSize;
                                        for (int I = 0; I < difference; i++) {
                                            origin.removeElement();
                                        }
                                        success = true;
                                    } else {
                                        Thread.sleep(10); // wait for a short time before retrying
                                    }
                                } finally {
                                    originLock.unlock();
                                }
                            } catch (InterruptedException e) {}
