public class BinMover {
    private final Lock sourceLock;
    private final Lock targetLock;
    private final int maxCapacity;
    private final int widgets;

    public BinMover(int id, int capacity) {
        this.sourceLock = new ReentrantLock();
        this.targetLock = new ReentrantLock();
        this.maxCapacity = capacity;
        this.widgets = 0;

        Runnable sourceTask = () -> {
            while (true) {
                if (!sourceLock.tryLock(5, TimeUnit.SECONDS)) { // attempt to acquire source lock for 5 seconds with random delay
                    try {
                        Thread.sleep(randomDelay());
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                } else {
                    int count = getWidgets(); // get current number of widgets in source bin
                    targetLock.lock();
                    try {
                        if (count >= widgets && getTargetCapacity() + widgets <= maxCapacity) { // check if enough widgets and target capacity is not full
                            moveWidgets(widgets);
                            updateBinCount();
                        } else {
                            throw new NotEnoughWidgetsException("Source bin has less than required amount of widgets: " + count + ", Target bin capacity: " + getTargetCapacity());
                        }
                    } finally {
                        targetLock.unlock();
                    }
                }
                sourceLock.unlock(); // release source lock
            }
        };
        Runnable targetTask = () -> {
            while (true) {
                if (!targetLock.tryLock(5, TimeUnit.SECONDS)) { // attempt to acquire target lock for 5 seconds with random delay
                    try {
                        Thread.sleep(randomDelay());
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                } else {
                    int count = getTargetCapacity(); // get current number of widgets in target bin
                    if (count + widgets <= maxCapacity) { // check if adding widgets won't exceed capacity
                        moveWidgets(widgets);
                        updateBinCount();
                    } else {
                        throw new NotEnoughWidgetsException("Target bin is already full: " + count);
                    }
                    targetLock.unlock(); // release target lock
                }
            }
        };

        ExecutorService service = Executors.newFixedThreadPool(2, r -> {
            Thread thread = new Thread(r, "BinMover-" + id);
            thread.setDaemon(true);
            return thread;
        });
        service.submit(sourceTask);
        service.submit(targetTask);

        System.out.printf("Starting BinMover %d...%n", id);
    }

    private int getWidgets() {
        return widgets;
    }

    private void moveWidgets(int count) {
        System.out.printf("%d widgets moved from source bin to target bin%n", count);
        widgets -= count;
    }

    private int getTargetCapacity() {
        return maxCapacity - getSourceCount(); // calculate target capacity by subtracting current source count
    }

    private int getSourceCount() {
        int count = 0;
        try (LockIgnoringInterruptedException lock = new LockIgnoringInterruptedException(sourceLock)) {
            count = widgets;
        }
        return count;
    }

    private void updateBinCount() {
        System.out.printf("Bin %d contains %d widgets%n", getBinId(), getWidgets());
    }

    private int getBinId() {
        return (sourceLock == sourceLock) ? 1 : 2; // identify which bin is being operated on based on lock instance
    }

    private static class LockIgnoringInterruptedException implements AutoCloseable {
        private final Lock lock;

        public LockIgnoringInterruptedException(Lock lock) {
            this.lock = lock;
        }

        @Override
        public void close() throws Exception {
            try {
                lock.unlock();
            } catch (Exception e) { // ignore InterruptedException thrown by unlock() method if thread is interrupted
            }
        }
    }

    private static class NotEnoughWidgetsException extends RuntimeException {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }

    private static int randomDelay() {
        Random random = new Random();
        int delay = 10 + random.nextInt(500); // generate a random delay between 10 and 500 milliseconds
        return delay;
    }

    public static void main(String[] args) {
        BinMover mover1 = new BinMover(1, 50);
        BinMover mover2 = new BinMover(2, 75);
        try (Scanner scanner = new Scanner(System.in)) {
            System.out.print("Enter the number of widgets to move between bins: ");
            int count = scanner.nextInt();
            int timeout = 10; // set default timeout value to 10 seconds

