import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Consumer;
import java.util.function.Function;

public class DeadlockAvoidanceBinMover {
    private static final int MAX_THREADS = 3;
    private static final ScheduledExecutorService scheduledExecutor = Executors.newSingleThreadScheduledExecutor(
            new ThreadFactory() {
                private int threadNumber = 1;
                @Override
                public Thread newThread(Runnable r) {
                    return new Thread(r, "thread-" + threadNumber++);
                }
            });

    static final class Bin implements Runnable {
        private String name;
        private int capacity;
        private Lock lock = new ReentrantLock();
        private Condition notFull = lock.newCondition();
        private List<WidgetCount> widgets = new ArrayList<>();

        public Bin(String name, int capacity) {
            this.name = name;
            this.capacity = capacity;
        }

        @Override
        public void run() {
            try {
                while (true) {
                    lock.lock();
                    try {
                        if (!widgets.isEmpty()) {
                            WidgetCount widgetToRemove = widgets.remove(widgets.size() - 1);
                            int remainingCapacity = capacity - widgets.stream().mapToInt(WidgetCount::getCount).sum();
                            if (remainingCapacity >= widgetToRemove.getCount()) {
                                System.out.printf("%s: Removed %d, now %d%n", name, widgetToRemove.getCount(), remainingCapacity);
                            } else {
                                lock.unlock();
                                notFull.signalAll();
                                throw new NotEnoughSpaceException("Insufficient space in " + name);
                            }
                        } else {
                            notFull.await(1, TimeUnit.SECONDS);
                        }
                    } finally {
                        lock.unlock();
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } catch (NotEnoughSpaceException e) {
                System.err.println(e.getMessage());
            }
        }

        public synchronized void addWidgets(List<WidgetCount> widgets) {
            int capacityChange = widgets.stream().mapToInt(WidgetCount::getCount).sum();
            if (capacity + capacityChange <= capacity) {
                this.widgets.addAll(widgets);
            } else {
                System.err.printf("%s: Cannot add %d, would exceed capacity of %d%n", name, capacityChange, capacity);
            }
        }
    }

    static final class WidgetCount {
        private int count;

        public WidgetCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }
    }

    static final class NotEnoughWidgetsException extends Exception {}

    static final class NotEnoughSpaceException extends Exception {}

    private static void moveWidgets(Bin source, Bin target, int widgetsToMove) throws InterruptedException, NotEnoughWidgetsException {
        Lock sourceLock = source.lock;
        Lock targetLock = target.lock;
        int tryTimeoutMs = 100;
        int maxRetries = 3;

        for (int retry = 0; ; ++retry) {
            boolean lockedSource = false;
            boolean lockedTarget = false;
            Future<?> releaseFuture = null;
            Future<?> moveFuture = null;

            try {
                // Acquire locks first, if one fails retry with timeout
                int delayMs = getDelayMs();
                Thread.sleep(delayMs);

                lockedSource = sourceLock.tryLock(delayMs, TimeUnit.MILLISECONDS);
                releaseFuture = scheduledExecutor.submit(() -> {
                    try {
                        lockedSource.unlock();
                    } catch (Exception e) {
                        System.err.printf("Error unlocking source bin: %s%n", e.getMessage());
                    }
                });

                if (!lockedSource || retry > maxRetries) {
                    throw new DeadlockException("Failed to acquire locks after " + maxRetries + " attempts");
                }

                lockedTarget = targetLock.tryLock(delayMs, TimeUnit.MILLISECONDS);
                moveFuture = scheduledExecutor.submit(() -> {
                    try {
                        int remainingWidgets = source.widgets.stream().mapToInt(WidgetCount::getCount).sum();
                        if (remainingWidgets < widgetsToMove) {
                            throw new NotEnoughWidgetsException("Insufficient number of widgets in source bin: " + remainingWidgets);
                        }

                        int movedWidgets = Math.min(widgetsToMove, remainingWidgets);
                        target.addWidgets(source.widgets.subList(0, movedWidgets).stream().map(WidgetCount::getCount).boxed().collect(ArrayList::new));
                        source.widgets.subList(0, movedWidgets).clear();
                    } catch (Exception e) {
                        System.err.printf("Error moving widgets from %s to %s: %s%n", source.name, target.name, e.getMessage());
                    } finally {
                        lockedTarget.unlock();
                    }
                });
            } catch (DeadlockException | NotEnoughWidgetsException e) {
                // Rollback if failed to acquire locks or insufficient widgets
                if (!lockedSource && !releaseFuture.isDone()) {
                    releaseFuture.cancel(true);
                }
                throw e;
            } finally {
                lockedSource.unlock();
                // Release source bin lock
                if (!releaseFuture.isDone() && lockedTarget) {
                    releaseFuture.cancel(true);
                }
            }

            // Wait for move to complete before releasing locks
            try {
                moveFuture.get(tryTimeoutMs, TimeUnit.MILLISECONDS);
            } catch (Exception e) {
                System.err.println("Error waiting for move completion: " + e.getMessage());
            } finally {
                releaseFuture.cancel(true);
                // Release source bin lock
                if (!releaseFuture.isDone() && lockedSource) {
                    releaseFuture.cancel(true);
                }
            }
        }
    }

    private static int getDelayMs() {
        Thread thread = Thread.currentThread();
        long nanos = System.nanoTime() % 10_000_000;
        int delayMs = (int) Math.min(Math.max((int) ((nanos / 1000) % 10), 1), 9); // [1, 9] ms
        try {
            Thread.sleep(delayMs);
        } catch (Exception e) {}
        return delayMs;
    }

    public static void main(String[] args) throws Exception {
        Bin source = new Bin("Source", 10);
        Bin target = new Bin("Target", 5);

        int widgetsToMove = 7;

        scheduledExecutor.execute(() -> moveWidgets(source, target, widgetsToMove));

        // Wait for moving to complete
        if (!moveFuture.isDone()) {
            moveFuture.get(1, TimeUnit.SECONDS);
        }

        System.out.println("Final contents of bins:");
        System.out.printf("Source bin:\n%s%n", source.widgets);
        System.out.printf("Target bin:\n%s%n", target.widgets);

        scheduledExecutor.shutdown();
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.IntConsumer;
import java.util.random.Random;
import java.util.stream.IntStream;

public class WidgetMover {
    static final int DEFAULT_TIMEOUT = 1000;
    static final int MAX_THREADS = 3;

    static class Bin {
        private final String name;
        private final AtomicInteger count = new AtomicInteger();
        private final ReentrantLock lock = new ReentrantLock();
        private final Condition notFull = lock.newCondition();
        private final Condition notEmpty = lock.newCondition();

        public Bin(String name) {
            this.name = name;
        }

        int getCount() {
            return count.get();
        }

        void incrementCount(int delta) {
            lock.lock();
            try {
                int current = count.get();
                count.set(current + delta);
                notEmpty.signalAll();
            } finally {
                lock.unlock();
            }
        }

        void decrementCount(int delta) {
            lock.lock();
            try {
                int current = count.get();
                if (current - delta < 0) {
                    throw new NotEnoughWidgetsException("Not enough widgets in bin " + name);
                }
                count.set(current - delta);
                notFull.signalAll();
            } finally {
                lock.unlock();
            }
        }

        boolean tryAcquireCount(int delta, long timeout, TimeUnit unit) throws InterruptedException, TimeoutException {
            lock.lock();
            try {
                int current = count.get();
                if (current - delta >= 0) {
                    count.set(current - delta);
                    notFull.signalAll();
                    return true;
                } else {
                    try {
                        long nanos = unit.convert(timeout, TimeUnit.NANOSECONDS);
                        if (notEmpty.awaitNanos(nanos)) {
                            int current2 = count.get();
                            if (current2 - delta >= 0) {
                                count.set(current2 - delta);
                                notFull.signalAll();
                                return true;
                            } else {
                                throw new NotEnoughWidgetsException("Bin " + name + " was emptied");
                            }
                        } else {
                            return false;
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        throw new InterruptedException("Interrupted waiting for bin " + name);
                    }
                }
            } finally {
                lock.unlock();
            }
        }
    }

    static class WidgetCount implements IntConsumer {
        private final int value;
        private final Bin sourceBin;
        private final Bin targetBin;

        public WidgetCount(int value, Bin sourceBin, Bin targetBin) {
            this.value = value;
            this.sourceBin = sourceBin;
            this.targetBin = targetBin;
        }

        @Override
        public void accept(int ignore) {
            tryMoveWidgets();
        }

        private void tryMoveWidgets() {
            boolean success = false;
            int retryCount = 0;
            while (!success && ++retryCount <= 10) {
                boolean sourceAcquired = false;
                boolean targetAcquired = false;
                long deadline = System.nanoTime() + DEFAULT_TIMEOUT;
                while (!sourceAcquired && !targetAcquired && System.nanoTime() < deadline) {
                    boolean sourceResult = sourceBin.tryAcquireCount(1, DEFAULT_TIMEOUT, TimeUnit.MILLISECONDS);
                    boolean targetResult = targetBin.tryAcquireCount(value, DEFAULT_TIMEOUT, TimeUnit.MILLISECONDS);
                    if (sourceResult && targetResult) {
                        success = true;
                    } else {
                        tryAcquireLocked(retryCount <= 5);
                    }
                    sourceAcquired = sourceResult;
                    targetAcquired = targetResult;
                }
                if (!success && retryCount < 10) {
                    Thread.sleep(getDelay(retryCount));
                }
            }
        }

        private int getDelay(int retryCount) {
            int fixedDelay = Math.min(Math.max(0, DEFAULT_TIMEOUT - (DEFAULT_TIMEOUT % 10)), DEFAULT_TIMEOUT / 2);
            return fixedDelay + Random.current().nextInt(retryCount <= 5 ? 5 : 10);
        }

        private void tryAcquireLocked(boolean shouldRetry) {
            boolean result = false;
            int retryCount = 0;
            long deadline = System.nanoTime() + DEFAULT_TIMEOUT;
            while (!result && System.nanoTime() < deadline) {
                boolean success = sourceBin.lockInterruptibly();
                boolean targetSuccess = targetBin.lockInterruptibly();
                if (success && targetSuccess) {
                    try {
                        int currentSource = sourceBin.getCount();
                        int currentTarget = targetBin.getCount();
                        if (currentSource - value >= 0 && currentTarget + value <= Bin.MAX_CAPACITY) {
                            result = true;
                        }
                        sourceBin.decrementCount(value);
                        targetBin.incrementCount(value);
                    } catch (InterruptedException | NotEnoughWidgetsException e) {
                        // Ignore and try again
                    } finally {
                        targetBin.unlock();
                        sourceBin.unlock();
                    }
                } else if (shouldRetry && retryCount < 10) {
                    Thread.sleep(getDelay(retryCount));
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        Bin sourceBin = new Bin("Source");
        Bin targetBin = new Bin("Target");
        IntStream.rangeClosed(1, 100).forEach(widget -> {
            executor.submit(new WidgetCount(widget, sourceBin, targetBin));
        });
        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(10);
        }
        System.out.println("Source: " + sourceBin.getCount());
        System.out.println("Target: " + targetBin.getCount());
    }
}

class NotEnoughWidgetsException extends Exception {
    NotEnoughWidgetsException(String message) {
        super(message);
    }
}

