        public WidgetCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }
    }

    static final class NotEnoughWidgetsException extends Exception {}

    static final class NotEnoughSpaceException extends Exception {}

    private static void moveWidgets(Bin source, Bin target, int widgetsToMove) throws InterruptedException, NotEnoughWidgetsException {
        Lock sourceLock = source.lock;
        Lock targetLock = target.lock;
        int tryTimeoutMs = 100;
        int maxRetries = 3;

        for (int retry = 0; ; ++retry) {
            boolean lockedSource = false;
            boolean lockedTarget = false;
            Future<?> releaseFuture = null;
            Future<?> moveFuture = null;

            try {
                // Acquire locks first, if one fails retry with timeout
                int delayMs = getDelayMs();
                Thread.sleep(delayMs);

                lockedSource = sourceLock.tryLock(delayMs, TimeUnit.MILLISECONDS);
                releaseFuture = scheduledExecutor.submit(() -> {
                    try {
                        lockedSource.unlock();
                    } catch (Exception e) {
                        System.err.printf("Error unlocking source bin: %s%n", e.getMessage());
                    }
                });

                if (!lockedSource || retry > maxRetries) {
                    throw new DeadlockException("Failed to acquire locks after " + maxRetries + " attempts");
                }

                lockedTarget = targetLock.tryLock(delayMs, TimeUnit.MILLISECONDS);
                moveFuture = scheduledExecutor.submit(() -> {
                    try {
                        int remainingWidgets = source.widgets.stream().mapToInt(WidgetCount::getCount).sum();
                        if (remainingWidgets < widgetsToMove) {
                            throw new NotEnoughWidgetsException("Insufficient number of widgets in source bin: " + remainingWidgets);
                        }

                        int movedWidgets = Math.min(widgetsToMove, remainingWidgets);
                        target.addWidgets(source.widgets.subList(0, movedWidgets).stream().map(WidgetCount::getCount).boxed().collect(ArrayList::new));
                        source.widgets.subList(0, movedWidgets).clear();
                    } catch (Exception e) {
                        System.err.printf("Error moving widgets from %s to %s: %s%n", source.name, target.name, e.getMessage());
                    } finally {
                        lockedTarget.unlock();
                    }
                });
            } catch (DeadlockException | NotEnoughWidgetsException e) {
                // Rollback if failed to acquire locks or insufficient widgets
                if (!lockedSource && !releaseFuture.isDone()) {
                    releaseFuture.cancel(true);
                }
                throw e;
            } finally {
                lockedSource.unlock();
                // Release source bin lock
                if (!releaseFuture.isDone() && lockedTarget) {
                    releaseFuture.cancel(true);
                }
            }

            // Wait for move to complete before releasing locks
            try {
                moveFuture.get(tryTimeoutMs, TimeUnit.MILLISECONDS);
            } catch (Exception e) {
                System.err.println("Error waiting for move completion: " + e.getMessage());
            } finally {
                releaseFuture.cancel(true);
                // Release source bin lock
                if (!releaseFuture.isDone() && lockedSource) {
                    releaseFuture.cancel(true);
                }
            }
        }
    }

    private static int getDelayMs() {
        Thread thread = Thread.currentThread();
        long nanos = System.nanoTime() % 10_000_000;
        int delayMs = (int) Math.min(Math.max((int) ((nanos / 1000) % 10), 1), 9); // [1, 9] ms
        try {
            Thread.sleep(delayMs);
        } catch (Exception e) {}
        return delayMs;
    }

    public static void main(String[] args) throws Exception {
        Bin source = new Bin("Source", 10);
        Bin target = new Bin("Target", 5);

        int widgetsToMove = 7;

        scheduledExecutor.execute(() -> moveWidgets(source, target, widgetsToMove));

        // Wait for moving to complete
        if (!moveFuture.isDone()) {
            moveFuture.get(1, TimeUnit.SECONDS);
        }

        System.out.println("Final contents of bins:");
        System.out.printf("Source bin:\n%s%n", source.widgets);
        System.out.printf("Target bin:\n%s%n", target.widgets);

        scheduledExecutor.shutdown();
    }
}

