class ServerStatusBeforeSplit {
    private Set<String> vehicles;
    private Set<String> events;
    private static final int MAX_THREADS = 3;
    private ExecutorService executorService = Executors.newFixedThreadPool(MAX_THREADS - 1);

    public ServerStatusBeforeSplit() {
        vehicles = new HashSet<>();
        events = new HashSet<>();
    }

    synchronized void addUser(String u) {
        vehicles.add(u);
    }

    synchronized void addQuery(String q) {
        events.add(q);
    }

    synchronized void removeUser(String u) {
        vehicles.remove(u);
    }

    synchronized void removeQuery(String q) {
        events.remove(q);
    }

    class Worker implements Runnable {
        private Runnable task;

        public Worker(Runnable task) {
            this.task = task;
        }

        @Override
        public void run() {
            try {
                task.run();
            } catch (Throwable e) {
                // Ignore exceptions to prevent thread pool shutdown
            } finally {
                executorService.shutdown();
            }
        }
    }

