public class PersonSet {
    private static final int MAX_THREADS = 3;
    private static final ExecutorService threadPool = Executors.newFixedThreadPool(MAX_THREADS - 1);

    interface Person {}

    static class Impl implements Person {
        String name, address;
        int age;

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof Impl)) return false;
            Impl other = (Impl) obj;
            return name.equals(other.name) && address.equals(other.address);
        }
    }

    private final Set<Person> persons = new HashSet<>();

    public synchronized void add(Person person) {
        persons.add(person);
    }

    public synchronized boolean contains(Person person) {
        return persons.contains(person);
    }

    // Threaded method to check if set contains a specific Person object
    public CompletableFuture<Boolean> containsAsync(Person person) {
        return threadPool.submit(() -> {
            boolean result = contains(person);
            threadPool.shutdown();
            return CompletableFuture.completedFuture(result);
        });
    }

    public static void main(String[] args) {
        PersonSet personSet = new PersonSet();

        // Thread #1: Adds multiple Person objects to the set asynchronously
        threadPool.submit(() -> {
            for (int i = 0; I < 20; i++) {
                String name = "Person" + i;
                int age = i % 10;
                personSet.add(new Impl().setName(name).setAge(age));
            }
        });

        // Thread #2: Verifies if set contains a specific Person object asynchronously
        threadPool.submit(() -> {
            boolean result = personSet.containsAsync(new Impl().setName("Person1").setAddress("Somewhere")).join();
            System.out.println("Contains Person1? " + result);
            threadPool.shutdown();
        });

        // Thread #3: Main thread
        try {
            TimeUnit.SECONDS.sleep(2);
        } catch (InterruptedException ignored) {}
        System.out.println("Finished initializing, shutting down thread pool...");
        threadPool.shutdown();
    }
}

