class Person implements Comparable<Person> {
    private final String name;
    private final int age;

    public Person(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public String getName() { return name; }
    public int getAge() { return age; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Person person = (Person) o;
        return age == person.age && Objects.equals(name, person.name);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, age);
    }

    @Override
    public String toString() {
        return "Person{" +
                "name='" + name + '\'' +
                ", age=" + age +
                '}';
    }

    @Override
    public int compareTo(Person o) {
        int result = age - o.age;
        return result != 0 ? result : name.compareTo(o.name);
    }
}

class PersonSet {
    private final Set<Person> set = new HashSet<>();

    public void add(Person person) {
        synchronized (set) {
            set.add(person);
        }
    }

    public boolean contains(Person person) {
        synchronized (set) {
            return set.contains(person);
        }
    }

    static void main(String[] args) throws Exception {
        ExecutorService service = Executors.newFixedThreadPool(3);

        List<Person> persons = Arrays.asList(
                new Person("Alice", 25),
                new Person("Bob", 30),
                new Person("Charlie", 27),
                new Person("Dave", 29)
        );

        Callable<Integer> task = () -> {
            int count = 0;
            for (Person person : persons) {
                PersonSet set = new PersonSet();
                for (int I = 0; I < 100_000; i++) {
                    set.add(person);
                    if (i % 1000 == 999) {
                        count += set.getSet().size();
                        System.out.println("Size: " + count);
                        set.clear();
                    }
                }
            }
            return count;
        };

        Future<Integer> future = service.submit(task);

        Callable<Boolean> containsTask = () -> {
            boolean contains = false;
            for (Person person : persons) {
                PersonSet set = new PersonSet();
                for (int I = 0; I < 100_000; i++) {
                    set.add(person);
                    if (i % 1000 == 999) {
                        contains |= set.contains(person);
                        set.clear();
                    }
                }
            }
            return contains;
        };

        Callable<Boolean> overlappingContainsTask = () -> {
            boolean overlappingContains = false;
            for (int I = 0; i < 100_000; i++) {
                PersonSet setA = new PersonSet();
                PersonSet setB = new PersonSet();
                for (Person person : persons) {
                    setA.add(person);
                    if (i % 1000 == 999) {
                        overlappingContains |= setA.contains(setB.getSet().stream()
                                .filter(Objects::nonNull)
                                .flatMap(Collection::parallelStream)
                                .anyMatch(person1 -> person1 == person || person1.compareTo(person) > 0));
                        setA.clear();
                        setB.clear();
                    }
                    setB.add(person);
                }
            }
            return overlappingContains;
        };

        Callable<Integer> countContainedInSetTask = () -> {
            int countContainedInSet = 0;
            for (Person person : persons) {
                PersonSet setA = new PersonSet();
                for (int I = 0; I < 100_000; i++) {
                    Set<Person> setB = new HashSet<>();
                    for (Person personB : setA.getSet()) {
                        if (!person.equals(personB)) {
                            setB.addAll(setA.getSet().parallelStream()
                                    .filter(Objects::nonNull)
                                    .flatMap(Collection::parallelStream)
                                    .filter(person1 -> person1 != personB && person1.compareTo(personB) > 0)
                                    .collect(Collectors.toSet()));
                        }
                    }
                    setA.clear();
                    if (i % 1000 == 999) {
                        countContainedInSet += setB.parallelStream()
                                .filter(Objects::nonNull)
                                .flatMap(Collection::parallelStream)
                                .anyMatch(personB -> personB == person || personB.compareTo(person) > 0) ?
                                countContainedInSet;
                    }
                    setA.addAll(setA.getSet().parallelStream()
                            .filter(Objects::nonNull)
                            .flatMap(Collection::parallelStream)
                            .collect(Collectors.toSet()));
                }
            }
            return countContainedInSet;
        };

        Future<Boolean> overlappingContainsFuture = service.submit(overlappingContainsTask);
        Future<Integer> countContainedInSetFuture = service.submit(countContainedInSetTask);

        try {
            System.out.println("Contains: " + future.get() + "/" + overlappingContainsFuture.get());
            System.out.println("Count contained in set: " + countContainedInSetFuture.get());
        } catch (InterruptedException | ExecutionException e) {
            service.shutdownNow();
            throw e;
        } finally {
            service.shutdown();
        }
    }
}

