import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

public class PublishingVehicleTracker {
    private final Map<String, SafePoint> positions = new ConcurrentHashMap<>();

    private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutorService();
    private final Runnable updatePositionsTask = () -> {
        for (Map.Entry<String, SafePoint> entry : positions.entrySet()) {
            entry.setValue(updatePosition(entry.getKey(), entry.getValue()));
        }
    };

    private final long updateIntervalSeconds = 3;

    public Collection<SafePoint> getPositions() {
        return Collections.unmodifiableCollection(positions.values());
    }

    public SafePoint getPosition(String id) {
        Objects.requireNonNull(id);
        return positions.get(id);
    }

    public void setPosition(String id, int x, int y) {
        SafePoint point = positions.putIfAbsent(id, new SafePoint(x, y));
        if (point != null) {
            positions.replace(id, updatePosition(id, point));
        }
    }

    private SafePoint updatePosition(String id, SafePoint current) {
        int dx = current.getX() + 1; // Simulate movement
        int dy = current.getY() + 2;
        return new SafePoint(dx, dy);
    }

    public void start() {
        scheduler.scheduleAtFixedRate(updatePositionsTask, 0, updateIntervalSeconds, TimeUnit.SECONDS);
    }

    public void stop() {
        scheduler.shutdownNow();
    }

    private static class SafePoint {
        private final int x;
        private final int y;

        SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == this) {
                return true;
            } else if (! (obj instanceof SafePoint)) {
                return false;
            } else {
                SafePoint other = (SafePoint) obj;
                return x == other.x && y == other.y;
            }
        }

        @Override
        public int hashCode() {
            int result = 17;
            result = 31 * result + x;
            result = 31 * result + y;
            return result;
        }
    }

    private static class PositionUpdater<K, V> implements BiFunction<K, V, V>, Consumer<V>, Supplier<V> {
        private final Function<V, V> updater;

        public PositionUpdater(Function<V, V> updater) {
            this.updater = Objects.requireNonNull(updater);
        }

        @Override
        public V apply(K key, V value) {
            return updater.apply(value);
        }

        @Override
        public void accept(V value) {
            if (value != null) {
                value = updater.apply(value);
            }
        }

        @Override
        public V get() {
            return updater.apply(null);
        }
    }
}

