class PublishingVehicleTracker implements Runnable {
    private final Map<String, SafePoint> positions = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(3);

    public void start() {
        executorService.submit(this);
    }

    @Override
    public void run() {
        try (Stream<String> lines = getClass().getResourceAsStream("input.txt").lines()) {
            lines.map(line -> line.split(" ")).map(parts -> new SafePoint(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]))).limit(10)
                    .forEach(point -> {
                        String id = UUID.randomUUID().toString();
                        positions.putIfAbsent(id, point);
                        executorService.submit(() -> updatePositions());
                    });
            lines.close();
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
            System.exit(1);
        }
    }

    private void updatePositions() {
        try (Stream<Map.Entry<String, SafePoint>> entries = positions.entrySet().stream()) {
            Random rand = ThreadLocalRandom.current();
            entries.forEach(entry -> {
                SafePoint point = entry.getValue();
                int dx = rand.nextInt(10) - 5;
                int dy = rand.nextInt(10) - 5;
                int newX = Math.max(Math.min(point.getX() + dx, 100), 0);
                int newY = Math.max(Math.min(point.getY() + dy, 100), 0);
                entry.setValue(new SafePoint(newX, newY));
            });
        } catch (Exception e) {
            System.err.println("Error updating positions: " + e.getMessage());
            System.exit(1);
        }
    }

    public Map<String, SafePoint> getPositions() {
        return Collections.unmodifiableMap(positions);
    }

    public SafePoint getPosition(String id) {
        return positions.get(id).orElseThrow(() -> new NoSuchElementException("No such vehicle: " + id));
    }
}

