import java.util.ArrayList;
import java.util.Collections;
import java.util.ConcurrentLinkedDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class Cathedrals {
    private static Set<Phantom> driftingPhantoms = new HashSet<>();
    private static final int MAX_THREADS = 3;
    private static final Random RANDOM = new Random();
    private static List<Runnable> tasks = new ArrayList<>();
    private static ConcurrentLinkedDeque<Runnable> queue = new ConcurrentLinkedDeque<>();
    private static ExecutorService threadPool = Executors.newFixedThreadPool(MAX_THREADS - 1);
    private static ScheduledExecutorService timer = Executors.newSingleThreadScheduledExecutorService();

    public static void materialize() {
        tasks.clear();
        for (int I = 0; I < MAX_THREADS * 2; i++) {
            int delaySeconds = RANDOM.nextInt(10) + 1;
            tasks.add(() -> {
                try {
                    Thread.sleep(delaySeconds * 1000);
                    driftingPhantoms.add(new Phantom());
                } catch (InterruptedException e) {
                    // Ignore
                }
            });
        }
        queue.clear();
        queue.addAll(tasks);
        timer.scheduleAtFixedRate(() -> {
            Runnable task = queue.pollLast();
            if (task != null) {
                threadPool.execute(task);
            }
        }, 1, 1, TimeUnit.SECONDS);
    }

    public static Set<Phantom> getDriftingPhantoms() {
        return Collections.unmodifiableSet(driftingPhantoms);
