import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.stream.*;

enum Constellation { SOLAR, LUNAR, ASTRAL }
enum Resonance { POSITIVE, NEGATIVE }

class Rune implements Comparable<Rune> {
    private final Constellation constellation;
    private final Resonance resonance;

    Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }

    Constellation getConstellation() { return constellation; }
    Resonance getResonance() { return resonance; }

    @Override
    public int compareTo(Rune other) {
        int result = Constellation.compare(constellation, other.constellation);
        return result == 0 ? Constellation.compare(Constellation.SOLAR.equals(constellation), Constellation.SOLAR.equals(other.constellation)) : result;
    }
}

class Harmony implements Comparable<Harmony> {
    private final List<Rune> runes;

    Harmony(List<Rune> runes) {
        this.runes = new ArrayList<>(runes);
        Collections.sort(runes, (a, b) -> Integer.compare(Constellation.SOLAR.equals(a.getConstellation()) ^ Constellation.SOLAR.equals(b.getConstellation()), Constellation.SOLAR.equals(a.getConstellation()) ^ Constellation.SOLAR.equals(b.getConstellation()) ? Integer.compare(Resonance.POSITIVE.equals(a.getResonance()), Resonance.POSITIVE.equals(b.getResonance())) : 0);
    }

    List<Rune> getRunes() { return runes; }

    @Override
    public int compareTo(Harmony other) {
        return Integer.compare(runes.size(), other.runes.size());
    }
}

class Grimoire {
    private final List<Rune> harmonies = new ArrayList<>();

    void addRunes(List<Rune> runes) {
        for (int I = 0; I < runes.size(); i++) {
            int j = I + 1;
            while (j < runes.size() && Constellation.equals(runes.get(i).getConstellation(), runes.get(j).getConstellation()) && Resonance.equals(runes.get(i).getResonance(), runes.get(j).getResonance())) {
                j++;
            }
            List<Rune> subList = runes.subList(I, j);
            if (!subList.isEmpty()) {
                harmonies.add(new Harmony(subList));
                I = --j; // Move j back to compare with the next element in the original list
            }
        }
    }

    List<Harmony> getHarmonies() { return new ArrayList<>(harmonies); }
}

class HarmonyChecker implements Callable<Integer>, Comparable<HarmonyChecker> {
    private final Rune[] candidates;
    private int count = 0;
    private boolean started = false;

    HarmonyChecker(Rune[] candidates) {
        this.candidates = Arrays.copyOf(candidates, candidates.length);
    }

    @Override
    public int compareTo(HarmonyChecker other) {
        return Integer.compare(Arrays.stream(candidates).mapToInt(Rune::hashCode).sum(), Arrays.stream(other.candidates).mapToInt(Rune::hashCode).sum());
    }

    @Override
    public Integer call() throws Exception {
        started = true;
        return channelTheGrimoire(Arrays.copyOf(candidates, candidates.length));
    }

    int getCount() { return count; }
}

int channelTheGrimoire(Rune[] candidateRunes) {
    List<Rune> harmonies = new ArrayList<>();
    CandidateComparator comparator = new CandidateComparator();
    Arrays.sort(candidateRunes, comparator);
    for (int I = 0; I < candidateRunes.length - 1; i++) {
        int j = i + 1;
        while (j < candidateRunes.length && Constellation.equals(candidateRunes[i].getConstellation(), candidateRunes[j].getConstellation()) && Resonance.equals(candidateRunes[i].getResonance(), candidateRunes[j].getResonance())) {
            j++;
        }
        List<Rune> subList = Arrays.copyOfRange(candidateRunes, i, j);
        if (!subList.isEmpty()) {
            harmonies.add(new Harmony(subList));
            i = --j; // Move j back to compare with the next element in the original list
        }
    }
    return harmonies.size();
}

class CandidateComparator implements Comparator<Rune> {
    @Override
    public int compare(Rune o1, Rune o2) {
        int result = Constellation.compare(o1.getConstellation(), o2.getConstellation());
        return result == 0 ? Constellation.compare(Constellation.SOLAR.equals(o1.getConstellation()), Constellation.SOLAR.equals(o2.getConstellation())) : result;
    }
}

public class RuneHarmony {
    private static final ExecutorService executor = Executors.newFixedThreadPool(3);
    private static final Random random = ThreadLocalRandom.current();

    public static void main(String[] args) {
        Grimoire grimoire = new Grimoire();
        int numRunes = 10;
        List<Rune> runes = IntStream.rangeClosed(1, numRunes).mapToObj(i -> new Rune(random.nextBoolean() ? Constellation.SOLAR : random.nextBoolean() ? Constellation.LUNAR : Constellation.ASTRAL, random.nextBoolean() ? Resonance.POSITIVE : Resonance.NEGATIVE)).collect(Collectors.toList());
        executor.submit(new HarmonyChecker(runes.subList(0, numRunes / 2).toArray(Rune[]::new))).call();
        executor.submit(new HarmonyChecker(Arrays.copyOfRange(runes.subList(numRunes / 2, numRunes).toArray(Rune[]::new), numRunes - numRunes / 2, numRunes))).call();
