import java.util.concurrent.*;
import java.util.stream.Collectors;

enum Constellation {
    FIRE, WATER, AIR, EARTH
}

enum Resonance {
    POSITIVE, NEGATIVE
}

class Rune {
    private Constellation constellation;
    private Resonance resonance;

    public Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }

    Constellation getConstellation() {
        return constellation;
    }

    Resonance getResonance() {
        return resonance;
    }
}

class Harmony implements Comparable<Harmony> {
    private List<Rune> runes = new ArrayList<>();

    public Harmony(List<Rune> runes) {
        this.runes = runes;
    }

    int getSize() {
        return runes.size();
    }

    List<Rune> getRunes() {
        return runes;
    }

    @Override
    public int compareTo(Harmony o) {
        // Compare rune constellation first, then resonance
        int result = Constellation.compare(getConstellation(), o.getConstellation());
        return result != 0 ? result : Resonance.compare(getRunes().get(getRunes().size() - 1).getResonance(), o.getRunes().get(o.getRunes().size() - 1).getResonance());
    }

    Constellation getConstellation() {
        return runes.get(0).getConstellation();
    }
}

class Grimoire {
    private List<Harmony> harmonies = new ArrayList<>();

    public void addHarmony(Harmony harmony) {
        // Add harmony to grimoire, preserving order
        int index = binarySearch(harmonies, (o) -> o.getConstellation().compareTo(harmony.getConstellation()) == 0);
        harmonies.addAll(index, harmony);
    }

    private int binarySearch(List<Harmony> list, Comparator<Harmony> comparator) {
        int left = 0;
        int right = list.size() - 1;
        while (left <= right) {
            int middle = left + (right - left) / 2;
            int result = comparator.compare(list.get(middle), null);
            if (result == 0) {
                return middle;
            } else if (result < 0) {
                left = middle + 1;
            } else {
                right = middle - 1;
            }
        }
        return left;
    }

    int getSize() {
        return harmonies.size();
    }

    List<Harmony> getHarmonies() {
        return harmonies;
    }
}

