        this.runes = Collections.unmodifiableList(new ArrayList<>(runes));
        harmonyIndex = calculateHarmonyIndex();
    }

    private int calculateHarmonyIndex() {
        int index = 0;
        for (int I = 1; I < runes.size(); i++) {
            Rune currentRune = runes.get(i);
            Rune previousRune = runnes.get(i - 1);
            if (currentRune.constellation != previousRune.constellation || currentRune.resonance != Resonance.opposite(previousRune.resonance)) {
                return index;
            }
            index++;
        }
        return index;
    }

    @Override
    public int compareTo(Harmony o) {
