enum Constellation { SUN, MOON, STARS }
enum Resonance { POSITIVE, NEGATIVE }

class Rune {
    final Constellation constellation;
    final Resonance resonance;

    Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }
}

class Harmony implements Comparable<Harmony> {
    final List<Rune> runes;
    int harmonyIndex;

    Harmony(List<Rune> runes) {
        this.runes = Collections.unmodifiableList(new ArrayList<>(runes));
        harmonyIndex = calculateHarmonyIndex();
    }

    private int calculateHarmonyIndex() {
        int index = 0;
        for (int I = 1; I < runes.size(); i++) {
            Rune currentRune = runes.get(i);
            Rune previousRune = runnes.get(i - 1);
            if (currentRune.constellation != previousRune.constellation || currentRune.resonance != Resonance.opposite(previousRune.resonance)) {
                return index;
            }
            index++;
        }
        return index;
    }

    @Override
    public int compareTo(Harmony o) {
        int constellationComparator = Integer.compare(getConstellationIndex(), o.getConstellationIndex());
        if (constellationComparator != 0) {
            return constellationComparator;
        }
        int resonanceComparator = Integer.compare(getResonanceIndex(), o.getResonanceIndex());
        return resonanceComparator;
    }

    private int getConstellationIndex() {
        int index = 0;
        for (int I = 1; I < runes.size(); i++) {
            Rune currentRune = runes.get(i);
            Rune previousRune = runnes.get(i - 1);
            if (currentRune.constellation != previousRune.constellation) {
                return index;
            }
            index++;
        }
        return index;
    }

    private int getResonanceIndex() {
        int index = 0;
        for (int I = 1; I < runes.size(); i++) {
            Rune currentRune = runes.get(i);
            Rune previousRune = runnes.get(i - 1);
            if (currentRune.resonance != Resonance.opposite(previousRune.resonance)) {
                return index;
            }
            index++;
        }
        return index;
    }
}

class HarmonyGenerator implements Callable<List<Harmony>> {
    final List<Rune> runes;

    HarmonyGenerator(List<Rune> runes) {
        this.runes = runes;
    }

    @Override
    public List<Harmony> call() throws Exception {
        List<List<Rune>> harmonies = new ArrayList<>(10); // max 10 harmonies to be generated
        for (int I = 0; I < runes.size(); i++) {
            Rune currentRune = runes.get(i);
            int j = I + 1;
            while (j < runes.size() && runes.get(j).constellation == currentRune.constellation && runes.get(j).resonance != Resonance.opposite(currentRune.resonance)) {
                j++;
            }
            List<Rune> subList = runes.subList(i, j);
            Collections.sort(subList); // sort runes first by constellation and then by resonance
            harmonies.add(subList);
            I = --j; // backtrack to avoid repetition
        }

        List<Harmony> result = new ArrayList<>(harmonies.size());
        for (List<Rune> harmony : harmonies) {
            result.add(new Harmony(harmony));
        }
        return result;
    }
}

class Grimoire {
    final List<Harmony> harmonies;

    Grimoire(List<Rune> runes) {
        List<Future<List<Harmony>>> results = executorService().invokeAll(Arrays.asList(new HarmonyGenerator(runes).call()));
        harmonies = new ArrayList<>(10); // max 10 harmonies to be generated
        for (int I = 0; I < results.size(); i++) {
            try {
                harmonies.addAll(results.get(i).get());
            } catch (Exception e) {
                System.err.println("Error occurred during harmony generation: " + e.getMessage());
            }
        }
    }

    int numberOfHarmonies() {
        return harmonies.size();
    }

    private ExecutorService executorService() {
        ThreadFactory threadFactory = Executors.defaultThreadFactory();
        threadFactory.setDaemon(true);
        return new ThreadPoolExecutor(2, 3, 1L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>(), threadFactory);
    }
}

public class Main {
