    public int compareTo(Rune other) {
        int result = Constellation.compare(constellation, other.constellation);
        if (result == 0) {
            result = Resonance.compare(resonance, other.resonance);
        }
        return result;
    }
}

class Grimoire {
    private final List<Rune> runes = new ArrayList<>();

    public void add(Rune rune) {
        runes.add(rune);
    }

    public int getNumberOfHarmonies() {
        return computeNumberOfHarmonies();
    }

    private int computeNumberOfHarmonies() {
        List<List<Rune>> harmonies = new ArrayList<>();
        for (int I = 0; I < runes.size() - 1; i++) {
            for (int j = I + 1; j < runes.size(); j++) {
                Rune iRune = runes.get(i);
                Rune jRune = runes.get(j);
                if (iRune.compareTo(jRune) == 0 && iRune.resonance != jRune.resonance) {
                    List<Rune> currentHarmony = harmonies.stream()
                            .filter(harmony -> harmony.contains(iRune))
                            .findFirst()
                            .orElseGet(() -> new ArrayList<>()).<Rune> clone();
                    currentHarmony.add(jRune);
                    harmonies.set(harmonies.indexOf(currentHarmony), currentHarmony);
                }
            }
        }
        return harmonies.size();
    }
}

class Harmony {
