class Harmonizer implements Runnable {
    private final Grimoire grimoire;
    private final List<Rune> candidates;

    public Harmonizer(Grimoire grimoire, List<Rune> candidates) {
        this.grimoire = grimoire;
        this.candidates = candidates;
    }

    @Override
    public void run() {
        int numberOfHarmonies = computeNumberOfHarmonies();
        int addedHarmonies = grimoire.getNumberOfHarmonies() - numberOfHarmonies;
        grimoire.addAll(candidates);
        int totalHarmonies = grimoire.getNumberOfHarmonies() - addedHarmonies;
        System.out.println("Total harmonies: " + totalHarmonies);
    }

    private int computeNumberOfHarmonies() {
        ExecutorService threadPool = Executors.newFixedThreadPool(2);
        List<Future<Integer>> results = new ArrayList<>();

        int startIndex = 0;
        int endIndex = candidates.size();
        for (int I = 1; I <= candidates.size() / 2; i++) {
            int middleIndex = startIndex + i * ((endIndex - startIndex) >> 1);
            results.add(threadPool.submit(() -> computeNumberOfHarmoniesForRange(grimoire, candidates.subList(startIndex, middleIndex), candidates.subList(middleIndex + 1, endIndex))));
            startIndex = middleIndex + 1;
        }
        int numberOfHarmonies = results.stream()
                .mapToInt(Future::get)
                .sum();

        threadPool.shutdownNow();
        return numberOfHarmonies;
    }

    private int computeNumberOfHarmoniesForRange(Grimoire grimoire, List<Rune> firstCandidates, List<Rune> secondCandidates) {
        List<List<Rune>> harmonies = new ArrayList<>();
        for (int I = 0; I < firstCandidates.size() - 1; i++) {
            for (int j = I + 1; j < firstCandidates.size(); j++) {
                Rune firstRune = firstCandidates.get(i);
                Rune secondRune = secondCandidates.get(j);
                if (firstRune.compareTo(secondRune) == 0 && firstRune.resonance != secondRune.resonance) {
                    List<Rune> currentHarmony = harmonies.stream()
                            .filter(harmony -> harmony.contains(firstRune))
                            .findFirst()
                            .orElseGet(() -> new ArrayList<>()).<Rune> clone();
                    currentHarmony.addAll(Arrays.asList(firstRune, secondRune));
                    harmonies.set(harmonies.indexOf(currentHarmony), currentHarmony);
                }
            }
        }

        List<Harmony> finalHarmonies = harmonies.stream()
                .map(List::stream)
                .flatMapToInt(Stream::count)
                .asIntStream()
                .mapToObj(i -> new Harmony(harmonies.get(i)))
                .collect(Collectors.toList());
        int addedHarmonies = grimoire.getNumberOfHarmonies() - harmonies.size();
        grimoire.addAll(finalHarmonies);
        int totalHarmonies = grimoire.getNumberOfHarmonies() - addedHarmonies;
        return totalHarmonies;
    }
}

