    Crimble(int twine, int glint) {
        this.twine = twine;
        this.glint = glint;
    }

    @Override
    public void run() {
        Random rand = new Random();
        int x = rand.nextInt(20);
        int y = rand.nextInt(15);
        System.out.println("Crimble at (" + x + ", " + y + ") with twine=" + twine + " and glint=" + glint);
    }
}

class Swirl implements Runnable {
    public final int centerX, centerY;

    Swirl(int centerX, int centerY) {
        this.centerX = centerX;
        this.centerY = centerY;
    }

    @Override
    public void run() {
        Random rand = new Random();
        int x = rand.nextInt(20);
        int y = rand.nextInt(15);
        int radius = Math.abs(x - centerX) + Math.abs(y - centerY);
        if (radius <= 5) { // within swirling region
            Crimble c1 = new Crimble(centerX, centerY);
            Crimble c2 = new Crimble(centerX - x, centerY - y);
            ExecutorService executor = Executors.newFixedThreadPool(2);
            executor.submit(c1).get();
            executor.submit(c2).get();
            executor.shutdown(); // shut down thread pool after all tasks finished
        }
    }
}

public class Main {
    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(5);
        List<Swirl> swirls = new ArrayList<>();
        int centerX1 = 5, centerY1 = 5;
        int centerX2 = 15, centerY2 = 10;
        int centerX3 = 5, centerY3 = 15;
        swirls.add(new Swirl(centerX1, centerY1));
        swirls.add(new Swirl(centerX2, centerY2));
        swirls.add(new Swirl(centerX3, centerY3));
        for (Swirl s : swirls) {
            executor.submit(s);
        }
        executor.shutdown(); // shut down thread pool after all tasks finished
    }
}

