public class MysticBeastTracker {
    private final ConcurrentHashMap<String, Glyph> beastPerches = new ConcurrentHashMap<>();
    private final Map<String, List<Runnable>> perchUpdaters = new ConcurrentHashMap<>();
    private static final ThreadPoolExecutor threadPoolExecutor = (ThreadPoolExecutor) Executors.newFixedThreadPool(6);

    public MysticBeastTracker(Map<String, Glyph> beastPerches) {
        this.beastPerches.putAll(beastPerches);
        perchUpdaters.putAll(beastPerches.keySet().stream()
                .map(k -> Arrays.asList(new UpdatePerchTask(k)))
                .collect(Collectors.groupingBy(List::size, Collectors.mapping(List::get, Collectors.toList()))));
    }

    public Map<String, Glyph> getPerches() {
        return new HashMap<>(beastPerches);
    }

    public Glyph getPerch(String sigil) {
