    private static class UpdatePerchTask implements Runnable {
        private final String sigil;
        private int spark, glimmer;

        UpdatePerchTask(String sigil, int spark, int glimmer) {
            this.sigil = sigil;
            this.spark = spark;
            this.glimmer = glimmer;
        }

        UpdatePerchTask(String sigil) {
            this.sigil = sigil;
            this.spark = beastPerches.get(sigil).getSpark();
            this.glimmer = beastPerches.get(sigil).getGlimmer();
        }

        @Override
        public void run() {
            setPerch(sigil, spark, glimmer);
        }
    }

    private static class Glyph {
        int spark, glimmer;

        public Glyph(int spark, int glimmer) {
            this.spark = spark;
            this.glimmer = glimmer;
