        public int getGlimmer() {
            return glimmer;
        }

        public void setGlimmer(int glimmer) {
            this.glimmer = glimmer;
        }
    }

    private static class SetPerchTask implements BiConsumer<String, Glyph> {
        private String sigil;
        private int spark, glimmer;

        SetPerchTask(String sigil, int spark, int glimmer) {
            this.sigil = sigil;
            this.spark = spark;
            this.glimmer = glimmer;
        }

        @Override
        public void accept(String sigil, Glyph glyph) {
            beastPerches.put(sigil, new Glyph(spark, glimmer));
            List<Runnable> updaters = perchUpdaters.getOrDefault(sigil, Collections.emptyList());
            updaters.forEach(threadPoolExecutor::submit);
            perchUpdaters.computeIfPresent(sigil, (k, v) -> {
                List<Runnable> newUpdaters = new ArrayList<>(v);
                newUpdaters.addAll(Arrays.asList(new UpdatePerchTask(sigil, spark, glimmer)));
                return newUpdaters;
            });
        }
    }

    public void setPerch(String sigil, int spark, int glimmer) {
