import org.slf4j.LoggerFactory;

public class MysticBeastTracker {
    private static final int MAX_THREADS = 6;
    private static final Logger LOGGER = LoggerFactory.getLogger(MysticBeastTracker.class);

    // internal concurrent map used to store beast sigils and their perches
    private final ConcurrentMap<String, Glyph> beastPerches = new ConcurrentHashMap<>();

    // constructor method to add initial beast sigils and their perches to the internal concurrent map
    public MysticBeastTracker(Map<String, Glyph> initialBeasts) {
        this.beastPerches.putAll(initialBeasts);
    }

    // method to get an unmodifiable view of the current beast perches
    public Collection<Glyph> getPerches() {
        return Collections.unmodifiableCollection(this.beastPerches.values());
    }

    // method to get the current perch of a beast with the specified sigil or null if not found
    public Glyph getPerch(String sigil) {
        return this.beastPerches.get(Objects.requireNonNull(sigil));
    }

    // method to set the new coordinates for an existing beast's perch
    public void setPerch(String sigil, int spark, int glimmer) {
        Glyph oldGlyph = this.beastPerches.putIfAbsent(sigil, new Glyph(spark, glimmer));
        if (oldGlyph != null && !Objects.equals(oldGlyph, this.beastPerches.get(sigil))) {
            this.beastPerches.replace(sigil, oldGlyph, new Glyph(spark, glimmer));
        }
    }

    // method to capture a snapshot of the current beast perches as an unmodifiable Map
    public Map<String, Glyph> getPerchesAsStatic() {
        return this.beastPerches.entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a, ConcurrentHashMap::new));
    }

    // inner class Glyph to represent the coordinates of a perch
    static final class Glyph {
        private int spark;
        private int glimmer;

        public Glyph(int spark, int glimmer) {
            this.spark = spark;
            this.glimmer = glimmer;
        }

        // accessor methods for the perch coordinates
        public int getSpark() { return this.spark; }
        public int getGlimmer() { return this.glimmer; }
    }

    // static main method used as the entry point of the program
    public static void main(String[] args) throws Exception {
        // create initial beast sigils and their perches
        Map<String, Glyph> initialBeasts = IntStream.rangeClosed(1, 20)
                .mapToObj(i -> new Beast(i))
                .collect(Collectors.toMap(Beast::getSigil, beast -> {
                    int spark = RandomUtils.nextInt(100);
                    int glimmer = RandomUtils.nextInt(100);
                    LOGGER.debug("Initializing {} with perch ({}, {})", beast.getName(), spark, glimmer);
                    return new Glyph(spark, glimmer);
                }));
        // create a fixed thread pool to manage additional threads
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS - 1);
        // spawn tasks to move beasts randomly and periodically
        Set<Future<?>> movingTasks = executor.submit(new MoveBeastsRandomlyTask()).get().handle((result, throwable) -> {
            if (throwable != null) {
                LOGGER.warn("Failed to submit moving tasks: {}", throwable.getMessage());
            }
            return result;
        }).get();
        Future<?> movingTasksTimeout = executor.submit(() -> {
            try {
                Thread.sleep(500); // sleep for half a second before terminating
            } catch (InterruptedException e) {
                LOGGER.warn("Thread interrupted while moving beasts periodically: {}", e.getMessage());
            } finally {
                executor.shutdownNow(); // terminate thread pool and interrupt any pending tasks
            }
        });
        try {
            // wait for all moving tasks to complete, then return the snapshot of beast perches
            Map<String, Glyph> finalPerches = getPerchesAsStatic();
            movingTasksTimeout.get(500, TimeUnit.MILLISECONDS); // terminate if moving tasks do not finish in 500 ms
            return finalPerches;
        } finally {
            // interrupt and wait for any remaining background threads to complete
            movingTasks.forEach(Future::cancel);
            executor.shutdownNow();
            movingTasksTimeout.get(); // wait for any remaining moving tasks to finish, then terminate thread pool and interrupt any pending tasks
        }
    }

    // inner class MoveBeastsRandomlyTask used to move beasts randomly in the background
    static final class MoveBeastsRandomlyTask implements Runnable {
        @Override
        public void run() {
            while (!Thread.currentThread().isInterrupted()) {
                Set<String> movedBeasts = new HashSet<>();
                // move each beast randomly and update the internal map atomically
                for (String sigil : MysticBeastTracker.this.beastPerches.keySet()) {
                    Glyph currentGlyph = MysticBeastTracker.this.beastPerches.get(sigil);
                    int newSpark = RandomUtils.nextInt(100);
                    int newGlimmer = RandomUtils.nextInt(100);
                    Glyph newGlyph = new Glyph(newSpark, newGlimmer);
                    MysticBeastTracker.this.beastPerches.replace(sigil, currentGlyph, newGlyph);
                    if (!Objects.equals(currentGlyph, newGlyph)) { // move succeeded, add the beast to the moved set
                        movedBeasts.add(sigil);
                    }
                }
                // remove any stale entries (beasts that disappeared from the internal map)
                MysticBeastTracker.this.beastPerches.entrySet().removeIf(entry -> !movedBeasts.contains(entry.getKey()));
            }
        }
    }

    // inner class Beast used to represent a mystic beast with its unique sigil and name
    static final class Beast {
        private final int id;
        private final String sigil;
        private final String name;

        public Beast(int id) {
            this.id = id;
            this.sigil = "BEAST-" + id;
            this.name = "Beast #" + id;
        }

        // accessor methods for the sigil and name of the beast
        public String getSigil() { return this.sigil; }
        public String getName() { return this.name; }
    }
}
