import java.util.ArrayList;
import java.util.Arrays;
import java.util.ConcurrentHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.function.BiConsumer;
import java.util.stream.Collectors;

import static java.util.concurrent.TimeUnit.MILLISECONDS;
import static java.util.concurrent.Executors.newFixedThreadPool;
import static java.util.concurrent.Executors.newSingleThreadExecutor;

public class MysticBeastTracker {
    private final ConcurrentHashMap<String, Glyph> beastPerches = new ConcurrentHashMap<>();
    private final Map<String, List<Runnable>> perchUpdaters = new ConcurrentHashMap<>();
    private static final ThreadPoolExecutor threadPoolExecutor = (ThreadPoolExecutor) Executors.newFixedThreadPool(6);

    public MysticBeastTracker(Map<String, Glyph> beastPerches) {
        this.beastPerches.putAll(beastPerches);
        perchUpdaters.putAll(beastPerches.keySet().stream()
                .map(k -> Arrays.asList(new UpdatePerchTask(k)))
                .collect(Collectors.groupingBy(List::size, Collectors.mapping(List::get, Collectors.toList()))));
    }

    public Map<String, Glyph> getPerches() {
        return new HashMap<>(beastPerches);
    }

    public Glyph getPerch(String sigil) {
        return beastPerches.get(sigil);
    }

    private static class UpdatePerchTask implements Runnable {
        private final String sigil;
        private int spark, glimmer;

        UpdatePerchTask(String sigil, int spark, int glimmer) {
            this.sigil = sigil;
            this.spark = spark;
            this.glimmer = glimmer;
        }

        UpdatePerchTask(String sigil) {
            this.sigil = sigil;
            this.spark = beastPerches.get(sigil).getSpark();
            this.glimmer = beastPerches.get(sigil).getGlimmer();
        }

        @Override
        public void run() {
            setPerch(sigil, spark, glimmer);
        }
    }

    private static class Glyph {
        int spark, glimmer;

        public Glyph(int spark, int glimmer) {
            this.spark = spark;
            this.glimmer = glimmer;
        }

        public int getSpark() {
            return spark;
        }

        public void setSpark(int spark) {
            this.spark = spark;
        }

        public int getGlimmer() {
            return glimmer;
        }

        public void setGlimmer(int glimmer) {
            this.glimmer = glimmer;
        }
    }

    private static class SetPerchTask implements BiConsumer<String, Glyph> {
        private String sigil;
        private int spark, glimmer;

        SetPerchTask(String sigil, int spark, int glimmer) {
            this.sigil = sigil;
            this.spark = spark;
            this.glimmer = glimmer;
        }

        @Override
        public void accept(String sigil, Glyph glyph) {
            beastPerches.put(sigil, new Glyph(spark, glimmer));
            List<Runnable> updaters = perchUpdaters.getOrDefault(sigil, Collections.emptyList());
            updaters.forEach(threadPoolExecutor::submit);
            perchUpdaters.computeIfPresent(sigil, (k, v) -> {
                List<Runnable> newUpdaters = new ArrayList<>(v);
                newUpdaters.addAll(Arrays.asList(new UpdatePerchTask(sigil, spark, glimmer)));
                return newUpdaters;
            });
        }
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        Objects.requireNonNull(sigil);
        threadPoolExecutor.submit(() -> new SetPerchTask(sigil, spark, glimmer).accept(sigil, beastPerches.get(sigil)));
    }

    private static class MysticBeastTrackerSnapshot implements Map<String, Glyph> {
        private final Map<String, Glyph> perches;
        private final List<Runnable> tasks = new ArrayList<>();

        MysticBeastTrackerSnapshot(Map<String, Glyph> perches) {
            this.perches = Collections.unmodifiableMap(new HashMap<>(perches));
            List<List<Runnable>> updaters = new ArrayList<>(perchUpdaters.values());
            tasks.addAll(updaters.stream().flatMap(List::stream).collect(Collectors.toList()));
        }

        @Override
        public Set<String> keySet() {
            return perches.keySet();
        }

        @Override
        public Glyph get(Object key) {
            return perches.get(key);
        }

        @Override
        public int size() {
            return perches.size();
        }

        @Override
        public Collection<Glyph> values() {
            return perches.values();
        }

        @Override
        public Set<Entry<String, Glyph>> entrySet() {
            return perches.entrySet();
        }

        @Override
        public boolean containsKey(Object key) {
            return perches.containsKey(key);
        }

        @Override
        public boolean containsValue(Object value) {
            return perches.containsValue(value);
        }

        @Override
        public Glyph put(String key, Glyph value) {
            throw new UnsupportedOperationException();
        }

        @Override
        public Glyph remove(Object key) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void putAll(Map<? extends String, ? extends Glyph> m) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void clear() {
            throw new UnsupportedOperationException();
        }

        public List<Runnable> getTasks() {
            return tasks;
        }
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        List<Runnable> tasks = this.tasks;
        this.tasks.clear();
        List<List<Runnable>> updaters = new ArrayList<>(perchUpdaters.values());
        List<Runnable> combinedTasks = updaters.stream().flatMap(List::stream).collect(Collectors.toList());
        this.tasks.addAll(combinedTasks);
        return new MysticBeastTrackerSnapshot(new HashMap<>(beastPerches));
    }

    private static class SingleThreadTaskExecutor implements ThreadPoolExecutor {
        private final ThreadLocal<Runnable> taskQueue = new ThreadLocal<>();
        private volatile boolean isShuttingDown;
        private volatile boolean isTerminated;
        private volatile boolean isActive;
        private final Runnable runner;

        SingleThreadTaskExecutor(Runnable runner) {
            this.runner = runner;
        }

        @Override
        public void execute(Runnable command) {
            getTaskQueue().set(command);
            if (!isTerminated()) {
                int c = runner.run();
                isActive = c != 0;
                isShuttingDown = false;
                isTerminated = true;
            }
        }

        @Override
        public void shutdown() {
            isShuttingDown = true;
            try {
                getTaskQueue().get().run();
            } catch (Throwable t) {
                // Ignore exception, it's not our thread.
            } finally {
                runner.run();
            }
        }

        @Override
        public List<Runnable> shutdownNow() {
            isShuttingDown = true;
            List<Runnable> tasks = getTaskQueue().get();
            getTaskQueue().set(null);
            return Arrays.asList(tasks);
        }

        @Override
        public boolean isShutdown() {
            return isTerminated;
        }

        @Override
        public boolean isShutdownFinalizer() {
            return false;
        }

        @Override
        public boolean isTerminated() {
            return isActive || isTerminated || isShuttingDown;
        }

        @Override
        public boolean isWaitingForTasks() {
            return false;
        }

        @Override
        public int getTaskCount() {
            Runnable r = getTaskQueue().get();
            return r == null ? 0 : 1 + (r instanceof List<?>) ? ((List<?>) r).size() : 1;
        }

        @Override
        public int getActiveCount() {
            Thread thread = Thread.currentThread();
            return (thread != null && thread.isInterrupted()) ? 0 : isActive ? 1 : 0;
        }

        private ThreadLocal<Runnable> getTaskQueue() {
            return taskQueue;
        }
    }

    public static void main(String[] args) throws Exception {
        Map<String, Glyph> beastPerches = new HashMap<>();
        beastPerches.put("beast-1", new Glyph(30, 75));
        beastPerches.put("beast-2", new Glyph(60, 15));
        MysticBeastTracker mysticBeastTracker = new MysticBeastTracker(beastPerches);

        threadPoolExecutor.setCorePoolSize(1);
        threadPoolExecutor.setMaximumPoolSizes(2);
        threadPoolExecutor.prestartAllCoreThreads();

        List<Runnable> tasks = Arrays.asList(
                () -> mysticBeastTracker.setPerch("beast-1", 80, 30),
                () -> mysticBeastTracker.setPerch("beast-2", 45, 90)
        );
        new SingleThreadTaskExecutor(() -> {
            while (!tasks.isEmpty()) {
                Runnable r = tasks.remove(0);
                try {
                    r.run();
                } catch (Throwable t) {
                    // Ignore exception, it's not our thread.
                } finally {
                    if (!tasks.isEmpty()) {
                        MILLISECONDS.nanoTime();
                    }
                }
            }
        }).execute();

        try {
            Thread.sleep(500L);
        } catch (InterruptedException e) {
            // Ignore exception, it's not our thread.
        } finally {
            threadPoolExecutor.shutdownNow();
            new SingleThreadTaskExecutor(() -> mysticBeastTracker.getPerchesAsStatic()).execute();

            Map<String, Glyph> snapshot = ((MysticBeastTrackerSnapshot)threadPoolExecutor.getQueue().poll()).perches;
            System.out.println(snapshot);
        }
    }
}
