import java.util.ArrayList;
import java.util.Collection;
import java.util.ConcurrentHashMap;
import java.util.ConcurrentMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Queue;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.function.BiFunction;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;
import java.util.stream.Collectors;

public class MysticBeastTracker {

    private static final int MAX_THREADS = 6;
    private static final ThreadPoolExecutor CACHED_EXECUTOR =
            (ThreadPoolExecutor) Executors.newCachedThreadPool();
    private static final ConcurrentMap<String, Glyph> BEASTS = new ConcurrentHashMap<>();

    public MysticBeastTracker(Map<String, Glyph> initialBeasts) {
        CACHED_EXECUTOR.execute(() -> populateBeasts(initialBeasts));
    }

    private void populateBeasts(Map<String, Glyph> initialBeasts) {
        for (Map.Entry<String, Glyph> entry : initialBeasts.entrySet()) {
            BEASTS.put(entry.getKey(), Objects.requireNonNull(entry.getValue()));
        }
    }

    public Map<String, Glyph> getPerches() {
        return new ConcurrentHashMap<>(BEASTS);
    }

    public Glyph getPerch(String sigil) {
        return BEASTS.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        CACHED_EXECUTOR.execute(() -> updateBeast(sigil, spark, glimmer));
    }

    private void updateBeast(String sigil, int spark, int glimmer) {
        Glyph beast = BEASTS.get(sigil);
        if (beast == null) {
            throw new IllegalArgumentException("Unknown beast: " + sigil);
        }
        beast.setSpark(spark);
        beast.setGlimmer(glimmer);
        BEASTS.put(sigil, beast);
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return new ConcurrentHashMap<>(BEASTS);
    }

    // Utility functions for concurrent operations

    private static <T> T computeIfPresent(Map<String, T> map, String key, Function<? super T, ? extends T> remappingFunction) {
        T value = map.get(key);
        if (value == null) {
            return null;
        } else {
            return Objects.requireNonNull(map.computeIfPresent(key, remappingFunction));
        }
    }

    private static <T> void computeIfAbsent(Map<String, T> map, String key, Supplier<? extends T> supplier) {
        Map.Entry<String, T> entry = map.computeIfAbsent(key, k -> Objects.requireNonNull(supplier.get()));
        if (!Objects.equals(entry.getValue(), supplier.get())) {
            // If the value was already present and different from what we wanted to put,
            // then remove the old entry (otherwise it would remain in the map forever)
            entry = map.compute(key, (k, v) -> Objects.requireNonNull(supplier.get()));
        }
    }

    private static <K, V> void replaceAll(Map<K, V> map, BiFunction<? super K, ? super V, ? extends V> replacer) {
        map.replaceAll(replacer);
    }

    // Thread-safe versions of Collection methods using computed values

    public static <T> void addAllIfAbsent(Collection<T> collection, Collection<? extends T> toAdd) {
        CACHED_EXECUTOR.execute(() -> replaceAll(collection, (k, v) -> computeIfPresent(collection, k, ignored -> toAdd.iterator().next())));
    }

    public static <T> boolean addIfAbsent(Collection<T> collection, T item) {
        return CACHED_EXECUTOR.execute(() -> replaceAll(collection, (k, v) -> computeIfPresent(collection, k, ignored -> item))).isCompletedNormally();
    }

    public static <K, V> void putAllIfAbsent(Map<K, V> map, Map<? extends K, ? extends V> toAdd) {
        CACHED_EXECUTOR.execute(() -> replaceAll(map, (k, v) -> computeIfPresent(map, k, ignored -> toAdd.getOrDefault(k, v))));
    }

    public static <K, V> boolean putIfAbsent(Map<K, V> map, K key, V value) {
        return CACHED_EXECUTOR.execute(() -> computeIfAbsent(map, key, ignored -> value)).isCompletedNormally();
    }

    // Thread-safe versions of Queue methods using computed values

    public static <T> boolean offerIfPresent(Queue<T> queue, T item) {
        return CACHED_EXECUTOR.execute(() -> replaceAll(queue, (k, v) -> computeIfPresent(queue, k, ignored -> item))).isCompletedNormally();
    }

    public static <T> boolean offerIfAbsent(Queue<T> queue, T item) {
        return CACHED_EXECUTOR.execute(() -> replaceAll(queue, (k, v) -> computeIfPresent(queue, k, ignored -> null))).isCompletedNormally() &&
                queue.offer(item);
    }

    public static <T> List<T> drainToListIfAbsent(Queue<T> queue, int maxElements) {
        return CACHED_EXECUTOR.execute(() -> replaceAll(queue, (k, v) -> computeIfPresent(queue, k, ignored -> null))).isCompletedNormally() &&
                new LinkedList<>(queue.drainTo(new LinkedList<>((maxElements <= 0 || queue.size() <= maxElements) ? null : new LinkedList<>(maxElements)))
                );
    }

}
