import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.ConcurrentHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static java.time.Duration.ofSeconds;

public class CelestialCaravanTracker {

    private final Map<String, Starlight> beastMap = new ConcurrentHashMap<>();
    private final ExecutorService threadPool = Executors.newFixedThreadPool(6);

    public CelestialCaravanTracker(Map<String, Starlight> initialBeasts) {
        initialBeasts.forEach((glyph, starlight) -> beastMap.putIfAbsent(glyph, starlight));
    }

    public Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(beastMap);
    }

    public Optional<Starlight> getHaven(String glyph) {
        return Optional.ofNullable(beastMap.get(glyph));
    }

    public void setHaven(String glyph, int shimmer, int pulse) {
        beastMap.computeIfPresent((k, v) -> v.withShimmer(shimmer).withPulse(pulse))
                .orElseGet(() -> {
                    throw new IllegalArgumentException("Beast " + glyph + " does not exist.");
                });
    }

    public Map<String, Starlight> getHavensAsStatic() {
        return new HashMap<>(beastMap);
    }

    /**
     * Finds the closest haven to a given point based on the Manhattan distance.
     */
    public Optional<Starlight> findNearestHaven(int x, int y) {
        List<Future<Optional<Starlight>>>> futures = threadPool.submit(() -> {
            List<Future<Optional<Starlight>>>> results = new ArrayList<>();
            beastMap.keySet().parallelStream()
                    .map(glyph -> threadPool.submit(() -> {
                        Starlight starlight = beastMap.get(glyph);
                        int distanceX = Math.abs(x - starlight.getX());
                        int distanceY = Math.abs(y - starlight.getY());
                        return Optional.ofNullable(starlight).filter(haven -> 
                                distanceX + distanceY <= haven.getRadius() * 2);
                    }))
                    .collect(Collectors.toList());
            results.addAll(futures);
            return results;
        }).get();
        List<Optional<Starlight>> allResults = futures.stream().flatMap(Future::get).collect(Collectors.toList());
        return allResults.isEmpty() ? Optional.empty() : allResults.stream().min(Comparator.comparingInt(o -> {
            int distanceX = Math.abs(x - o.get().getX());
            int distanceY = Math.abs(y - o.get().getY());
            return distanceX + distanceY;
        })).map(Optional::get);
    }

    public void migrateBeasts(int x, int y) {
        beastMap.keySet().parallelStream()
                .map(glyph -> threadPool.submit(() -> {
                    beastMap.computeIfPresent((k, v) -> new Starlight(x + v.getRadius(), y))
                            .orElseThrow(() -> new IllegalStateException("Beast " + glyph + " does not exist."));
                    return null;
                }))
                .collect(Collectors.toList()).stream().flatMap(Future::get).forEach(Consumer.ignore());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        CelestialCaravanTracker that = (CelestialCaravanTracker) o;
        return Objects.equals(beastMap, that.beastMap) && Objects.equals(threadPool, that.threadPool);
    }

    @Override
    public int hashCode() {
        return Objects.hash(beastMap, threadPool);
    }

    private static class Starlight {
        private final int x;
        private final int y;
        private final int radius;

        public Starlight(int x, int y) {
            this(x, y, 50);
        }

        public Starlight(int x, int y, int radius) {
            this.x = x;
            this.y = y;
            this.radius = radius;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }

        public int getRadius() {
            return radius;
        }

        private Starlight withShimmer(int shimmer) {
            return new Starlight(x, y, radius, shimmer);
        }

        private Starlight withPulse(int pulse) {
            return new Starlight(x, y, radius, shimmer, pulse);
        }

        public static class Builder {
            private int x;
            private int y;
            private int radius;
            private int shimmer = 0;
            private int pulse = 0;

            public Starlight build() {
                return new Starlight(x, y, radius, shimmer, pulse);
            }

            public Builder withX(int x) {
                this.x = x;
                return this;
            }

            public Builder withY(int y) {
                this.y = y;
                return this;
            }

            public Builder withRadius(int radius) {
                this.radius = radius;
                return this;
            }

            public Builder withShimmer(int shimmer) {
                this.shimmer = shimmer;
                return this;
            }

            public Builder withPulse(int pulse) {
                this.pulse = pulse;
                return this;
            }
        }

        private Starlight(int x, int y, int radius, int shimmer, int pulse) {
            this.x = x;
            this.y = y;
            this.radius = radius;
            this.shimmer = shimmer;
            this.pulse = pulse;
        }
    }

    /**
     * Runs a task with the provided Runnable on the main thread.
     */
    public void runMainThread(Runnable task) {
        if (threadPool.isShutdown()) {
            throw new IllegalStateException("Thread pool is already shut down.");
        }
        task.run();
    }

    /**
     * Runs a task on one of the available threads in the thread pool with 1 second time out.
     */
    public <T> T runOnPooledThread(Callable<T> task, int priority, long timeout) throws Exception {
        return threadPool.submit(task).get(timeout, TimeUnit.SECONDS);
