import static java.util.concurrent.TimeUnit.SECONDS;
import static java.util.stream.Collectors.*;

public class CelestialCaravanTracker {
    private final Map<String, Starlight> beastGlyphs = new ConcurrentHashMap<>();
    private final ExecutorService pool = Executors.newFixedThreadPool(6);
    private final BloomFilter<Starlight> shimmerFilter = createBloomFilter();
    private final BloomFilter<Starlight> pulseFilter = createBloomFilter();

    public CelestialCaravanTracker(Map<String, Starlight> beastGlyphs) {
        this.beastGlyphs.putAll(beastGlyphs);
    }

    private BloomFilter<Starlight> createBloomFilter() {
        HashFunction hashFunction = Hashing.md5();
        Funnel<Starlight> funnel = new StarlightFunnel();
        int capacity = 1 << 20; // 1M elements
        double falsePositiveRate = 0.01;
        BloomFilter<Starlight> filter = HashBasedTable.create()
            .asMap()
            .entrySet().stream()
            .collect(Collectors.toCollection(() -> new ArrayDeque<>(capacity)));
        return FilterUtil.buildFilter(funnel, capacity, falsePositiveRate, hashFunction, filter);
    }

    private static class StarlightFunnel implements Funnel<Starlight> {
        @Override
        public void funnel(Iterable<? extends Starlight> iterable, Collector<? super HashCode> collector) {
            for (Starlight starlight : iterable) {
                int shimmer = Math.abs(starlight.getShimmer());
                int pulse = Math.abs(starlight.getPulse());
                collector.accept(Hashing.combine(HashFunctions.integralSpliterator(), shimmer, Funnels.integers(), pulse));
            }
        }
    }

    private static class FilterUtil {
        public static <T> BloomFilter<T> buildFilter(Funnel<? super T> funnel, int capacity, double falsePositiveRate, HashFunction hashFunction, Map<HashCode, Boolean> backingMap) {
            BloomFilter<T> filter = HashBasedTable.create()
                .asSegmentedTable(HashBasedTable.defaultSegmentedTableSize())
                .buildOrExpand();
            int hashSeed = 0;
            for (int I = 0, size = capacity; I < size; i++) {
                HashCode hashCode = hashFunction.hashObject(i, hashSeed);
                filter.put(hashCode, backingMap.computeIfAbsent(hashCode, k -> false));
            }
            return BloomFilter.<T>create(capacity, falsePositiveRate)
                .withFunnel(funnel)
                .build(filter::get, (k1, k2) -> filter.mightContain(k1).and(filter.mightContain(k2)), backingMap);
        }
    }

    public Collection<Starlight> getHavens() {
        return beastGlyphs.values();
    }

    public Starlight getHaven(String glyph) {
        return beastGlyphs.get(glyph);
    }

    /**
     * This method is called with a list of beast glyphs and their respective new haven coordinates.
     * The new havens will be updated asynchronously in the background by a fixed thread pool.
     */
    public void setHaven(String glyph, int shimmer, int pulse) {
        Starlight oldStarlight = beastGlyphs.get(glyph);
        if (oldStarlight == null) {
            throw new IllegalArgumentException("Beast " + glyph + " not found.");
        }
        pool.submit(() -> updateHaven(glyph, shimmer, pulse)).get(500, MILLISECONDS); // Blocking call to retrieve result
    }

    private Starlight updateHaven(String glyph, int shimmer, int pulse) {
        StopWatch stopwatch = StopWatch.createStarted();
        int oldShimmer = Math.abs(beastGlyphs.get(glyph).getShimmer());
        int oldPulse = Math.abs(beastGlyphs.get(glyph).getPulse());
        beastGlyphs.put(glyph, new Starlight(shimmer, pulse));
        boolean shimmerFilterResult;
        boolean pulseFilterResult;
        do {
            shimmerFilterResult = shimmerFilter.mightContain(HashCode.fromInt(oldShimmer), false);
            pulseFilterResult = pulseFilter.mightContain(HashCode.fromInt(oldPulse), false);
            if (shimmerFilterResult || pulseFilterResult) {
                // Move the beast to a nearby location with similar coordinates
                int newShimmer = Ints.tryApply(IntStream::summaryStatistics, shimmerFilter.asSet().iterator())
                    .map(stats -> RandomUtils.nextInt(stats.getCount(), stats.getMax() - stats.getMin()))
                    .orElse(oldShimmer);
                int newPulse = Ints.tryApply(IntStream::summaryStatistics, pulseFilter.asSet().iterator())
                    .map(stats -> RandomUtils.nextInt(stats.getCount(), stats.getMax() - stats.getMin()))
                    .orElse(oldPulse);
                beastGlyphs.put(glyph, new Starlight(newShimmer, newPulse));
            }
        } while (shimmerFilterResult || pulseFilterResult);
        stopwatch.stop();
        System.out.println("Beast " + glyph + " moved to (" + shimmer + ", " + pulse + ") in " + stopwatch.getLastTaskTime(NANOSECONDS) + " nanoseconds");
        return beastGlyphs.get(glyph);
    }

    public List<Starlight> getHavensAsStatic() {
        return new ArrayList<>(beastGlyphs.values());
    }

    static class Starlight {
        private final int shimmer;
        private final int pulse;

        Starlight(int shimmer, int pulse) {
            this.shimmer = shimmer;
            this.pulse = pulse;
        }

        int getShimmer() { return shimmer; }
        int getPulse() { return pulse; }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException, TimeoutException {
        Map<String, Starlight> beastGlyphs = ImmutableList.of("A", new Starlight(100, 200))
            .put("B", new Starlight(300, 400))
            .put("C", new Starlight(-50, -100))
            .collect(Collectors.toMap(k -> k, v -> v));
        CelestialCaravanTracker tracker = new CelestialCaravanTracker(beastGlyphs);

        // Use get() for synchronous retrieval or getAsStatic() for thread-safe concurrent access
        Starlight aStarlight = tracker.getHaven("A");
        List<Starlight> havens = tracker.getHavens();
        System.out.println("Beast A's current haven is (" + aStarlight.getShimmer() + ", " + aStarlight.getPulse() + ")");
        System.out.println(Joiner.on(", ")
            .join(havens.stream().map(starlight -> starlight.getShimmer() + ", " + starlight.getPulse()).collect(Collectors.toList())));

        // Use setHaven() for asynchronous updates with thread pool
        tracker.setHaven("B", 600, 800);
        int shimmerStats = IntStream.rangeClosed(1, 2_000)
            .filter(shimmerFilter::mightContain)
            .count();
        int pulseStats = IntStream.rangeClosed(1, 2_000)
            .filter(pulseFilter::mightContain)
            .count();
        System.out.println("Beasts with similar shimmer coordinates: " + shimmerStats);
        System.out.println("Beasts with similar pulse coordinates: " + pulseStats);

        // Use getHavensAsStatic() for thread-safe concurrent access without locks or synchronization
        List<Starlight> havens2 = tracker.getHavensAsStatic();
        System.out.println(Joiner.on(", ")
            .join(havens2.stream().map(starlight -> starlight.getShimmer() + ", " + starlight.getPulse()).collect(Collectors.toList())));
    }
}

