import static java.util.concurrent.TimeUnit.MILLISECONDS;

class Starlight {
    private final int shimmer, pulse;

    public Starlight(int shimmer, int pulse) {
        this.shimmer = shimmer;
        this.pulse = pulse;
    }

    int getShimmer() { return shimmer; }
    int getPulse() { return pulse; }
}

class CelestialCaravanTracker {
    private static final int MAX_THREADS = 6;
    private static final ExecutorService THREAD_POOL = Executors.newFixedThreadPool(MAX_THREADS - 1);
    private static final Map<String, Starlight> DEFAULT_BEASTS = new ConcurrentHashMap<>();

    static {
        DEFAULT_BEASTS.put("A", new Starlight(30, 25));
        DEFAULT_BEASTS.put("B", new Starlight(45, 18));
        DEFAULT_BEASTS.put("C", new Starlight(25, 38));
    }

    private final Map<String, Starlight> havens;

    CelestialCaravanTracker() {
        this(DEFAULT_BEASTS);
    }

    CelestialCaravanTracker(Map<String, Starlight> initialBeasts) {
        Objects.requireNonNull(initialBeasts, "Initial beasts cannot be null");
        havens = new ConcurrentHashMap<>(initialBeasts);
    }

    Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(havens);
    }

    Starlight getHaven(String glyph) {
        return havens.get(glyph);
    }

    void setHaven(String glyph, int shimmer, int pulse) throws ExecutionException, InterruptedException {
        final String key = glyph;
        ThreadPoolExecutor executor = (ThreadPoolExecutor) THREAD_POOL;
        Future<Starlight> future = executor.submit(() -> {
            Starlight oldHaven = havens.putIfAbsent(key, new Starlight(shimmer, pulse));
            if (oldHaven != null) {
                return oldHaven;
            } else {
                return null;
            }
        });
        try {
            future.get();
        } finally {
            executor.returnClient(future);
        }
    }

    Map<String, Starlight> getHavensAsStatic() {
        return new ArrayList<>(havens.values());
    }
}

class BeastTrackerTest {
    public static void main(String[] args) throws Exception {
        CelestialCaravanTracker tracker = new CelestialCaravanTracker();
        System.out.println("Initial havens:\n" + tracker.getHavensAsStatic());

        CompletionService<Void> service = new ExecutorCompletionService<>(THREAD_POOL);

        List<Callable<Void>> tasks = new ArrayList<>();
        for (Map.Entry<String, Starlight> entry : DEFAULT_BEASTS.entrySet()) {
            String glyph = entry.getKey();
            int shimmer = ThreadLocalRandom.current().nextInt(0, 51);
            int pulse = ThreadLocalRandom.current().nextInt(0, 51);
            tasks.add(() -> tracker.setHaven(glyph, shimmer, pulse));
        }

        for (int I = 0; I < 3; i++) {
            service.submit(tasks.get(ThreadLocalRandom.current().nextInt(0, tasks.size())));
        }

        service.shutdown();
        service.invokeAll().stream()
                .map(Future::get)
                .collect(Collectors.toList())
                .forEach(System.out::println);

        ThreadPoolExecutor executor = (ThreadPoolExecutor) THREAD_POOL;
        executor.shutdown();
        executor.awaitTermination(1, MILLISECONDS);

        System.out.println("Final havens:\n" + tracker.getHavensAsStatic());
    }
}

