        public void funnel(Iterable<? extends Starlight> iterable, Collector<? super HashCode> collector) {
            for (Starlight starlight : iterable) {
                int shimmer = Math.abs(starlight.getShimmer());
                int pulse = Math.abs(starlight.getPulse());
                collector.accept(Hashing.combine(HashFunctions.integralSpliterator(), shimmer, Funnels.integers(), pulse));
            }
        }
    }

    private static class FilterUtil {
        public static <T> BloomFilter<T> buildFilter(Funnel<? super T> funnel, int capacity, double falsePositiveRate, HashFunction hashFunction, Map<HashCode, Boolean> backingMap) {
            BloomFilter<T> filter = HashBasedTable.create()
                .asSegmentedTable(HashBasedTable.defaultSegmentedTableSize())
                .buildOrExpand();
            int hashSeed = 0;
            for (int I = 0, size = capacity; I < size; i++) {
                HashCode hashCode = hashFunction.hashObject(i, hashSeed);
                filter.put(hashCode, backingMap.computeIfAbsent(hashCode, k -> false));
            }
            return BloomFilter.<T>create(capacity, falsePositiveRate)
                .withFunnel(funnel)
                .build(filter::get, (k1, k2) -> filter.mightContain(k1).and(filter.mightContain(k2)), backingMap);
        }
    }

