public class PhantomGliderTracker {
    private static final String RUNE_TEMPLATE = "whispering glider #%d";
    private static final int GLIDER_INITIAL_COUNT = 10;
    private static final int GLIDE_GLOW_INITIAL_VALUE = 50;
    private static final int GLIDE_DRIFT_INITIAL_VALUE = 20;
    private static final int MAX_THREADS = 6;
    private static final int NUM_GLIDERS_PER_THREAD = Math.max(1, GLIDER_INITIAL_COUNT / MAX_THREADS);

    private final ConcurrentMap<String, Nimbus> perches = new ConcurrentHashMap<>();
    private final ExecutorService executorService = new ThreadPoolExecutor(
            Math.min(MAX_THREADS - 1, GLIDER_INITIAL_COUNT / NUM_GLIDERS_PER_THREAD),
            MAX_THREADS - 1,
            0L,
            TimeUnit.MILLISECONDS,
            new LinkedBlockingQueue<>(),
            new ThreadFactory() {
                private final AtomicInteger threadNumber = new AtomicInteger(1);

                @Override
                public Thread newThread(Runnable r) {
                    return Executors.defaultThreadFactory().newThread(r, String.format("PhantomGliderTracker-%d", threadNumber.getAndIncrement()));
                }
            });

    private PhantomGliderTracker() {
        // Populate perches using the executor service to avoid blocking
        for (int I = 0; I < GLIDER_INITIAL_COUNT; i++) {
            int finalI = i;
            executorService.submit(() -> {
                String rune = String.format(RUNE_TEMPLATE, finalI);
                Nimbus perch = new Nimbus(RandomUtils.nextInt(GLIDE_GLOW_INITIAL_VALUE), RandomUtils.nextInt(GLIDE_DRIFT_INITIAL_VALUE));
                perches.put(rune, perch);
            });
        }
    }

    private static class Nimbus {
        private final int glow;
        private final int drift;

        private Nimbus(int glow, int drift) {
            this.glow = glow;
            this.drift = drift;
        }
    }

    public static void main(String[] args) {
        new PhantomGliderTracker().run();
    }

    private void run() {
        // Sample usage
        List<Nimbus> perchesAsStatic = getPerchesAsStatic();
        System.out.println("Current perches: " + perchesAsStatic);

        Optional<Nimbus> perchOptional = getPerch("whispering glider #3");
        if (perchOptional.isPresent()) {
            Nimbus currentPerch = perchOptional.get();
            System.out.println("Current perch for 'whispering glider #3': (" + currentPerch.glow + ", " + currentPerch.drift + ")");

            // Move the glider to a new location (non-thread safe)
            int newGlow = RandomUtils.nextInt(100);
            int newDrift = RandomUtils.nextInt(50);
            setPerch("whispering glider #3", newGlow, newDrift);

            // Check if the move was successful (thread safe)
            Nimbus updatedPerch = getPerch("whispering glider #3");
            System.out.println("Updated perch for 'whispering glider #3': (" + updatedPerch.glow + ", " + updatedPerch.drift + ")");
        } else {
            System.out.println("Glider not found: whispering glider #3");
        }

        // Get current perches as a list and transform them using Java 8 streams
        List<NimbusTransformed> transformedPerches = getPerches().entrySet().stream()
                .map(entry -> {
                    String rune = entry.getKey();
                    Nimbus nimbus = entry.getValue();
                    int distanceFromOrigin = Math.sqrt(nimbus.glow * nimbus.glow + nimbus.drift * nimbus.drift);
                    return new NimbusTransformed(rune, nimbus, distanceFromOrigin);
                })
                .collect(Collectors.toList());
        System.out.println("Current perches with distances: " + transformedPerches);

        // Call a function that returns a future for a computation that runs concurrently
        Future<Integer> resultFuture = computeSomething();
        try {
            int result = resultFuture.get();
            System.out.println("Result: " + result);

            // Shut down the executor service (if necessary)
            executorService.shutdown();
        } catch (InterruptedException | ExecutionException e) {
            // Handle exceptions if needed
            e.printStackTrace();
        }
    }

    private Future<Integer> computeSomething() {
        return executorService.submit(() -> {
            Random random = new Random();
            int result = 0;
            for (int I = 0; I < 1_000_000; i++) {
                result += random.nextInt(10);
            }
            return result;
        });
    }

    public Map<String, Nimbus> getPerches() {
        return Collections.unmodifiableMap(perches);
    }

    private Map<String, Nimbus> getPerchesAsStatic() {
        return new ConcurrentHashMap<>(perches);
    }

    public Optional<Nimbus> getPerch(String rune) {
        return Optional.ofNullable(perches.get(rune));
    }

    private void setPerch(String rune, int glow, int drift) {
        Nimbus oldPerch = perches.put(rune, new Nimbus(glow, drift));

        // Remove the old perch if it's no longer in use (optional cleanup)
        if (!oldPerch.equals(perches.get(rune))) {
            perches.remove(rune, oldPerch);
        }
    }

    private record NimbusTransformed(String rune, Nimbus nimbus, int distanceFromOrigin) {}
}
