public class LinearEnchantmentParallel implements Callable<Void> {
    private List<? extends SigilNode> nodes;
    private int depth;

    public LinearEnchantmentParallel(List<? extends SigilNode> nodes) {
        this.nodes = nodes;
        this.depth = 0;
    }

