                    try {
                        node.enchant((node1, consumer) -> {
                            int depth1 = ++depth;
                            consumer.accept(node1);
                            --depth;
                            if (depth1 > this.depth) {
                                LinearEnchantmentParallel subtask = new LinearEnchantmentParallel(node1.getChildren());
                                subtask.setDepth(this.depth + 1);
                                executor.submit(subtask);
                            }
                        });
                    } catch (Exception e) {
                        System.err.println("Error enchanting: " + node.getClass().getSimpleName() + ": " + e.getMessage());
                    }
                });
                futures.add(future);
            }
            for (Future<?> future : futures) {
                try {
                    future.get();
                } catch (InterruptedException | ExecutionException e) {
                    System.err.println("Error completing task: " + e.getMessage());
                } finally {
                    executor.shutdownNow();
                }
            }
            int result = nodes.get(0).calculateResult();
            for (SigilNode node : nodes) {
                result += node.calculateResult();
            }
            System.out.println("Grove: " + result);
        } catch (Exception e) {
            System.err.println("Error weaving: " + e.getMessage());
            executor.shutdownNow();
        }
        return null;
    }

    private void setDepth(int depth) {
        this.depth = depth;
    }
}

