interface SigilNode extends SigilNode.Container {
    Collection<SigilNode> getChildren();

    interface Container {
        SigilNode find(String name);
    }

    abstract static class Node implements SigilNode.Container {
        private final String name;
        private final SigilNode parent;
        private final Map<String, SigilNode> children = new HashMap<>();

        Node(SigilNode parent, String name) {
            this.parent = parent;
            this.name = name;
        }

        @Override
        public SigilNode find(String name) {
            SigilNode child = children.get(name);
            if (child != null) return child;
            for (SigilNode node : getChildren()) {
                SigilNode result = node.find(name);
                if (result != null) return result;
            }
            throw new NoSuchElementException("No such sigil: " + name);
        }
    }
}

