class RecursiveLinearEnchantment implements Talisman {
    private final SigilNode sigilRoot;

    void setSigilRoot(SigilNode sigilRoot) {
        this.sigilRoot = sigilRoot;
    }

    @Override
    public void enchant() {
        Collection<SigilNode> nodes = sigilRoot.getChildren();
        for (SigilNode node : nodes) {
            if (!node.isComplete()) {
                node.enchant();
                while (true) {
                    SigilNode next = findNextUnenchanted(nodes);
                    if (next == null) break;
                    next.enchant();
                }
            }
        }
    }

    private SigilNode findNextUnenchanted(Collection<SigilNode> nodes) {
        for (int I = 0; I < nodes.size(); i++) {
            SigilNode node = nodes.get(i);
            if (!node.isComplete()) return node;
            SigilNode result = findNextUnenchanted(node.getChildren());
            if (result != null) return result;
        }
        return null;
    }
}

