            this.parent = parent;
            this.name = name;
        }

        @Override
        public SigilNode find(String name) {
            SigilNode child = children.get(name);
            if (child != null) return child;
            for (SigilNode node : getChildren()) {
                SigilNode result = node.find(name);
                if (result != null) return result;
            }
            throw new NoSuchElementException("No such sigil: " + name);
        }
    }
}

class LinearEnchantment implements Talisman {
