    @Override
    public void enchant() {
        SigilNode current = sigilRoot;
        while (!current.isComplete()) {
            current.enchant();
            current = current.findNextUnenchanted();
        }
    }

    private SigilNode findNextUnenchanted() {
        for (SigilNode child : getChildren()) {
            SigilNode result = child.findNextUnenchanted();
            if (result != null) return result;
