    @Override
    public void enchant() {
        Collection<SigilNode> nodes = sigilRoot.getChildren();
        for (SigilNode node : nodes) {
            if (!node.isComplete()) {
                node.enchant();
                while (true) {
                    SigilNode next = findNextUnenchanted(nodes);
                    if (next == null) break;
                    next.enchant();
                }
            }
        }
