            }, Executors.newFixedThreadPool(2));
            result = future.joinCompletely().orElseThrow(IllegalStateException::new);
        }
        System.out.println("Finished computing " + name);
        return result;
    }

    @Override
    public void apply() {
        System.out.println("Applying " + name + ", priority: " + priority);
        if (priority == 1) {
