}

interface RuneNode {
    List<RuneNode> getChildren();
    Charm getCharm();
}

class Rune implements RuneNode {
    private final RuneNode parent;
    private final String name;
    private final int depth;
    private final Charm charm;
    private final ExecutorService executor = Executors.newFixedThreadPool(2); // Fixed thread pool to manage at most 2 additional threads beyond the main thread
    private List<Charm> collectedCharms = new ArrayList<>();

    Rune(String name, int depth, RuneNode parent, Charm charm) {
        this.parent = parent;
        this.name = name;
        this.depth = depth;
        this.charm = charm;
    }

    @Override
    public List<RuneNode> getChildren() {
        return new ArrayList<>(); // No child runes in this example
    }

    @Override
    public Charm getCharm() {
        return charm;
    }

    void applyRecursive() {
        collectedCharms.add(charm);
        if (parent != null) { // Parent exists, execute sequential processing
            parent.applyRecursive();
        } else { // No parent, execute parallel processing
            List<Future<Charm>> futures = new ArrayList<>();
            for (RuneNode child : getChildren()) {
                Future<Charm> future = executor.submit(() -> child.getCharm());
                futures.add(future);
            }
            try {
                for (Future<Charm> future : futures) {
                    collectedCharms.add(future.get());
                }
            } catch (InterruptedException | ExecutionException e) {
                // Handle exceptions
            } finally {
                executor.shutdown(); // Shut down the thread pool to avoid unbounded thread creation or cached thread pools
            }
        }
    }

    void apply() {
        List<Charm> runeCharms = new ArrayList<>();
        if (parent == null) { // No parent, execute parallel processing
            List<Future<Charm>> futures = new ArrayList<>();
            for (RuneNode child : getChildren()) {
                Future<Charm> future = executor.submit(() -> child.getCharm());
                futures.add(future);
            }
            try {
                for (Future<Charm> future : futures) {
                    runeCharms.add(future.get());
                }
            } catch (InterruptedException | ExecutionException e) {
                // Handle exceptions
            } finally {
                executor.shutdown(); // Shut down the thread pool to avoid unbounded thread creation or cached thread pools
            }
            for (Charm charm : runeCharms) {
                this.charm.apply();
            }
        } else { // Parent exists, execute sequential processing
            parent.applyRecursive();
            for (RuneNode child : getChildren()) {
                child.applyRecursive();
            }
            charm.apply();
        }
    }
}

class Main {
