        Rune tree = new Rune("Root", 0, null, () -> System.out.println("Root Charm Applied"));
        tree.getChildren().add(new Rune("Child1", 1, tree, () -> System.out.println("Child1 Charm Applied")));
        tree.getChildren().add(new Rune("Child2", 1, tree, () -> System.out.println("Child2 Charm Applied")));
        // Concurrent processing of runes using recursive method
