sequentialRecursive(n.getChildren(), results);
}
}

public <T> Collection<T> parallelRecursive(List<Node<T>> nodes) throws InterruptedException {
Collection<T> results = Collections.synchronizedList(new ArrayList<>());
CountDownLatch latch = new CountDownLatch(nodes.size());

Thread worker = new Thread(() -> {
for (Node<T> n : nodes) {
T result = n.compute();
results.add(result);
sequentialRecursive(n.getChildren(), results);
latch.countDown();
}
