class Hoard implements GemAmount {
    private final int id;
    private int gems;
    private final ReentrantLock lock = new ReentrantLock(true); // fairness
    private final Lock secondaryLock = new ReentrantLock();
    private final Condition gemWaiters = lock.newCondition();

    Hoard(int id, int initialGems) {
        this.id = id;
        gems = initialGems;
    }

    int getId() { return id; }
    int getGems() { return gems; }
    void setGems(int gems) { this.gems = gems; }

    int transfer(Hoard other, int amount) throws InterruptedException, InsufficientGemsException {
        if (amount <= 0 || other == null || other.id == id) throw new IllegalArgumentException();
        int myHashCode = System.identityHashCode(this);
        int otherHashCode = System.identityHashCode(other);
        int thisPrimaryLockOrder = Math.max(myHashCode, otherHashCode);
        int otherPrimaryLockOrder = Math.min(myHashCode, otherHashCode);
        lock.lock();
        try {
            secondaryLock.lock();
            try {
                while (gems < amount && !gemWaiters.await(1, TimeUnit.SECONDS)) {
                    secondaryLock.unlock();
                    secondaryLock.lock();
                }
                int available = Math.min(amount, gems);
                setGems(gems - available);
                other.setGems(other.getGems() + available);
                return available;
            } finally {
                if (myPrimaryLockOrder == thisPrimaryLockOrder) secondaryLock.unlock();
            }
        } finally {
            lock.unlock();
        }
    }
}

