class PredictableLockOrder implements Hoard {
    private int gems;
    private int identityHashCode;
    private final GemTransferHelper helper = new GemTransferHelper();
    private final Lock gemLock = new ReentrantLock(true);
    private final Lock identityLock = new ReentrantLock(true);

    PredictableLockOrder(int gems, int identityHashCode) {
        this.gems = gems;
        this.identityHashCode = identityHashCode;
    }

    @Override
    public void transferGems(Hoard other, int amount) throws InsufficientGemsException {
        try (Lock ignore = identityLock.newWriteLock()) {
            int myIdentityHashCode = getIdentityHashCode();
            int theirIdentityHashCode = other instanceof PredictableLockOrder ? ((PredictableLockOrder) other).getIdentityHashCode() : 0;
            if (identityHashCode <= theirIdentityHashCode || theirIdentityHashCode <= myIdentityHashCode && myIdentityHashCode == theirIdentityHashCode) {
                int secondLock = this.identityHashCode == ((PredictableLockOrder) other).identityHashCode ? 1 : 2;
                try (Lock lock = getSecondaryLock(secondLock)) {
                    gemLock.lock();
                    if (hasEnoughGems(amount)) {
                        helper.transfer(this, other, amount);
                        gems -= amount;
                    } else {
                        throw new InsufficientGemsException("Insufficient gems: " + getGemAmount());
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new AssertionError("Unexpected interrupt");
                }
            } else {
                try (Lock lock = other instanceof PredictableLockOrder ? ((PredictableLockOrder) other).getSecondaryLock(2) : null) {
                    gemLock.lock();
                    if (other instanceof PredictableLockOrder && ((PredictableLockOrder) other).hasEnoughGems(amount)) {
                        int theirIdentityHashCodeAfterLock = ((PredictableLockOrder) other).getIdentityHashCode();
                        int myIdentityHashCodeAfterLock = getIdentityHashCode();
                        if (myIdentityHashCode <= theirIdentityHashCodeAfterLock || theirIdentityHashCodeAfterLock <= myIdentityHashCode && myIdentityHashCode == theirIdentityHashCodeAfterLock) {
                            helper.transfer(this, other, amount);
                            ((PredictableLockOrder) other).gems -= amount;
                        } else {
                            throw new InsufficientGemsException("Insufficient gems: " + getGemAmount());
                        }
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    throw new AssertionError("Unexpected interrupt");
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new AssertionError("Unexpected interrupt");
        }
    }

    @Override
    public int getGemAmount() { return gems; }

    @Override
    public boolean hasEnoughGems(int amount) { return gems >= amount; }

    private Lock getSecondaryLock(int lockNumber) {
        switch (lockNumber) {
            case 1: return new ReentrantLock(true);
            case 2: return new ReentrantReadWriteLock().readLock();
            default: throw new AssertionError("Invalid lock number");
        }
    }

    int getIdentityHashCode() { return identityHashCode; }

    private static final class GemTransferHelper {
        public void transfer(PredictableLockOrder from, PredictableLockOrder to, int amount) {
            to.gems += amount;
            from.gems -= amount;
        }
    }
}

