        if (transfer.tryAcquire()) {
            threadPool.submit(new Runnable() {
                @Override
                public void run() {
                    try {
                        executeTransfer(transfer);
                        transfers.add(transfer);
                    } catch (Exception e) {
                        System.err.println("Transfer failed: " + e.getMessage());
                    } finally {
                        transfer.release();
                    }
                }
            });
        } else {
            waitForAvailableTransfer(other);
            receive(other);
        }
    }

    private void executeTransfer(GemTransfer transfer) throws Exception {
        int amount = Math.min(transfer.getAmount(), gems);
        System.out.printf("Hoard %d transfers %d gem%s to Hoard %d\n", id, amount, amount == 1 ? "" : "s", transfer.getOther().id);
        gems -= amount;
        transfer.getOther().deposit(amount);
    }

    private void waitForAvailableTransfer(Hoard other) {
        synchronized (this) {
            while (!shutdown && !transfers.isEmpty() && Arrays.hashCode(new Object[]{this, other}) == transfers.peek().getHashCode()) {
                try {
                    wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    @Override
    public void run() {
        while (!shutdown && !transfers.isEmpty()) {
            try {
                GemTransfer transfer = transfers.take();
                executeTransfer(transfer);
            } catch (Exception e) {
                System.err.println("Transfer failed: " + e.getMessage());
            } finally {
                shutdownThreadPool();
            }
        }
    }

    private void shutdownThreadPool() {
        if (!shutdown && !threadPool.isShuttingDown()) {
            threadPool.shutdownNow();
            shutdown = true;
        }
    }

    static class GemTransfer implements Transferable {
        Hoard source, other;
        int amount;
        int hashCode;

        GemTransfer(Hoard source, Hoard other) {
            this.source = source;
            this.other = other;
            amount = Math.min(source.gems, other.gems);
