class VaultNode {
    private int id;
    private Lock lockA, lockB;
    private int crystalAmount;
    private ExecutorService threadPool = Executors.newFixedThreadPool(2);

    public VaultNode(int id) {
        this.id = id;
        lockA = new ReentrantLock();
        lockB = new ReentrantLock();
    }

    void transferCrystal(VaultNode target) throws InsufficientCrystalsException {
        int myHashCode = Integer.hashCode(this);
        int targetHashCode = Integer.hashCode(target);
        boolean isSelf = myHashCode == targetHashCode;
        boolean sameHashCode = myHashCode == targetHashCode || myHashCode ^ targetHashCode == 0x3FFFFFFF;
        if (isSelf) {
            throw new InsufficientCrystalsException("Cannot transfer crystals to self");
        } else if (sameHashCode) {
            lockA.lock();
            try {
                lockB.lock();
