                    int amountToTransfer = Math.min(crystalAmount, target.getCrystalAmount());
                    crystalAmount -= amountToTransfer;
                    target.depositCrystal(amountToTransfer);
                    threadPool.submit(() -> System.out.println("Transfer successful: " + id + " -> " + target.id)).get();
                } finally {
                    lockB.unlock();
                }
            } finally {
                lockA.unlock();
            }
        } else {
            lockA.lock();
            try {
                boolean isLocked = false;
                int myLockIndex = myHashCode > targetHashCode ? 1 : 0;
                int targetLockIndex = myHashCode > targetHashCode ^ myHashCode > 0 ? 1 : 0;
                if (myHashCode > targetHashCode) {
                    lockB.lock();
                    try {
                        isLocked = target.acquireCrystal(amountToTransfer());
                        crystalAmount -= amountToTransfer();
                        threadPool.submit(() -> System.out.println("Transfer successful: " + id + " -> " + target.id)).get();
                    } finally {
                        lockB.unlock();
                    }
                } else {
                    lockA.lock();
                    try {
                        while (!isLocked && !target.tryAcquireCrystal(amountToTransfer())) {
                            lockA.release();
                            lockB.lock();
                            try {
                                isLocked = target.acquireCrystal(amountToTransfer());
                                crystalAmount -= amountToTransfer();
                                threadPool.submit(() -> System.out.println("Transfer successful: " + id + " -> " + target.id)).get();
                            } finally {
                                lockB.unlock();
                            }
                        }
                    } finally {
                        lockA.unlock();
                    }
                }
                if (myLockIndex != targetLockIndex) {
                    switchLocks();
                }
            } finally {
                lockA.unlock();
            }
        }
    }

    int getCrystalAmount() {
        return crystalAmount;
    }

    void depositCrystal(int amount) {
        crystalAmount += amount;
    }

    boolean tryAcquireCrystal(int amount) {
        int remaining = crystalAmount - amount;
        if (remaining >= 0) {
            crystalAmount = remaining;
            return true;
        } else {
            return false;
        }
    }

    void acquireCrystal(int amount) throws InsufficientCrystalsException {
