            crystalAmount = remaining;
        } else {
            throw new InsufficientCrystalsException("Insufficient crystals: " + id + ", required: " + amount);
        }
    }

    private void switchLocks() {
        lockA.lock();
        try {
            lockB.unlock();
        } finally {
            lockA.unlock();
        }
        lockB.lock();
        try {
            lockA.lock();
        } finally {
            lockB.unlock();
        }
    }
