    private Semaphore spaceSemaphore = new Semaphore(MAX_ORBS); // Permit for claiming a spot in the vault
    private ReentrantLock lock = new ReentrantLock(); // Lock for internal vault manipulation
    private Condition notFull = lock.newCondition(); // Condition for notifying thread waiting for space
    private Condition notEmpty = lock.newCondition(); // Condition for notifying thread waiting for orb
    private AtomicInteger threadsAlive = new AtomicInteger(0); // Counter for threads currently running

    public static void main(String[] args) {
