    List<Crystal> crystals = new ArrayList<>();
    int head, tail;
    AtomicInteger availableSlots = new AtomicInteger(MAX_CAPACITY);
    AtomicInteger availableCrystals = new AtomicInteger(0);
    ReentrantLock lock = new ReentrantLock();
    Condition notFull = lock.newCondition();
    Condition notEmpty = lock.newCondition();

    Carousel() {
        head = tail = 0;
    }

    boolean isFull() {
        return availableSlots.get() == 0;
    }

    boolean isEmpty() {
        return availableCrystals.get() == 0;
    }

