        lock.lock();
        try {
            while (availableSlots.get() == 0 && !Thread.currentThread().isInterrupted()) {
                notFull.await();
            }
            if (Thread.currentThread().isInterrupted()) {
                return;
            }
            int next = (tail + 1) % MAX_CAPACITY;
            crystals.set(next, crystal);
            tail = next;
            availableSlots.decrementAndGet();
            notEmpty.signalAll();
        } finally {
            lock.unlock();
        }
    }

    Crystal take() throws InterruptedException {
        lock.lock();
        try {
            while (availableCrystals.get() == 0 && !Thread.currentThread().isInterrupted()) {
