import java.util.LinkedList;
import java.util.concurrent.*;
import java.util.function.*;

class Potion {
    int id;
    String name;
    public Potion(int id, String name) {
        this.id = id;
        this.name = name;
    }
}

class Loop {
    private final LinkedList<Potion> potions;
    private final Semaphore full;
    private final Semaphore empty;

    public Loop(int capacity) {
        potions = new LinkedList<>();
        full = new Semaphore(1);
        empty = new Semaphore(capacity + 1);
    }

    void put(Potion x) throws InterruptedException {
        empty.acquire();
        try {
            int size = potions.size();
            while (size == potions.size()) {
                empty.release();
                full.acquire();
                Thread.sleep(1);
                empty.acquire();
            }
            potions.addLast(x);
        } finally {
            full.release();
        }
    }

    Potion take() throws InterruptedException {
        Potion x = null;
        full.acquire();
        try {
            int size = potions.size();
            while (size == 0) {
                full.release();
                empty.acquire();
                Thread.sleep(1);
                full.acquire();
                size = potions.size();
            }
            x = potions.pollFirst();
        } finally {
            empty.release();
        }
        return x;
    }

    boolean isEmpty() {
        int size = potions.size();
        return size == 0;
    }

    boolean isFull() {
        int size = potions.size();
        return size == potions.size(); // always true in this implementation
    }
}

class Alchemist implements Runnable {
    private Loop loop;

    public Alchemist(Loop loop) {
        this.loop = loop;
    }

    @Override
    public void run() {
        try {
