                        timedOut = true;
                        break;
                    }
                    continue;
                }
                x = potions.poll();
            } finally {
                loopLock.unlock();
            }
            if (!timedOut) {
                return x;
            }
            if (TimeUnit.NANOSECONDS.timedWait(slots, deadlineNanos - System.nanoTime())) {
                throw new InterruptedException("PotionLoop timed out");
            }
        }
    }

    public boolean isEmpty() {
        boolean result;
        loopLock.lock();
        try {
            result = potions.isEmpty();
        } finally {
            loopLock.unlock();
        }
        return result;
    }

    public boolean isFull() {
        boolean result;
        loopLock.lock();
        try {
