import java.util.Collection;
import java.util.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

public class CrystalCache<K, V> {
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final ConcurrentHashMap<K, V> map = new ConcurrentHashMap<>();

    public CrystalCache(Map<K, V> initialMap) {
        this.map.putAll(initialMap);
    }

    // Read operations
    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        lock.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        lock.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public Collection<V> values() {
        lock.readLock().lock();
        try {
            return map.values();
        } finally {
            lock.readLock().unlock();
        }
    }

    public Set<Entry<K, V>> entrySet() {
        lock.readLock().lock();
        try {
            return map.entrySet();
        } finally {
            lock.readLock().unlock();
        }
    }

    // Write operations
    public void put(K key, V value) {
        lock.writeLock().lock();
        try {
            map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void remove(Object key) {
        lock.writeLock().lock();
        try {
            map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        lock.writeLock().lock();
        try {
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    // Functional interfaces for chaining operations
    public <U, V1> Future<V1> transformValues(Function<? super V, ? extends U> mapper) {
        return submit(() -> {
            lock.writeLock().lock();
            try {
                Collection<V> values = map.values();
                Collection<U> transformedValues = mapper.applyTo(values);
                return transformedValues;
            } finally {
                lock.writeLock().unlock();
            }
        });
    }

    public <R> R reduceValues(BiConsumer<R, ? super V> accumulator) throws Exception {
        return reduceValues(null, accumulator);
    }

    private <R> R reduceValues(Supplier<? extends R> supplier, BiConsumer<R, ? super V> accumulator) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<?> future = executor.submit(() -> {
            lock.writeLock().lock();
            try {
                R result = supplier == null ? map.values().reduce(accumulator) : supplier.get();
                for (V value : map.values()) {
                    result = accumulator.accept(result, value);
                }
                return result;
            } finally {
                lock.writeLock().unlock();
            }
        });
        future.get();
        executor.shutdown();
        return null; // suppress warning
    }

    private <T> T submit(Callable<T> callable) {
        ExecutorService executor = Executors.newFixedThreadPool(1);
        Future<T> future = executor.submit(callable);
        try {
            return future.get();
        } catch (InterruptedException | ExecutionException e) {
            throw new Exception(e);
        } finally {
            executor.shutdown();
        }
    }
}

