import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.util.function.*;

public class EnchantedRegistry {
    private final Map<String, Integer> artifacts;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private int readCount = 0;
    private int writeCount = 0;

    public EnchantedRegistry(Map<String, Integer> initialArtifacts) {
        this.artifacts = Collections.unmodifiableMap(initialArtifacts);
    }

    public void addObserver() {
        lock.readLock().lock();
        readCount++;
        lock.readLock().unlock();
    }

    public void removeObserver() {
        lock.readLock().lock();
        readCount--;
        lock.readLock().unlock();
    }

    public int getReadCount() {
        lock.readLock().lock();
        int count = readCount;
        lock.readLock().unlock();
        return count;
    }

    public int getWriteCount() {
        lock.readLock().lock();
        int count = writeCount;
        lock.readLock().unlock();
        return count;
    }

    public void addCrafter(Callable<Void> task) throws ExecutionException, InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        pool.submit(task).get();
        pool.shutdownNow();
    }

    public int getArtifact(String key) {
        lock.readLock().lock();
        try {
            return artifacts.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public Set<String> getKeys() {
        lock.readLock().lock();
        try {
            return Collections.unmodifiableSet(artifacts.keySet());
        } finally {
            lock.readLock().unlock();
        }
    }

    public Collection<Integer> getValues() {
        lock.readLock().lock();
        try {
            return Collections.unmodifiableCollection(artifacts.values());
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(String key) {
        lock.readLock().lock();
        try {
            return artifacts.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Integer value) {
        lock.readLock().lock();
        try {
            return artifacts.values().asList().stream().anyMatch(value::equals);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return artifacts.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public void put(String key, Integer value) {
        lock.writeLock().lock();
        try {
            int prevSize = artifacts.size();
            artifacts.put(key, value);
            writeCount++;
            int newSize = artifacts.size();
            if (newSize > prevSize) {
                System.out.printf("New item added: (%s, %d)\n", key, value);
            }
        } finally {
            lock.writeLock().unlock();
