            int value = counter.get();
            while (counter.compareAndSet(value, value + 1)) {
                // Keep spinning until successful increment or timeout
                TimeUnit.MILLISECONDS.sleep(10);
            }
            return counter.get();
        });
        Future<Integer> future2 = service.submit(() -> {
            int value = counter.get();
            while (!counter.compareAndSet(value, value + 1)) {}
            return counter.get();
        });
        int sum = future1.get() + future2.get();
        service.shutdown();
        System.out.println("Sum: " + sum);
