import java.util.concurrent.*;

public class MysticCounter {
    private int essence;
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public MysticCounter() {
        essence = 0;
    }

    public synchronized int get() {
        return essence;
    }

    public synchronized int compareAndSwap(int expectedEssence, int newEssence) {
        return essence == expectedEssence ? (essence = newEssence) : essence;
    }

    public boolean compareAndSet(int expectedEssence, int newEssence) {
        return compareAndSwap(expectedEssence, newEssence) != expectedEssence;
    }

    public void increment() {
        executor.submit(() -> essence = essence + 1).get();
    }

    public void decrement() {
        executor.submit(() -> essence = essence - 1).get();
    }

    public static void main(String[] args) throws Exception {
        MysticCounter counter = new MysticCounter();
