class Spellbook {
    private static final Spellbook INSTANCE = new Spellbook();

    private Spellbook() {}

    public static Spellbook getInstance() { return INSTANCE; }

    void invokeSpell() { System.out.println("Abracadabra!"); }
}

class ThreadSafeSpellbook extends Spellbook {
    private static final ExecutorService threadPool = Executors.newFixedThreadPool(4);

    @Override
    void invokeSpell() {
        try {
            threadPool.execute(() -> { System.out.println("Abracadabra!"); });
        } catch (RejectedExecutionException e) {
            // Ignore rejection due to max thread pool size
        } finally {
            threadPool.shutdown();
        }
    }
