        spellbook.invokeSpell();

        exec.shutdown();

        try {
            exec.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {} finally {
            System.out.println("Ritual complete!");
