    }

    private static Constellation<String, MutableOrb> deepClone(Constellation<String, MutableOrb> constellation) {
        return new Constellation<>(Collections.list(constellation.entrySet().stream()
                .map(entry -> Map.entry(entry.getKey(), deepClone(entry.getValue())))
                .collect(Collectors.toMap(Entry::getKey, Entry::getValue))).entrySet());
