class Constellation<K, V> {
    private final Map<K, V> orbMap;
    private final int width, height;

    public Constellation(Collection<K> keys, Collection<V> values) {
        this.orbMap = Collections.unmodifiableMap(new LinkedHashMap<>(Maps.uniqueKeys(Maps.transformValues(values::deepClone)), Maps.uniqueValues(values)));
        this.width = Math.max(orbMap.size(), 10);
        this.height = orbMap.size() / width + 1;
    }

    public Map<K, V> orbMap() {
        return orbMap;
    }

    public int getWidth() {
        return width;
    }

    public int getHeight() {
        return height;
    }
}

class MutableOrb implements Cloneable {
