import static java.util.concurrent.TimeUnit.SECONDS;

public class ChronomanticDragonTracker {
    private final Constellation<String, MutableOrb> constellation;
    private final Set<Thread> threads = new CopyOnWriteArraySet<>();

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> constellation) {
        this.constellation = deepClone(constellation);
    }

    private static <K, V> Constellation<K, V> deepClone(Constellation<K, V> constellation) {
        return new Constellation<>(constellation.keySet(), Collections.list(constellation.values()).stream()
                .map(v -> (V) v.deepClone())
                .collect(Collectors.toList()));
    }

    private synchronized MutableOrb getOrb(String sigil) {
        Map<String, MutableOrb> orbMap = constellation.orbMap();
        return orbMap.get(sigil);
    }

    public synchronized Collection<MutableOrb> getConstellations() {
        return Collections.unmodifiableCollection(constellation.values());
    }

    private synchronized void setOrb(String sigil, int shimmerX, int shimmerY) throws IllegalArgumentException {
        MutableOrb orb = constellation.orbMap().get(sigil);
        if (orb == null) {
            throw new IllegalArgumentException("Sigil \"" + sigil + "\" not found");
        }
        orb.setShimmerX(shimmerX);
        orb.setShimmerY(shimmerY);
    }

    public void updateOrbs() throws InterruptedException {
        ExecutorService service = Executors.newFixedThreadPool(2, r -> {
            Thread thread = new Thread(r);
            thread.setDaemon(true);
            return thread;
        });
        try {
            Future<Void> future1 = service.submit(() -> IntStream.rangeClosed(1, 50).parallel().forEach(i -> moveOrb("D" + i)));
            Future<Void> future2 = service.submit(() -> IntStream.rangeClosed(51, 100).parallel().forEach(i -> moveOrb("K" + i)));
            future1.get(10, SECONDS);
            future2.get(10, SECONDS);
        } finally {
            service.shutdown();
        }
    }

    private void moveOrb(String sigil) {
        MutableOrb orb = constellation.orbMap().get(sigil);
        int shimmerX = orb.getShimmerX();
        int shimmerY = orb.getShimmerY();
        int newX = (shimmerX + 10) % constellation.width();
        int newY = (shimmerY + 7) % constellation.height();
        setOrb(sigil, newX, newY);
    }

    public static void main(String[] args) throws InterruptedException {
        Constellation<String, MutableOrb> initialConstellation = createInitialConstellation();
        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initialConstellation);

        // Add threads for updating orbs concurrently
        tracker.updateOrbs();

        Set<Thread> runningThreads = new HashSet<>(Arrays.asList(Thread.currentThread(), threads));
        while (!runningThreads.isEmpty()) {
            Thread.sleep(500);
            runningThreads.removeIf(Thread::isInterrupted || Thread::isDaemon);
        }

        Collection<MutableOrb> finalConstellations = tracker.getConstellations();
        System.out.println("Final constellation:");
        for (MutableOrb orb : finalConstellations) {
            System.out.printf("Sigil: %s, Shimmer: (%d, %d)\n", orb.getSigil(), orb.getShimmerX(), orb.getShimmerY());
        }
    }

    private static Constellation<String, MutableOrb> createInitialConstellation() {
        Map<String, MutableOrb> orbMap = new HashMap<>();
        orbMap.put("D1", new MutableOrb("Dragon 1"));
        orbMap.put("D2", new MutableOrb("Dragon 2"));
        orbMap.put("D50", new MutableOrb("Dragon 50"));
        orbMap.put("K51", new MutableOrb("Kraken 51"));
        orbMap.put("K52", new MutableOrb("Kraken 52"));
        orbMap.put("K100", new MutableOrb("Kraken 100"));
        return new Constellation<>(orbMap.keySet(), Collections.list(orbMap.values()));
    }
