public final class MysticSeahorseTracker {

    private static final int DEFAULT_SWIRL_X = 5;
    private static final int DEFAULT_SWIRL_Y = 10;

    private final ConcurrentMap<String, MutableShell> bubbleMap;
    private final ScheduledExecutorService threadPool;

    public MysticSeahorseTracker(BubbleMap<String, MutableShell> initialBubbleMap) {
        this.bubbleMap = newDeepCopyOfBubbleMap(initialBubbleMap);
        this.threadPool = Executors.newFixedThreadPool(2);
