    @SuppressWarnings("unchecked")
    private static <K, V> Map<K, V> newDeepCopyOfBubbleMap(Map<K, V> original) {
        // Perform deep copy using the same implementation as in java.util.Collections
        ConcurrentHashMap<K, V> result = new ConcurrentHashMap<>();
        for (Map.Entry<K, V> entry : original.entrySet()) {
            Object value = entry.getValue();
            if (value instanceof Map) { // Recursively copy nested maps
                value = newDeepCopyOfBubbleMap((Map<Object, Object>) value);
            }
            result.put(Objects.requireNonNull(entry.getKey()), value);
        }
        return result;
    }

