    public synchronized void setShell(String rune, int swirlX, int swirlY) {
        MutableShell shell = bubbleMap.get(rune);
        if (shell == null) {
            throw new IllegalArgumentException("Rune " + rune + " is not present in the tracker");
        }
        shell.setSwirlX(swirlX != DEFAULT_SWIRL_X ? swirlX : DEFAULT_SWIRL_X);
        shell.setSwirlY(swirlY != DEFAULT_SWIRL_Y ? swirlY : DEFAULT_SWIRL_Y);
    }

    // Implemented using a fixed thread pool with 2 threads to limit the number of threads
    public void startCurrents() {
        Runnable currentTask = () -> {
            List<MutableShell> currents = new ArrayList<>();
            Random random = ThreadLocalRandom.current();
            for (MutableShell shell : bubbleMap.values()) {
                int swirlX = shell.getSwirlX();
                int swirlY = shell.getSwirlY();
                int newX = swirlX + random.nextInt(2) - 1;
                int newY = swirlY + random.nextInt(2) - 1;
                currents.add(new MutableShell(shell.getRune(), newX, newY));
            }
            threadPool.submit(() -> bubbleMap.replaceAll((key, value) -> {
                MutableShell newValue = currents.remove(currents.size() - 1);
                if (newValue != null && Objects.equals(key, newValue.getRune())) {
                    return newValue;
                }
                return value;
            }));
        };
        threadPool.execute(currentTask);
        ScheduledExecutorService scheduledThreadPool = Executors.newSingleThreadScheduledExecutor(threadPool::shutdownNow);
        scheduledThreadPool.scheduleAtFixedRate(currentTask, 10, 500, TimeUnit.MILLISECONDS); // Schedule currents to run every half second
    }

    public void stopCurrents() {
        threadPool.shutdown();
        Executors.newSingleThreadScheduledExecutor(threadPool::shutdownNow).shutdown();
    }

    public Stream<MutableShell> streamCurrentsAfter(long delayMillis) throws InterruptedException {
        threadPool.execute(() -> startCurrents());
        Thread.sleep(delayMillis); // Wait for currents to start
        return bubbleMap.values().stream();
    }

    public Stream<MutableShell> streamCurrentsBetween(String sourceRune, String destRune) {
        Queue<MutableShell> queue = new LinkedList<>();
        BiConsumer<MutableShell, MutableShell> consumer = (source, destination) -> queue.addAll(destination.getConnected());
        bubbleMap.values().stream()
                .filter(sourceRune::equals)
                .flatMap(source -> {
                    List<MutableShell> connected = new ArrayList<>();
                    bubbleMap.values().stream()
                            .filter(destinationRune -> !Objects.equals(destinationRune, sourceRune))
                            .peek(destinationRune -> bubbleMap.forEach((key, value) -> {
                                if (value == source || value == destinationRune) {
                                    consumer.accept(source, value);
                                }
                            }))
                            .collect(Collectors.toCollection(() -> connected));
                    return bubbleMap.keySet().stream()
                            .filter(destinationRune::equals)
                            .flatMapToInt(bubbleMap::getOrDefault)
                            .boxed()
                            .map(Function.from(bubbleMap::get))
                            .collect(Collectors.toList())
                            .stream();
                })
                .peek(source -> bubbleMap.forEach((key, value) -> {
                    if (value == source || Objects.equals(sourceRune, key)) {
                        consumer.accept(value, source);
                    }
                }))
                .collect(Collectors.toList())
                .stream()
                .flatMap(this::flatStream) // Flatten the stream of lists
                .distinct() // Remove duplicates
                .collect(Collectors.toUnmodifiableList()); // Collect the result into an unmodifiable list
        return queue.stream().peek(MutableShell::clearConnected); // Clear the connections of each shell to prevent memory leaks
    }

    private Stream<MutableShell> flatStream(MutableShell shell) {
        List<MutableShell> connected = bubbleMap.getOrDefault(shell.getRune(), Collections.emptyList());
        return connected.stream() // Stream of connected shells
                .flatMap(this::flatStream); // Recursively apply the flatStream method to each connected shell
    }

    private static class MutableShell {
        private final String rune;
        private int swirlX = DEFAULT_SWIRL_X;
        private int swirlY = DEFAULT_SWIRL_Y;
        private List<MutableShell> connected = new ArrayList<>(); // Connected shells, used for finding a path between seahorses

        public MutableShell(String rune, int swirlX, int swirlY) {
