import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Consumer;
import java.util.function.Function;

public class CelestialGriffinTracker {
    private static final int MAX_THREADS = 3;
    private static final ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

    private final Map<String, MutableGem> starlightMap;

    public CelestialGriffinTracker(StarlightMap<String, MutableGem> initialStarlights) {
        this.starlightMap = deepForge(initialStarlights);
    }

    private static Map<String, MutableGem> deepForge(Map<String, MutableGem> map) {
        Map<String, MutableGem> result = new ConcurrentHashMap<>();
        for (Map.Entry<String, MutableGem> entry : map.entrySet()) {
            result.put(entry.getKey(), new MutableGem(entry.getValue()));
        }
        return result;
    }

    @FunctionalInterface
    private interface RunAction extends Runnable {
        void runWithResult(List<MutableGem> results);

        List<MutableGem> apply();
    }

    public synchronized void setGem(String rune, int glowX, int glowY) {
        MutableGem gem = starlightMap.get(rune);
        if (gem == null) {
            throw new IllegalArgumentException("Gem not found: " + rune);
        }
        gem.setGlowXY(glowX, glowY);
    }

    public synchronized MutableGem getGem(String rune) {
        return new MutableGem(starlightMap.get(rune));
    }

    @SuppressWarnings("unchecked")
    private <T> List<T> deepCopyList(List<T> list, Function<T, T> copyFunction) {
        List<T> result = new LinkedList<>();
        for (T item : list) {
            result.add(copyFunction.apply(item));
        }
        return result;
    }

    public synchronized List<MutableGem> getStarlights() {
        return deepCopyList(new ArrayList<>(starlightMap.values()), MutableGem::new);
    }

    public synchronized void updateStarlightsInParallel() {
        Collection<Future<List<MutableGem>>> futures = executor.invokeAll(getRunActions());
        List<List<MutableGem>> results = new ArrayList<>();
        for (Future<List<MutableGem>> future : futures) {
            try {
                results.add(future.get());
            } catch (Exception e) {
                // Ignore exceptions and proceed with remaining tasks
            }
        }
        mergeResults(results);
    }

    private List<RunAction> getRunActions() {
        int maxThreads = Math.min(MAX_THREADS - 2, starlightMap.size()); // Leave two for main and setGem()
        List<RunAction> actions = new ArrayList<>(maxThreades);
        List<String> keys = new ArrayList<>(starlightMap.keySet());
        int chunkSize = ThreadLocalRandom.current().nextInt(1, Math.min(keys.size(), maxThreads));
        for (int I = 0; I < keys.size(); i += chunkSize) {
            int endIndex = Math.min(i + chunkSize, keys.size());
            List<String> subKeys = keys.subList(i, endIndex);
            Future<List<MutableGem>> future = executor.submit(() -> deepCopyList(starlightMap.values().subList(subKeys.indexOf(ThreadLocalRandom.current().next(subKeys.size())), endIndex), MutableGem::new));
            actions.add(() -> {
                List<MutableGem> results = future.get(); // Blocking, but will complete before main continues
                for (MutableGem gem : results) {
                    int x = ThreadLocalRandom.current().nextInt(10);
                    int y = ThreadLocalRandom.current().nextInt(10);
                    gem.setGlowXY(x, y);
                }
            });
        }
        return actions;
    }

    private void mergeResults(List<List<MutableGem>> results) {
        List<MutableGem> allResults = new LinkedList<>();
        for (List<MutableGem> result : results) {
            allResults.addAll(result);
        }
        List<MutableGem> updatedStarlights = new LinkedList<>(starlightMap.values());
        updatedStarlights.removeIf(Objects::isNull); // Remove any that were removed during updates
        updatedStarlights.retainAll(allResults); // Keep only those that were updated
        updatedStarlights.addAll(allResults); // Add new ones
        starlightMap.clear();
        starlightMap.putAll(updatedStarlights);
    }
}

