import java.util.stream.Collectors;

public class ChronoCrystalBalancer {
    public static void main(String[] args) {
        ExecutorService pool = Executors.newFixedThreadPool(3);

        List<Crystal> crystals = Arrays.asList(
                new Crystal("c1"), new Crystal("c2"), new Crystal("c3"),
                new Crystal("c4"), new Crystal("c5")
        );
        AtomicInteger index = new AtomicInteger();
        List<Thread> threads = crystals.stream()
                .map(crystal -> {
                    final int crystalIndex = index.getAndIncrement();
                    return pool.submit(() -> runCrystal(crystal, crystalIndex));
                })
                .collect(Collectors.toList());

        try {
            threads.forEach(Thread::join);
        } catch (InterruptedException e) {
            // Ignore
        } finally {
            pool.shutdownNow();
        }
    }

    private static void runCrystal(Crystal crystal, int index) {
        for (int iteration = 0; iteration < 10; iteration++) {
            int fromIndex = index;
            int toIndex = index;
