            } catch (InsufficientChronoException e) {
                // Ignore
            }
        }
    }

    private static int getRandomIndex(Collection<Crystal> crystals, int excludeIndex) {
        int index = ThreadLocalRandom.current().nextInt(0, crystals.size());
        while (index == excludeIndex) {
            index = ThreadLocalRandom.current().nextInt(0, crystals.size());
        }
        return index;
    }

