                int toAmount = to.getChronoAmount();
                Duration shiftDuration = ChronoUnit.NANOS.between(from.getChronoInstant(), to.getChronoInstant());
                long minShard = Math.min(amount.getAmount(), Math.max(0, fromAmount - toAmount));
