                int shardAmount = ThreadLocalRandom.current().nextInt((int) maxShard, (int) minShard + 1);
                if (shardAmount > 0 && shiftDuration.compareTo(MIN_SHIFT) >= 0) {
                    ChronoInstant newFromInstant = from.getChronoInstant().plusNanos(shiftDuration.multipliedBy(MIN_AMOUNT - shardAmount).negate());
                    ChronoInstant newToInstant = to.getChronoInstant().minusNanos(shiftDuration.multipliedBy(shardAmount));
                    int fromNewAmount = Math.max(0, fromAmount - shardAmount);
                    int toNewAmount = Math.min(toAmount + shardAmount, MAX_AMOUNT);
                    from.setChronoAmount(fromNewAmount);
                    to.setChronoAmount(toNewAmount);
