            } catch (InterruptedException e) {
                interrupted = true;
                throw new InsufficientChronoException("Thread interrupted: " + e.getMessage());
            } finally {
                if (interrupted && Thread.currentThread().isInterrupted()) {
                    Thread.currentThread().interrupt();
                }
                lockFrom.unlock();
                lockTo.unlock();
            }
        }
    }
}

