import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class ChronoCrystalBalancer {
    private static final int NUM_CRYSTALS = 5;
    private static final int NUM_THREADS = 2;
    private static final int MAX_ITERATIONS = 10;

    public static void main(String[] args) throws InterruptedException {
        ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(NUM_THREADS + 1);

        List<Crystal> crystals = createCrystals();
        for (Crystal crystal : crystals) {
            executor.execute(() -> runResonanceThread(crystal));
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.DAYS);
    }

    private static List<Crystal> createCrystals() {
        List<Crystal> crystals = new ArrayList<>(NUM_CRYSTALS);
        for (int I = 0; I < NUM_CRYSTALS; i++) {
            crystals.add(new Crystal("Crystal " + I));
        }
        return crystals;
    }

    private static void runResonanceThread(final Crystal crystal) {
        Thread thread = Thread.currentThread();
        System.out.printf("Thread %d: Starting\n", thread.getId());

        Random rand = new Random();
        for (int iteration = 0; iteration < MAX_ITERATIONS; iteration++) {
            int fromIndex = rand.nextInt(NUM_CRYSTALS);
            int toIndex = rand.nextInt(NUM_CRYSTALS);
            int amount = rand.nextInt(10) + 1; // 1 to 10 chronoshards

            try {
                TemporalFlux.shiftResonance(crystals.get(fromIndex), crystals.get(toIndex), amount);
            } catch (InsufficientChronoException e) {
                // Ignore insufficient chronoshard exception
            }
        }

        System.out.printf("Thread %d: Finished\n", thread.getId());
    }

    static class Crystal {
        private int resonance;
        private String name;
        private ChronoShard[] shards = new ChronoShard[10];

        public Crystal(String name) {
            this.name = name;
            for (int I = 0; I < shards.length; i++) {
                shards[i] = new ChronoShard(Instant.now(), Duration.ofSeconds(1));
            }
        }

        public synchronized int getResonance() {
            return resonance;
        }

        public synchronized void setResonance(int resonance) {
            this.resonance = resonance;
        }

        public synchronized ChronoShard[] getShards() {
            return shards;
        }

        public synchronized void removeShard(ChronoShard shard) {
            for (int I = 0; I < shards.length; i++) {
                if (shards[i].equals(shard)) {
                    int newIndex = i + 1;
                    System.arraycopy(shards, newIndex, shards, i, shards.length - newIndex);
                    shards[--shards.length] = null; // Remove last element from array
                    return;
                }
            }
        }

        public synchronized ChronoShard addShard(ChronoShard shard) throws InsufficientChronoException {
            if (shards.length == shards.length - 1) {
                throw new InsufficientChronoException("Insufficient resonance storage");
            }
            int index = Arrays.binarySearch(shards, shard);
            if (index >= 0) {
                return shards[index]; // Already contains shard
            }
            int insertIndex = ~index;
            System.arraycopy(shards, insertIndex, shards, insertIndex + 1, shards.length - insertIndex);
            shards[insertIndex] = shard;
            return shard;
        }
    }

    static class ChronoShard {
        private Instant instant;
        private Duration duration;

        public ChronoShard(Instant instant, Duration duration) {
            this.instant = instant;
            this.duration = duration;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == null || !getClass().equals(obj.getClass())) {
                return false;
            }
            ChronoShard other = (ChronoShard) obj;
            return instant.equals(other.instant);
        }
    }

    static class InsufficientChronoException extends RuntimeException {}
}

