        int availableToShards = countAvailableShards(to.getShards());
        int totalAmount = Math.min(availableFromShards, availableToShards + amount);

        List<ChronoShard> toRemove = removeShards(from.getShards(), totalAmount);
        List<ChronoShard> toAdd = addShards(to.getShards(), totalAmount);

        from.removeShards(toRemove);
        to.addShards(toAdd);
