    private static int countAvailableShards(ChronoShard[] shards) {
        int available = 0;
        for (ChronoShard shard : shards) {
            Instant now = Instant.now();
            Duration duration = shard.duration;
            if (duration == null || !shard.instant.plus(duration).isAfter(now)) {
                available += getAmount(shard);
            }
        }
        return available;
