    private boolean flowing;
    private long sandStart, sandEnd;

    public void run() {
        synchronized (this) {
            if (!flowing) {
                sandStart = System.nanoTime();
                flowing = true;
            } else {
                sandEnd = System.nanoTime();
            }
            executor.submit(this).start(); // Start new thread for next run
        }
    }

    public synchronized void reset() {
        synchronized (executor) {
            flowing = false;
            sandStart = 0L;
            sandEnd = 0L;
            executor.shutdownNow(); // Stop all running tasks and interrupt any waiting tasks
            executor = Executors.newFixedThreadPool(2); // Reduce thread pool size
        }
    }

    public long getDrift() {
        synchronized (this) {
            return sandEnd - sandStart;
        }
    }
}

