Thread starter = new Thread(() -> {
timer.run();
});

Thread stopper = new Thread(() -> {
try {
Thread.sleep(500);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
timer.run();
});

starter.start();
stopper.start();

starter.join();
stopper.join();

System.out.println("Elapsed time in nanoseconds: " + timer.getTime());
System.out.println("Elapsed time in milliseconds: " + timer.getMillisTime());

timer.clear();
}
}

