class EnchantedCAS {
    private int value;
    private AtomicIntegerCAS counter = new AtomicIntegerCAS();

    public int get() {
        return value;
    }

    public boolean compareAndSwap(int expected, int newValue) {
        int current = counter.get();
        int prev = 0;
        do {
            prev = current & ~Integer.MAX_VALUE;
            if (counter.compareAndSet(current, prev + expected)) {
                value = newValue;
                return true;
            }
        } while (!counter.compareAndSet(prev, prev + expected));
        return false;
    }
