public class TransferService implements Runnable {
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    private final Account source;
    private final Account destination;
    private final DollarAmount amount;
    private final long timeout;
    private final TimeUnit timeUnit;

    public TransferService(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit timeUnit) {
        this.source = source;
        this.destination = destination;
        this.amount = amount;
        this.timeout = timeout;
        this.timeUnit = timeUnit;
    }

    @Override
    public void run() {
        try {
            boolean success = transfer();
            if (success) {
                System.out.format("%s -> %s: Success%n", source.getName(), destination.getName());
            } else {
                System.out.format("%s -> %s: Failed%n", source.getName(), destination.getName());
            }
        } catch (InsufficientFundsException e) {
            System.out.format("%s -> %s: Insufficient funds%n", source.getName(), destination.getName());
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            executor.shutdownNow();
        }
    }

    private boolean transfer() throws Exception {
        int backoff = new Random().nextInt(3); // Min 0, Max 2
        TimeUnit unit = TimeUnit.MILLISECONDS;
        long startTime = System.currentTimeMillis();
        boolean success = false;
        do {
            if (source.tryWithdraw(amount.getDollars(), timeout, timeUnit)) {
                destination.deposit(amount.getDollars());
                success = true;
            } else {
                long delay = Duration.between(Duration.ofMillis(startTime), Duration.ofNanos(System.nanoTime())).getSeconds() % unit.toMillis(1) + backoff * 500; // Min 500ms, Max 2s
                TimeUnit delayUnit = unit.shorterUnit();
                Thread.sleep(delay, TimeUnit.MILLISECONDS);
            }
        } while (!success && System.currentTimeMillis() - startTime < timeout + Duration.ofSeconds(1).toMillis()); // Max wait time of one second (timeout plus 1 second)
        return success;
    }

    public static void main(String[] args) throws Exception {
        Account source = new Account("Source");
        Account destination = new Account("Destination");
        DollarAmount amount = new DollarAmount(10, 0);
        long timeout = TimeUnit.SECONDS.toMillis(3); // Max 3 seconds
        TransferService service = new TransferService(source, destination, amount, timeout, TimeUnit.SECONDS);
        executor.submit(service);
        executor.awaitTermination(1, TimeUnit.SECONDS);
    }
}

