class Account {
    int balance;
    final ReentrantLock lock = new ReentrantLock();
    final Condition enoughFunds = lock.newCondition();

    public void transfer(Account destination, int amount) throws InsufficientFundsException {
        lock.lock();
        try {
            if (balance - amount >= 0) {
                int oldBalance = balance;
                balance -= amount;
                destination.deposit(amount);
                enoughFunds.signalAll();
                System.out.printf("Account %d: transferred $%d to Account %d, new balance: $%d\n", Thread.currentThread().getId(), amount, destination.id, balance);
                if (oldBalance == balance) {
                    throw new InsufficientFundsException();
                }
            } else {
                tryAcquire(lock, 500, TimeUnit.MILLISECONDS);
                transfer(destination, amount);
            }
        } finally {
            lock.unlock();
        }
    }

    void deposit(int amount) {
        lock.lock();
        try {
            balance += amount;
            enoughFunds.signalAll();
            System.out.printf("Account %d: deposited $%d, new balance: $%d\n", Thread.currentThread().getId(), amount, balance);
        } finally {
            lock.unlock();
        }
    }

    static class InsufficientFundsException extends Exception { }
}

