                    }
                });
        System.out.println("Thread " + Thread.currentThread().getId() + ": done.");
    }

    static ExecutorService executor = Executors.newFixedThreadPool(2);
    static Map<Integer, Account> accounts = new HashMap<>();

    private static void tryAcquire(ReentrantLock lock, long timeout, TimeUnit unit) {
        boolean acquired;
        do {
            try {
                acquired = lock.tryLock(timeout, unit);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                acquired = false;
            }
            if (!acquired && !Thread.currentThread().isInterrupted()) {
                try {
                    Thread.sleep(Math.min(10, TimeUnit.MILLISECONDS.convert(timeout - unit.toMillis(lock.getWaitQueueLength()), unit)));
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        } while (!acquired && !Thread.currentThread().isInterrupted());
    }
}

