class TransferTask implements Callable<Boolean> {
    private Account fromAccount;
    private Account toAccount;
    private DollarAmount amountToTransfer;
    private long timeoutDuration;
    private TimeUnit timeUnit;

    TransferTask(Account fromAccount, Account toAccount, DollarAmount amountToTransfer, long timeoutDuration, TimeUnit timeUnit) {
        this.fromAccount = fromAccount;
        this.toAccount = toAccount;
        this.amountToTransfer = amountToTransfer;
        this.timeoutDuration = timeoutDuration;
        this.timeUnit = timeUnit;
    }

    @Override
    public Boolean call() throws Exception {
        boolean result = false;
        try {
            boolean fromAcquired = fromAccount.lock(timeoutDuration, timeUnit).tryLock();
            boolean toAcquired = toAccount.lock(timeoutDuration, timeUnit).tryLock();
            if (fromAcquired && toAcquired) {
                double fromBalance = fromAccount.getBalance();
                double newFromBalance = fromBalance - amountToTransfer.doubleValue();
                if (newFromBalance >= 0) {
                    double newToBalance = toAccount.getBalance() + amountToTransfer.doubleValue();
                    toAccount.setBalance(newToBalance);
                    fromAccount.setBalance(newFromBalance);
                    result = true;
                } else {
                    throw new InsufficientFundsException("Insufficient funds in account " + fromAccount.getName() + ". Balance: $" + newFromBalance);
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            if (fromAccount.lock(timeoutDuration, timeUnit).tryLock()) {
                fromAccount.unlock();
            }
            if (toAccount.lock(timeoutDuration, timeUnit).tryLock()) {
                toAccount.unlock();
            }
        }
        return result;
    }
}

public class Main {
    private static final ExecutorService executor = Executors.newFixedThreadPool(2);
    private static final Random random = new Random();

    private static final long FIXED_DELAY = 10; // milliseconds
    private static final int MAX_RETRIES = 3;

    public static void main(String[] args) {
        Account sourceAccount = new Account("Source", 100);
        Account destinationAccount = new Account("Destination", 50);
        DollarAmount amountToTransfer = new DollarAmount(25);
        long timeoutDuration = TimeUnit.SECONDS.toMillis(3); // seconds

        Runnable transferRunner = () -> {
            Future<Boolean> future = executor.submit(new TransferTask(sourceAccount, destinationAccount, amountToTransfer, timeoutDuration, TimeUnit.SECONDS));
            try {
                boolean result = future.get();
                if (result) {
                    System.out.println("Transfer successful! From: $" + sourceAccount.getBalance() + ", To: $" + destinationAccount.getBalance());
                } else {
                    System.out.println("Transfer failed.");
                }
            } catch (ExecutionException | InterruptedException e) {
                System.err.println("Error transferring funds: " + e.getMessage());
            } finally {
                executor.shutdownNow();
            }
        };

        for (int retry = 0; retry < MAX_RETRIES; ++retry) {
            if (!transferRunner.run()) { // if transfer failed, retry with backoff
                long randomDelay = FIXED_DELAY + Math.max(1, retry) * random.nextInt(MAX_RETRIES - retry); // delay range: [FIXED_DELAY+1..MAX_RETRIES*MAX_RETRIES] milliseconds
                try {
                    Thread.sleep(randomDelay);
                } catch (InterruptedException e) {
                    System.err.println("Error sleeping thread: " + e.getMessage());
                }
            } else {
                return; // if transfer succeeded, exit main method
            }
        }

        System.out.println("Maximum retries exceeded."); // if maximum retry count is reached, print warning message and exit main method
    }
}

