public class BarrierTimer implements Runnable {
    private static final int THREAD_POOL_SIZE = 2;
    private static final ExecutorService threadPool = Executors.newFixedThreadPool(THREAD_POOL_SIZE + 1);

    private AtomicBoolean started = new AtomicBoolean(false);
    private long startTime, endTime;
    private LongAdder totalTime = new LongAdder();

    public void run() {
        if (started.getAndSet(true)) {
            endTime = System.nanoTime();
            totalTime.add(endTime - startTime);
        } else {
            startTime = System.nanoTime();
        }
    }

    public long getTime() {
        return Math.abs(endTime - startTime) + totalTime.sum();
    }

    public void clear() {
        started.set(false);
        endTime = 0;
        totalTime.reset();
    }

    private static class ThreadPoolWithTimeout implements Callable<Void> {
        private Runnable task;
        private long timeout, startTime;
        private int iterationCount = 2;
        private Random random = new Random(42);
        private boolean cancelled = false;

        public ThreadPoolWithTimeout(Runnable task, long timeout) {
            this.task = task;
            this.timeout = timeout;
            startTime = System.currentTimeMillis();
        }

        @Override
        public Void call() throws Exception {
            while (!cancelled && iterationCount-- > 0) {
                try {
                    task.run();
                    Thread.sleep(1); // simulate IO
                    int randomValue = random.nextInt(3);
                    System.out.println("Thread " + Thread.currentThread().getName() + " performed " + randomValue + " iterations.");
                } catch (Exception e) {
                    cancelled = true;
                    System.err.println("Thread " + Thread.currentThread().getName() + " caught an exception: " + e.getMessage());
                }
            }
            if (!cancelled && iterationCount == 0) { // time is up, but no exception was thrown
                cancelled = true;
                System.err.println("Thread " + Thread.currentThread().getName() + " timed out after " + (System.currentTimeMillis() - startTime) + " ms.");
            }
            return null;
        }
    }

    public static void main(String[] args) throws Exception {
        BarrierTimer timer = new BarrierTimer();
        ThreadPoolWithTimeout firstTask = new ThreadPoolWithTimeout(() -> timer.run(), 200L);
        threadPool.submit(firstTask).get(); // wait for the first task to complete
        Runnable secondTask = () -> {
            try (timer.clear()) {
                System.out.println("Timer was cleared.");
                timer.run();
                System.out.println("Second task finished: " + getTime() + " ns.");
            } catch (Exception e) {
                System.err.println("Caught exception: " + e.getMessage());
            }
        };
        threadPool.submit(secondTask).get(); // wait for the second task to complete
