import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class BoundedBuffer {
    private final int MAX_SIZE = 3;
    private Queue<Integer> buffer = new LinkedList<>();
    private Semaphore producerSem = new Semaphore(MAX_SIZE);
    private Semaphore consumerSem = new Semaphore(0);

    public void put(int x) throws InterruptedException {
        producerSem.acquire();
        buffer.offer(x);
        consumerSem.release();
    }

    public int take() throws InterruptedException {
        consumerSem.acquire();
        int x = buffer.poll();
        producerSem.release();
        return x;
    }

    public boolean isEmpty() {
        return buffer.isEmpty();
    }

    public boolean isFull() {
        return buffer.size() == MAX_SIZE;
    }

    public static void main(String[] args) throws Exception {
        BoundedBuffer bb = new BoundedBuffer();
        ThreadPoolExecutor pool = (ThreadPoolExecutor) Executors.newFixedThreadPool(3);

        Runnable producer1 = () -> {
            try {
                for (int i = 0; i < 2; i++) {
                    bb.put(i * 10);
                }
            } catch (InterruptedException e) {}
        };

        Runnable producer2 = () -> {
            try {
                for (int i = 0; i < 3; i++) {
                    bb.put(i * 11);
                }
            } catch (InterruptedException e) {}
        };

        Runnable consumer = () -> {
            try {
                int x;
                for (int I = 0; I < 5; i++) {
                    x = bb.take();
                    System.out.println("Consumed: " + x);
                }
            } catch (InterruptedException e) {}
        };

        pool.execute(producer1);
        pool.execute(producer2);
        pool.execute(consumer);

        boolean allDone = false;
        while (!allDone && !bb.isEmpty()) {
            try {
                TimeUnit.SECONDS.sleep(1);
            } catch (InterruptedException e) {}
            if (!pool.isTerminated()) {
                allDone = true;
                for (Runnable r : pool.getQueuedTasks()) {
                    pool.remove(r);
                }
                for (Runnable r : pool.getActiveThreads()) {
                    pool.returnExecute(r);
                }
            } else if (!bb.isEmpty()) {
                bb.producerSem.release();
            }
        }

        System.out.println("All tasks done: " + allDone);
    }
}

import java.util.ArrayDeque;
import java.util.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

public class BoundedBuffer {
    private static final int BUFFER_SIZE = 2; // adjust as needed
    private ArrayDeque<Integer> buffer = new ArrayDeque<>(BUFFER_SIZE);
    private Semaphore producerSemaphore = new Semaphore(BUFFER_SIZE);
    private Semaphore consumerSemaphore = new Semaphore(0);

    public void put(int x) throws InterruptedException {
        producerSemaphore.acquire(); // wait for space in buffer
        buffer.addLast(x);
        consumerSemaphore.release(); // notify waiting consumer
    }

    public int take() throws InterruptedException, TimeoutException {
        int x = -1;
        boolean timedOut = false;
        try {
            if (!consumerSemaphore.tryAcquire(10, TimeUnit.MILLISECONDS)) { // try to acquire in 10ms
                timedOut = true;
                consumerSemaphore.release(); // release resources for future tries
            } else {
                x = buffer.removeFirst();
            }
        } catch (InterruptedException e) {
            throw e;
        } finally {
            if (timedOut && !buffer.isEmpty()) { // handle partial fills with remaining items
                consumerSemaphore.release(BUFFER_SIZE - buffer.size());
            } else {
                consumerSemaphore.release();
            }
        }
        return x;
    }

    public boolean isEmpty() {
        return buffer.isEmpty();
    }

    public boolean isFull() {
        return buffer.size() == BUFFER_SIZE;
    }

    public static void main(String[] args) throws Exception {
        BoundedBuffer buffer = new BoundedBuffer();

        ExecutorService exec = Executors.newFixedThreadPool(2); // limit thread creation
        Runnable producer = () -> {
            try {
                for (int I = 0; I < 10; i++) {
                    buffer.put(i);
                    System.out.println("Produced: " + i);
                }
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        };
        Runnable consumer = () -> {
            try {
                for (int I = 0; I < 10; i++) {
                    int x = buffer.take();
                    System.out.println("Consumed: " + x);
                }
            } catch (InterruptedException | TimeoutException e) {
                e.printStackTrace();
            }
        };

        exec.submit(producer).get(); // wait for completion before proceeding
        System.out.println("Main thread ends.");

        exec.shutdownNow(); // terminate thread pool immediately
    }
}

