import java.math.BigInteger;
import java.util.concurrent.*;

public class CacheServlet {
    private static final ExecutorService exec = Executors.newFixedThreadPool(3);
    private static volatile Cache cache;

    public static void main(String[] args) {
        exec.execute(() -> {
            try {
                Thread.sleep(100); // simulate initialization time
                cache = new Cache(BigInteger.valueOf(42));
                System.out.println("Cache initialized: " + cache);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });
        exec.execute(() -> servletLoop());
        exec.execute(() -> servletLoop());
    }

    private static void servletLoop() {
        while (true) {
            try (Stream<String> req = System.in.lines()) {
                BigInteger input = new BigInteger(req.next().trim());
                Cache.Entry entry = cache.get(input);
                if (entry != null && entry.value().equals(input)) {
                    System.out.println("Cached result for " + input + ": " + entry.value());
                } else {
                    BigInteger result = new BigInteger("1");
                    Cache.Entry newEntry = cache.put(input, result);
                    if (newEntry != null && !entry.key().equals(input)) {
                        System.out.println("Stale entry found for " + entry.key() + ", replacing with " + input + ": " + newEntry.value());
                    }
                    System.out.println("Computed result for " + input + ": " + result);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    static class Cache {
        private final BigInteger value;
        private final ConcurrentMap<BigInteger, Entry> entries = new ConcurrentHashMap<>();

        public Cache(BigInteger value) {
            this.value = value;
        }

        Entry get(BigInteger key) {
            Entry entry = entries.get(key);
            if (entry != null && entry.expirationTime > System.currentTimeMillis()) {
                return entry;
            }
            return null;
        }

        Entry put(BigInteger key, BigInteger value) {
            Entry oldEntry = entries.putIfAbsent(key, new Entry(value, System.currentTimeMillis() + 1000));
            if (oldEntry == null || oldEntry.expirationTime <= System.currentTimeMillis()) {
                return new Entry(value, System.currentTimeMillis() + 1000);
            } else {
                return oldEntry;
            }
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder("Cache:");
            for (Map.Entry<BigInteger, Entry> entry : entries.entrySet()) {
                sb.append(entry.getKey()).append('=').append(entry.getValue().value()).append(';');
            }
            return sb.toString();
        }

        static class Entry {
            final BigInteger value;
            final long expirationTime;

            public Entry(BigInteger value, long expirationTime) {
                this.value = value;
                this.expirationTime = expirationTime;
            }
        }
    }
}

import java.math.BigInteger;
import java.net.HttpServlet;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Arrays;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class ConcurrentCacheServlet extends HttpServlet {
    private final static int MAX_THREADS = 3;
    private volatile ImmutableCache cache;

    @Override
    public void init() throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<ImmutableCache> future = executor.submit(() -> {
            BigInteger value = new BigInteger("1234567890");
            return new ImmutableCache(value, value);
        });
        try {
            cache = future.get(10, TimeUnit.SECONDS);
        } catch (Exception e) {
            // handle exceptions
        } finally {
            executor.shutdown();
        }
    }

    @Override
    protected void service(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        BigInteger input = new BigInteger(req.getQueryString());
        int cacheHitCount = 0;

        synchronized (cache) {
            ImmutableCache currentCache = cache;
            if (!currentCache.getValue().equals(input)) {
                ExecutorService executor = Executors.newFixedThreadPool(1);
                Future<ImmutableCache> future = executor.submit(() -> {
                    BigInteger value = input;
                    return new ImmutableCache(value, value);
                });
                try {
                    cache = future.get(10, TimeUnit.SECONDS);
                    cacheHitCount++;
                } catch (Exception e) {
                    // handle exceptions
                } finally {
                    executor.shutdown();
                }
            } else {
                cacheHitCount++;
            }
        }

        HttpURLConnection connection = (HttpURLConnection) resp.getOutputStream().unwrap(HttpURLConnection.class);
        connection.setRequestMethod("GET");
        connection.setRequestProperty("Cache-Control", "private, max-age=3600");
        connection.setResponseCode(200);
        connection.addRequestProperty("Content-Type", "application/octet-stream");
        byte[] content = Arrays.copyOf(cache.getValue().toByteArray(), cache.getValue().toByteArray().length + 4); // add size indicator
        content[content.length - 1] = (byte) cacheHitCount;
        connection.setRequestProperty("Content-Length", String.valueOf(content.length));
        connection.getOutputStream().write(content);
    }

    private static class ImmutableCache {
        final BigInteger value;
        final BigInteger result;

        public ImmutableCache(BigInteger value, BigInteger result) {
            this.value = value;
            this.result = result;
        }
    }
}

