public class ServerStatusBeforeSplit {
    private final Set<String> users = new HashSet<>();
    private final Set<String> queries = new HashSet<>();
    private final List<Runnable> tasks = new ArrayList<>();
    private static final int MAX_THREADS = 3;
    private static final ExecutorService THREAD_POOL = Executors.newFixedThreadPool(MAX_THREADS - 1);
    private static final Random RANDOM = new Random();

    public ServerStatusBeforeSplit() {
        // add some initial users and queries for testing
        users.add("user1");
        users.add("user2");
        queries.add("query1");
        queries.add("query2");
    }

    public synchronized void addUser(String u) {
        users.add(u);
    }

    public synchronized void removeUser(String u) {
        users.remove(u);
    }

    public synchronized void addQuery(String q) {
        queries.add(q);
    }

    public synchronized void removeQuery(String q) {
        queries.remove(q);
    }

    // helper method to run a task on the thread pool and handle exceptions
    private static void executeOnThreadPool(Runnable task) throws InterruptedException, ExecutionException {
        Future<Void> future = THREAD_POOL.submit(task);
        future.get();
    }

    // helper method to simulate user requests concurrently
    private static void simulateUserRequests() {
        ConcurrentLinkedQueue<String> requests = new ConcurrentLinkedQueue<>();
        int numRequests = RANDOM.nextInt(3) + 1; // generate a random number of requests per user
        int numUsers = RANDOM.nextInt(3) + 1; // generate a random number of users

        // add some requests for each user to the queue
        for (int I = 0; I < numUsers; i++) {
            String user = "user" + I;
            for (int j = 0; j < numRequests; j++) {
                requests.offer("request " + j + " from " + user);
            }
        }

        // run each request concurrently
        Collection<String> usersCopy = new HashSet<>(users); // create a copy to avoid modifying the original set inside the lambda expression
        executeOnThreadPool(() -> {
            for (String req : requests) {
                System.out.println(req + " by " + usersCopy.poll()); // simulate removing a user from the set when processing a request
            }
        });
    }

    public static void main(String[] args) throws Exception {
        ServerStatusBeforeSplit server = new ServerStatusBeforeSplit();
        executeOnThreadPool(() -> {
            for (int I = 0; I < 3; i++) { // simulate initial user requests
                String user = "user" + i;
                for (int j = 0; j < 2; j++) {
                    server.addUser(user);
                    server.addQuery("query " + j + " from " + user);
                }
            }
            // let the initial requests run for a short while before starting more concurrently
            TimeUnit.SECONDS.sleep(2);
            executeOnThreadPool(() -> {
                simulateUserRequests();
            });
        });
        // shutdown the thread pool and wait for all tasks to complete
        THREAD_POOL.shutdown();
        THREAD_POOL.awaitTermination(1, TimeUnit.SECONDS);
        System.out.println("Final user set: " + server.users);
        System.out.println("Final query set: " + server.queries);
    }
}

