    private static boolean debugLifecycle = false;
    private static int created = 0;
    private static int alive = 0;

    private final int id;
    private String name;

    public MyAppThread(Runnable r) {
        super(r);
        this.id = threadCounter.incrementAndGet();
        this.name = DEFAULT_NAME + "-" + this.id;
    }

    @Override
    public void run() {
        created++;
        try {
            super.run();
            alive++;
            if (debugLifecycle) {
                logger.info("Started thread: " + this);
            }
        } catch (Throwable e) {
            handleException(e);
        } finally {
            if (debugLifecycle && alive > 0) {
                logger.info("Ended thread: " + this);
            }
            alive--;
        }
    }

    private static void handleException(Throwable e) {
        logger.log(Level.SEVERE, String.format("%s: %s", getName(), e.getMessage()), e);
    }

    public static int getCreated() {
        return created;
    }

    public static int getAlive() {
        return alive;
    }

    public static boolean isDebugLifecycle() {
        return debugLifecycle;
    }

    public static void setDebugLifecycle(boolean debugLifecycle) {
        MyAppThread.debugLifecycle = debugLifecycle;
        if (debugLifecycle) {
            Handler consoleHandler = new ConsoleHandler();
            logger.setLevel(Level.ALL);
            logger.addHandler(consoleHandler);
            consoleHandler.setFormatter(new SimpleFormatter());
            logger.info("Debug lifecycle enabled");
        } else {
            logger.setUseParentHandlers(false);
            Handler[] handlers = logger.getHandlers();
            for (Handler handler : handlers) {
                logger.removeHandler(handler);
            }
        }
    }

    public static void main(String[] args) {
        ExecutorService pool = Executors.newFixedThreadPool(5);
        List<Callable<Integer>> tasks = new ArrayList<>();
        for (int I = 0; I < 2; i++) {
            tasks.add(() -> {
                int sum = 0;
                for (int j = 0; j < 1_000_000; j++) {
                    sum += j * 2 + 3;
                }
                return sum;
            });
        }
        List<Future<Integer>> results = pool.invokeAll(tasks);
        int sum = 0;
        for (Future<Integer> future : results) {
            try {
                sum += future.get();
            } catch (InterruptedException | ExecutionException e) {
                handleException(e);
            } finally {
                pool.shutdownNow();
            }
        }
        System.out.println("Sum: " + sum);
    }

    @Override
    public String toString() {
        Matcher matcher = Pattern.compile("-(\\d+)$").matcher(getName());
        if (matcher.matches()) {
            return getName(0, matcher.start("$1"));
        }
        return super.toString();
    }
}

