import java.util.function.Function;
import java.util.stream.Collectors;

class VehicleTracker {
    private final Map<String, Point> locations = new ConcurrentHashMap<>();
    private static ExecutorService threadPool = Executors.newFixedThreadPool(5);

    public VehicleTracker(Map<String, Point> initialLocations) {
        locations.putAll(initialLocations);
    }

    public List<Point> getLocations() {
        return new ArrayList<>(locations.values());
    }

    public Point getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        Point newLocation = new Point(x, y);
        locations.replace(id, newLocation);
    }

    public Map<String, Point> getLocationsAsStatic() {
        return new HashMap<>(locations);
    }

    public void moveAllVehicles(Function<Point, Point> transformer) throws ExecutionException, InterruptedException {
        List<Callable<Point>> tasks = locations.values().stream()
                .map(v -> () -> transformer.apply(v))
                .collect(Collectors.toList());
        List<Future<Point>> futures = threadPool.invokeAll(tasks);
        Map<String, Point> result = futures.stream().map(Future::get).collect(Collectors.toMap(Callable::call));
        locations.replaceAll((k, v) -> result.get(k));
    }
}

class DelegatingVehicleTracker extends VehicleTracker {
    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        super(initialLocations);
        threadPool.submit(() -> moveAllVehicles(v -> new Point(v.x - 1, v.y)));
        threadPool.submit(() -> moveAllVehicles(v -> new Point(v.x + 2, v.y)));
    }
}

public static void main(String[] args) throws Exception {
    Map<String, Point> initialLocations = Arrays.asList("a", "b")
            .collect(Collectors.toMap(k -> k, v -> new Point(v.x + 10, v.y)));
    DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);
    System.out.println("Initial locations: " + tracker.getLocationsAsStatic());
    Thread.sleep(100);
    System.out.println("After moveAllVehicles() and getLocations(): " + tracker.getLocations());
}

