import java.util.stream.Collectors;

public class DelegatingVehicleTracker {
    private static final int DEFAULT_THREAD_POOL_SIZE = 6;

    private final ConcurrentHashMap<String, Point> vehicles;
    private final ExecutorService executor;

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        vehicles = new ConcurrentHashMap<>(initialLocations);
        executor = Executors.newFixedThreadPool(DEFAULT_THREAD_POOL_SIZE - 1);
    }

    public List<Point> getLocations() {
        return Collections.unmodifiableList(vehicles.values().stream().collect(Collectors.toList()));
    }

    public Point getLocation(String id) {
        return vehicles.get(id);
    }

    public void setLocation(String id, int x, int y) {
        Objects.requireNonNull(id, "ID cannot be null");
        executor.submit(() -> vehicles.put(id, new Point(x, y))).get();
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(vehicles);
    }

    private static class MoveVehiclesTask implements Callable<Void> {
        private final List<Point> points;
        private final Random random;

        public MoveVehiclesTask(List<Point> points, Random random) {
            this.points = points;
            this.random = random;
        }

        @Override
        public Void call() throws Exception {
            int movesMade = 0;
            while (movesMade < points.size()) {
                int index = Math.abs(random.nextInt()) % points.size();
                Point point = points.get(index);
                point.x += random.nextInt(2) - 1;
                point.y += random.nextInt(2) - 1;
                movesMade++;
            }
            return null;
        }
    }

    public void simulateMovement(List<Point> points, long durationMillis) {
        Random random = ThreadLocalRandom.current().useSeed(System.nanoTime());
        List<Future<?>> futures = new ArrayList<>(points.size() / DEFAULT_THREAD_POOL_SIZE);
        int chunkSize = points.size() / (DEFAULT_THREAD_POOL_SIZE - 1);
        for (int I = 0; I < DEFAULT_THREAD_POOL_SIZE - 1; i++) {
            List<Point> chunk = points.subList(i * chunkSize, Math.min((i + 1) * chunkSize, points.size()));
            futures.add(executor.submit(new MoveVehiclesTask(chunk, random)));
        }
        try {
            boolean allFinished = false;
            while (!allFinished && System.currentTimeMillis() - System.nanoTime() / 1000000 < durationMillis) {
                int finished = 0;
                for (Future<?> future : futures) {
                    try {
                        future.get(1, TimeUnit.SECONDS);
                        finished++;
                    } catch (Exception e) {
                        // Ignore exceptions from failed tasks
                    }
                }
                allFinished = finished == futures.size();
            }
            if (!allFinished) {
                for (Future<?> future : futures) {
                    try {
