public class DynamicOrderDeadlock {
    private static final Lock lock1 = new ReentrantLock();
    private static final Lock lock2 = new ReentrantLock();

    public static void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        Lock currentLock;
        boolean firstTransfer = true;

        while (true) { // retry loop for lock contention
            if (firstTransfer) {
                firstTransfer = false;
                currentLock = lock1;
            } else {
                currentLock = lock2;
            }

            try {
                currentLock.lock();
                // transfer logic goes here
                BigDecimal fromAmount = from.getBalance().subtract(amount);

                if (fromAmount.compareTo(BigDecimal.ZERO) < 0) {
                    throw new InsufficientFundsException("Insufficient funds in account: " + from.getName());
                } else {
                    BigDecimal toAmount = to.getBalance().add(amount);
                    from.setBalance(fromAmount);
                    to.setBalance(toAmount);
                    System.out.printf("%s sent %d dollars to %s\n", from.getName(), amount, to.getName());
                }
            } finally {
                currentLock.unlock();
            }

            if (firstTransfer) {
                firstTransfer = false;
                currentLock = lock2;
            } else {
                currentLock = lock1;
            }
        }
    }
}

