    private static final Pattern NUMBER_PATTERN = Pattern.compile("-?\\d+");

    private volatile boolean cancelled = false;
    private List<Integer> primes = new ArrayList<>();

    public void start() {
        ExecutorService service = Executors.newSingleThreadExecutor();
        service.submit(this);
        service.shutdown();
        try {
            if (!service.awaitTermination(1, TimeUnit.SECONDS)) {
                service.shutdownNow();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void cancel() {
        this.cancelled = true;
    }

    public List<Integer> getPrimes() {
        return new ArrayList<>(primes);
    }

    @Override
    public void run() {
        try {
            int limit = getLimit();
            for (int I = 2; I < limit; i++) {
                if (!isComposite(i)) {
                    primes.add(i);
                }
            }
            Consumer<List<Integer>> consumer = lists -> System.out.println("Primes: " + lists);
            Supplier<List<Integer>> supplier = PrimeGenerator::getPrimes;
            Executors.newSingleThreadExecutor().submit(consumer.andThen(() -> {
                Consumer<List<Integer>> clearPrimesConsumer = lists -> primes.clear();
                Consumer<List<Integer>> addPrimesConsumer = lists -> primes.addAll(lists);
                Executors.newSingleThreadExecutor().submit(clearPrimesConsumer).get();
                Executors.newSingleThreadExecutor().submit(addPrimesConsumer, supplier).get();
                clearPrimesConsumer.andThen(() -> Executors.newSingleThreadExecutor().shutdownNow()).accept(lists);
            })).get();
        } catch (InterruptedException | ExecutionException e) {
            // Ignore exceptions and continue with cancellation
            cancel();
        } finally {
            if (!cancelled && !Thread.currentThread().isInterrupted()) {
                System.out.println("Program completed.");
            }
        }
    }

    private int getLimit() {
        String[] args = System.getProperties().getProperty("arg").split("\\s+");
        return args.length > 0 ? NUMBER_PATTERN.matcher(args[0]).parserInt() : Integer.MAX_VALUE;
    }

    private boolean isComposite(int n) {
        for (int I = 2; I * i <= n; i++) {
            if (n % i == 0) {
                return true;
            }
        }
        return false;
    }
}

