import java.util.stream.Collectors;

import static java.lang.Character.hashCode;
import static java.util.concurrent.Executors.newFixedThreadPool;
import static java.util.logging.Logger.getLogger;

class Node<K, V> {
    private final K key;
    private final V value;
    private Node<K, V> next;

    public Node(K key, V value) {
        this.key = key;
        this.value = value;
    }

    public K getKey() {
        return key;
    }

    public V getValue() {
        return value;
    }

    public Node<K, V> getNext() {
        return next;
    }

    public void setNext(Node<K, V> next) {
        this.next = next;
    }
}

class StripedMap<K, V> {
    private static final int N_BUCKETS = 1024;
    private static final int N_LOCKS = 16;

    private final Node[] buckets = new Node[N_BUCKETS];
    private final Lock[] locks = new ReentrantLock[N_LOCKS];

    StripedMap() {
        for (int I = 0; I < N_LOCKS; i++) {
            locks[i] = new ReentrantLock();
        }
    }

    private int hashIndex(K key) {
        return Math.abs(hashCode(key)) % N_BUCKETS;
    }

    private Node<K, V> getNodeAt(int index, K key) throws InterruptedException {
        locks[index % N_LOCKS].lock();
        try {
            Node<K, V> head = buckets[index];
            while (head != null && key.equals(head.getKey())) {
                head = head.getNext();
            }
            return head;
        } finally {
            locks[index % N_LOCKS].unlock();
        }
    }

    private Node<K, V> getNodeAt(int index) throws InterruptedException {
        locks[index % N_LOCKS].lock();
        try {
            return buckets[index];
        } finally {
            locks[index % N_LOCKS].unlock();
        }
    }

    private void setNodeAt(int index, Node<K, V> node) throws InterruptedException {
        locks[index % N_LOCKS].lock();
        try {
            Node<K, V> tail = buckets[index];
            Node<K, V> head = null;
            while (tail != null && !tail.getKey().equals(node.getKey())) {
                tail = tail.getNext();
                head = tail;
            }
            if (tail == node) {
                return;
            }
            Node<K, V> newNode = new Node<>(node.getKey(), node.getValue());
            if (head != null) {
                head.setNext(newNode);
            } else {
                buckets[index] = newNode;
            }
            tail.setNext(node);
        } finally {
            locks[index % N_LOCKS].unlock();
        }
    }

    private void clearNodesAt(int index) throws InterruptedException {
        locks[index % N_LOCKS].lock();
        try {
            Node<K, V> head = buckets[index];
            while (head != null) {
                Node<K, V> next = head.getNext();
                head = null;
                buckets[index] = next;
            }
        } finally {
            locks[index % N_LOCKS].unlock();
        }
    }

    public void put(K key, V value) throws InterruptedException {
        int index = hashIndex(key);
        Node<K, V> node = new Node<>(key, value);
        setNodeAt(index, node);
    }

    public V get(K key) throws InterruptedException {
        int index = hashIndex(key);
        Node<K, V> node = getNodeAt(index, key);
        return (node == null) ? null : node.getValue();
    }

    public void clear() throws InterruptedException {
        ExecutorService executor = newFixedThreadPool(4);
        int[] indices = IntStream.range(0, N_BUCKETS).parallel().mapToObj(i -> locks[i % N_LOCKS]).map(Lock::newExecutable).collect(Collectors.toList()).stream().map(Future::get).map(future -> {
            try {
                return future.get();
            } catch (Exception e) {
                throw new AssertionError(e);
            }
        }).toArray(int[]::new);
        executor.shutdown();
        System.arraycopy(indices, 0, buckets, 0, indices.length);
    }
}

class StripedMapTask implements Callable<Void> {
