public class StripedMap<K, V> {
    private static final int N_BUCKETS = 1024 * 8; // 8192 buckets
    private static final int N_LOCKS = 16;             // 16 locks for striping
    private Node[] buckets;                           // array of node entries
    private Object[] locks;                            // array of lock objects

    public StripedMap() {
        this.buckets = new Node[N_BUCKETS];
        this.locks = new Object[N_LOCKS];
        for (int I = 0; I < N_LOCKS; i++) {
            locks[i] = new Object();
        }
