    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> next;

        public Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }

    private int hashIndex(int hashCode) {
        return (N_BUCKETS - 1) & hashCode;
    }

    public V get(K key) throws NoSuchElementException {
        int index = hashIndex(System.identityHashCode(key));
        synchronized (locks[index % N_LOCKS]) {
            Node<K, V> current = buckets[index];
            while (current != null) {
                if (current.key.equals(key)) {
                    return current.value;
                }
                current = current.next;
            }
            throw new NoSuchElementException();
        }
    }

    public void clear() {
        ThreadPoolExecutor pool = (ThreadPoolExecutor) Executors.newFixedThreadPool(5);
        try {
            for (int I = 0; I < N_LOCKS; i++) {
                List<Node<K, V>> toRemove = new ArrayList<>();
                synchronized (locks[i]) {
                    Node<K, V> current = buckets[i];
                    while (current != null) {
                        Node<K, V> next = current.next;
                        buckets[i] = next;
                        toRemove.add(current);
                        current = next;
                    }
                }
                for (int j = 0; j < N_LOCKS && pool.getActiveCount() < 5; j++) {
                    int start = i * N_BUCKETS / N_LOCKS;
                    int end = (i + 1) * N_BUCKETS / N_LOCKS;
                    IntStream.rangeClosed(start, end).parallel().forEach(bucketIndex -> {
                        Node<K, V> current = buckets[bucketIndex];
                        while (current != null) {
                            Node<K, V> next = current.next;
                            if (!toRemove.remove(current)) {
                                continue;
                            }
                            buckets[bucketIndex] = next;
                            pool.submit(() -> {
                                try {
                                    Node<K, V> toEvict = current;
                                    synchronized (locks[i % N_LOCKS]) {
                                        int bucketIndex = hashIndex(current.key.hashCode());
                                        Node<K, V> newCurrent = buckets[bucketIndex];
                                        while (newCurrent != null && newCurrent != toEvict) {
                                            newCurrent = newCurrent.next;
                                        }
                                        if (newCurrent == toEvict) { // already removed by another thread
                                            return;
                                        }
                                        Node<K, V> next = current.next;
                                        buckets[bucketIndex] = next;
                                    }
                                } catch (Exception e) {
