                    current = current.next;
                }
            }
            return false;
        }).anyMatch(true::booleanValue);
    }

    public void remove(Object key) throws NoSuchElementException {
        int index = hashIndex(System.identityHashCode(key));
        synchronized (locks[index % N_LOCKS]) {
            Node<K, V> current = buckets[index];
            Node<K, V> prev = null;
            while (current != null && !current.key.equals(key)) {
                prev = current;
                current = current.next;
            }
            if (current == null) {
                throw new NoSuchElementException();
            }
            if (prev == null) { // at beginning of list
                buckets[index] = current.next;
            } else { // somewhere in middle or end of list
                prev.next = current.next;
            }
        }
    }

