import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

class Point {
    final int x, y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

class Calculator implements Callable<Integer> {
    private Point[] points;
    private int id;

    Calculator(Point[] points, int id) {
        this.points = points;
        this.id = id;
    }

    @Override
    public Integer call() throws Exception {
        int sum = 0;

        for (int I = 0; I < points.length - 1; i++) {
            int dx = points[i + 1].x - points[i].x;
            int dy = points[i + 1].y - points[i].y;

            sum += Math.abs(dx * dy);
        }

        System.out.println("Thread " + id + " has calculated the distance between " + points[0] + " and " + points[points.length - 1] + ": " + sum);
        return sum;
    }
}

public class Main {

    private static final int MAX_THREADS = 6;
    private static final ExecutorService pool = Executors.newFixedThreadPool(MAX_THREADS);
    private static final Random random = new Random();
    private static final AtomicInteger threadCounter = new AtomicInteger(0);

    public static void main(String[] args) {
        Point[] points = generatePoints();

        List<Future<Integer>> futures = new ArrayList<>();

        for (int I = 0; I < MAX_THREADS - 1; i++) {
            int id = threadCounter.incrementAndGet();
            futures.add(pool.submit(new Calculator(points, id)));
        }

        try {
            int sum = 0;
            for (Future<Integer> future : futures) {
                sum += future.get();
            }
            System.out.println("The distance between the points is: " + sum);
        } catch (ExecutionException | InterruptedException e) {
            e.printStackTrace();
        } finally {
            pool.shutdown();
        }
    }

    private static Point[] generatePoints() {
        Lock lock = new ReentrantLock();

        int x1 = 0, y1 = 0;
        int x2 = 0, y2 = 0;
        int maxX = Integer.MAX_VALUE / 100;
        int maxY = Integer.MAX_VALUE / 100;

        Runnable task = () -> {
            try {
                Thread.sleep(1);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }

            x1 = random.nextInt(maxX);
            y1 = random.nextInt(maxY);

            lock.lock();
            try {
                while (true) {
                    if (x2 == x1 || y2 == y1) {
                        continue;
                    }

                    x2 = random.nextInt(maxX);
                    y2 = random.nextInt(maxY);

                    return;
                }
            } finally {
                lock.unlock();
            }
        };

        ExecutorService pool = Executors.newFixedThreadPool(MAX_THREADS);
        for (int I = 0; I < MAX_THREADS - 1; i++) {
            pool.execute(task);
        }

        try {
            pool.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            pool.shutdown();
        }

        return new Point[]{new Point(x1, y1), new Point(x2, y2)};
    }
}

