import java.util.concurrent.*;

class Point {
    final int x, y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

class Task implements Callable<Point> {
    private final int midX, midY;

    Task(int minX, int maxX, int minY, int maxY) {
        int width = maxX - minX + 1;
        int height = maxY - minY + 1;
        int xRange = width >> 2; // divide by 16 to get ~2 iterations per thread
        int yRange = height >> 2;
        midX = minX + xRange;
        midY = minY + yRange;
    }

    @Override
    public Point call() throws Exception {
        int[] points = new int[xRange * yRange];
        int count = 0;
        for (int I = midX - xRange; I <= midX + xRange; i++) {
            for (int j = midY - yRange; j <= midY + yRange; j++) {
                if (Math.abs(i - midX) + Math.abs(j - midY) <= 2) { // within range of midpoint
                    points[count++] = i * 10_000 + j; // convert to unique identifier
                }
            }
        }
        int index = ThreadLocalRandom.current().nextInt(count);
        return new Point(points[index], points[index] / 10_000);
    }
}

