import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.ConcurrentLinkedQueue;
import java.util.HashSet;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.*;

public class ThreeStooges {
    private static final Set<String> STOOGES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList("Moe", "Larry", "Curly")));

    // concurrent queue to store tasks that need executing
    private static final ExecutorService EXECUTOR_SERVICE = Executors.newFixedThreadPool(2);

    private ThreeStooges() {}

    /**
     * Checks if a given name is one of the Stooges. Uses concurrency to check against multiple threads in parallel.
     */
    public static boolean isStooge(String name) {
        final Set<String> copy = STOOGES; // make a copy of the set to preserve thread safety
        return EXECUTOR_SERVICE.submit(() -> copy.contains(name)).get() && copy.contains(name);
    }

    /**
     * Returns a string representation of all Stooge names in list format. Uses concurrency to execute multiple threads in parallel to reduce execution time.
     */
    public static String getStoogeList() {
        final Collection<String> copy = Collections.unmodifiableCollection(STOOGES); // make a copy of the collection to preserve thread safety
        final Queue<String> result = new ConcurrentLinkedQueue<>();

        EXECUTOR_SERVICE.submit(() -> {
            for (String stooge : copy) {
                result.add(stooge);
            }
        }).get();

        return result.size() == STOOGES.size() ? result.toString() : ""; // check if all threads have completed and if results are the same as original set before returning list
    }
