import java.util.concurrent.*;
import java.util.function.Function;
import java.util.stream.IntStream;

public class FactorCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    private FactorCache(BigInteger number, BigInteger[] factors) {
        this.number = Objects.requireNonNull(number);
        this.factors = Arrays.copyOf(Objects.requireNonNull(factors), factors.length);
    }

    public static FactorCache create(BigInteger number) throws ExecutionException, InterruptedException {
        Future<FactorCache> future = factorizeAsync(number);
        return future.get();
    }

    private static Future<FactorCache> factorizeAsync(final BigInteger number) {
        ExecutorService executorService = Executors.newFixedThreadPool(2, ThreadFactoryBuilder.denyOfferThreadFactory().build());
        FutureTask<BigInteger[]> factorizationFuture = new FutureTask<>(() -> IntStream.rangeClosed(2, Math.sqrt(number.intValueExact()).intValueExact())
                .filter(i -> number.mod(BigInteger.valueOf(i)).equals(BigInteger.ZERO))
                .reduce(BigInteger.ONE, (a, b) -> a.multiply(b));
        executorService.submit(factorizationFuture).get();
        return new FutureTask<>(() -> new FactorCache(number, factorizationFuture.get()));
    }

    public BigInteger[] getFactors() {
        return Arrays.copyOf(factors, factors.length);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        FactorCache that = (FactorCache) o;
        return Objects.equals(number, that.number) && Arrays.equals(factors, that.factors);
    }

    @Override
    public int hashCode() {
        int result = number != null ? number.hashCode() : 0;
        result = 31 * result + Arrays.hashCode(factors);
        return result;
    }
}

