import java.math.BigInteger;
import java.util.Arrays;
import java.util.ConcurrentLinkedQueue;
import java.util.LinkedList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BiFunction;
import java.util.function.Consumer;
import java.util.function.IntSupplier;
import java.util.function.Supplier;

class Cache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public Cache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = Arrays.copyOf(factors, factors.length);
    }

    public BigInteger[] getFactors() {
        return Arrays.copyOf(factors, factors.length);
    }
}

class CacheFactory implements BiFunction<BigInteger, IntSupplier, Cache> {
    private final IntSupplier threadPoolSize;

    public CacheFactory(IntSupplier threadPoolSize) {
        this.threadPoolSize = threadPoolSize;
    }

    @Override
    public Cache apply(BigInteger number, int concurrencyLevel) {
        ExecutorService threadPool = Executors.newFixedThreadPool(threadPoolSize.getAsInt());
        try {
            Future<Cache>[] futures = new Future[concurrencyLevel];
            for (int I = 0; I < concurrencyLevel; i++) {
                int finalI = i;
                futures[i] = threadPool.submit(() -> computeFactors(number, i));
            }
            Cache result = null;
            AtomicInteger count = new AtomicInteger();
            for (int I = 0; I < concurrencyLevel; i++) {
                try {
                    Futures.get(futures[i], 1, TimeUnit.SECONDS);
                    if (result == null) {
                        result = new Cache(number, futures[i].get().factors);
                    } else if (!Arrays.equals(result.factors, futures[i].get().factors)) {
                        throw new RuntimeException("Duplicate factors for " + number);
                    }
                } catch (Exception e) {
                    System.err.println("Error computing factors for " + number + ": " + e.getMessage());
                } finally {
                    count.incrementAndGet();
                    if (count.get() == concurrencyLevel && result != null) {
                        threadPool.shutdownNow();
                        return result;
                    }
                }
            }
            throw new RuntimeException("Did not complete all computations for " + number);
        } finally {
            threadPool.shutdown();
        }
    }

    private static Cache computeFactors(BigInteger number, int workerId) {
        Supplier<LinkedList<BigInteger>> factorCache = () -> new LinkedList<>();
        Consumer<BigInteger> addFactor = factor -> factorCache.get().add(factor);
        for (int I = 2; I <= Math.sqrt(number.abs()).intValue(); i++) {
            if (number.mod(BigInteger.valueOf(i)).equals(BigInteger.ZERO)) {
                addFactor.accept(BigInteger.ONE);
                while (number.divide(BigInteger.valueOf(i)).remainder(BigInteger.ONE).equals(BigInteger.ZERO)) {
                    number = number.divide(BigInteger.valueOf(i));
                    addFactor.accept(number);
                }
            }
        }
        BigInteger[] factors = factorCache.get().toArray(new BigInteger[0]);
        Arrays.sort(factors);
        return new Cache(number, factors);
    }
}

public static void main(String[] args) {
    IntSupplier threadPoolSize = () -> Math.min(2, Runtime.getRuntime().availableProcessors());
    CacheFactory factory = new CacheFactory(threadPoolSize);
    BigInteger number1 = BigInteger.valueOf(1234567890L);
    BigInteger number2 = BigInteger.valueOf(9876543210L);
    System.out.println("Factors for " + number1 + ": " + factory.apply(number1, 2).getFactors());
    System.out.println("Factors for " + number2 + ": " + factory.apply(number2, 2).getFactors());
}

import java.math.BigInteger;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

public class FactorCache {
    private final BigInteger number;
    private final ArrayDeque<BigInteger[]> factorLists = new ArrayDeque<>();
    private final AtomicReference<Future<BigInteger[]>> fetchResult;
    private static final ExecutorService threadPool = Executors.newFixedThreadPool(2);

    public FactorCache(BigInteger number) {
        this.number = Objects.requireNonNull(number);
        fetchResult = new AtomicReference<>(null);
    }

    public BigInteger[] getFactors() {
        if (Objects.equals(number, fetchResult.get().get()) && !fetchResult.get().isCancelled() && !fetchResult.get().isDone()) {
            try {
                return fetchResult.get().get();
            } catch (InterruptedException | ExecutionException e) {
                // Ignore exception and return null
            } finally {
                threadPool.shutdownNow(); // Clear the fetch result in case of error
            }
        }

        BigInteger[] factors = null;
        if (factorLists.isEmpty()) {
            Runnable task = () -> {
                try {
                    factors = factorize(number);
                    factorLists.addLast(factors);
                    fetchResult.set(threadPool.submit(() -> Arrays.copyOf(factorLists.poll(), factorLists.size())));
                } finally {
                    threadPool.shutdownNow(); // Clear the fetch result in case of error
                }
            };
            threadPool.execute(task);
        } else {
            factors = Arrays.copyOf(factorLists.poll(), factorLists.size());
        }
        return Arrays.copyOf(factors, factors.length); // Return a copy to prevent modification of the internal state
    }

    private static BigInteger[] factorize(BigInteger number) {
        ArrayList<BigInteger> primes = new ArrayList<>();
        for (BigInteger p = BigInteger.TWO; p.square().compareTo(number) <= 0; p = p.nextProbablePrime()) {
            int exp = 0;
            while (number.divide(p).remainder(p).equals(BigInteger.ZERO)) {
                number = number.divide(p);
                exp++;
            }
            primes.add(p);
            primes.add(BigInteger.ONE); // Add a dummy element to separate factors with the same prime exponent
            for (int j = 0; j < exp; j++) {
                primes.add(p);
            }
        }
        return primes.toArray(new BigInteger[primes.size()]);
    }
}

public static void main(String[] args) {
    FactorCache cache = new FactorCache(BigInteger.valueOf(120));
    System.out.println(Arrays.toString(cache.getFactors())); // Output: [2, 2, 2, 5] (if not cached) or a different order if already cached
}

