            }
        }
    }

    /**
     * Adjusts the index of an element to its adjusted position within the parent list after a concurrent modification.
     */
    private E adjustIndex(E e) {
        int index = delegate.indexOf(e); // Get original index in parent list
        int adjustedIndex = index + offset; // Adjust index for current sublist
        if (adjustedIndex < 0 || adjustedIndex >= size) { // Index outside of sublist bounds, return null
            return null;
        }
        delegate.set(index, e); // Set original element in parent list with new adjusted index
        return list.get(adjustedIndex); // Return adjusted element from current sublist
    }

    /**
     * Thread-safe putIfAbsent operation for concurrent modification of both lists.
     */
    public boolean putIfAbsent(E e) {
        synchronized (lock) {
            int index = binarySearch(list, e); // Search parent list for element
            if (index >= 0) { // Element already exists in parent list, return false
                return false;
            }
            boolean added = delegate.add(e); // Add element to parent list
            size++; // Increment sublist size for new element
            int adjustedIndex = ~index; // Get adjusted index for new element
            if (adjustedIndex < 0 || adjustedIndex >= size) { // Index outside of sublist bounds, return false
                delegate.remove(added); // Remove newly added element from parent list
                --size; // Decrement sublist size for removed element
                return false;
            }
            list.set(adjustedIndex, e); // Set original element in parent list with adjusted index
            return true; // Element was successfully inserted into both lists
        }
    }
}

