import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.Random;
import java.util.stream.Collectors;

interface DollarAmount {
    int getAmount();
}

class Account implements Comparable<Account> {
    private final int id;
    private int balance = 0;
    private boolean isLocked = false;
    private final Object primaryLock = new Object();
    private final Object secondaryLock = new Object();

    Account(int id) {
        this.id = id;
    }

    int getId() {
        return id;
    }

    int getBalance() {
        return balance;
    }

    void lockPrimary() {
        synchronized (primaryLock) {
            isLocked = true;
        }
    }

    void unlockPrimary() {
        synchronized (primaryLock) {
            isLocked = false;
            primaryLock.notifyAll();
        }
    }

    void lockSecondary(Account other) {
        synchronized (secondaryLock) {
            if (this == other || getId() < other.getId()) {
                return;
            }
            isLocked = true;
            secondaryLock.notifyAll();
        }
    }

    void unlockSecondary(Account other) {
        synchronized (secondaryLock) {
            if (this == other || getId() < other.getId()) {
                return;
            }
            isLocked = false;
            secondaryLock.notifyAll();
        }
    }

    void transfer(Account to, int amount, Supplier<DollarAmount> source) {
        DollarAmount sourceAmount = source.get();
        if (sourceAmount.getAmount() < amount) {
            throw new InsufficientFundsException("Transfer failed: insufficient funds");
        }
        balance -= amount;
        to.deposit(amount, () -> source);
    }

    void deposit(int amount, Supplier<DollarAmount> source) {
        DollarAmount sourceAmount = source.get();
        balance += amount + sourceAmount.getAmount();
    }

    @Override
    public int compareTo(Account o) {
        if (id == o.id) {
            return secondaryLock.hashCode() < o.secondaryLock.hashCode() ? -1 : 1;
        }
        return id < o.id ? -1 : 1;
    }
}

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

class TransferRunner implements Callable<Void> {
    private final Account from, to;
    private final int amount;
    private final Supplier<DollarAmount> source;

    public TransferRunner(Account from, Account to, int amount, Supplier<DollarAmount> source) {
        this.from = from;
        this.to = to;
        this.amount = amount;
        this.source = source;
    }

    @Override
    public Void call() throws Exception {
        try (ThreadLocalRandom random = ThreadLocalRandom.current()) {
            int delayMs = random.nextInt(3);
            Thread.sleep(delayMs);
            from.lockPrimary();
            to.lockSecondary(from);
            from.transfer(to, amount, source);
            to.unlockSecondary(from);
            from.unlockPrimary();
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
        return null;
    }
}

public class Main {
    public static void main(String[] args) {
        ExecutorService pool = Executors.newFixedThreadPool(3);
        Account alice = new Account(1), bob = new Account(2);
        Supplier<DollarAmount> source = () -> new DollarAmount() {
            @Override
            public int getAmount() {
                return 10;
            }
        };
        List<TransferRunner> tasks = IntStream.rangeClosed(1, 2)
                .mapToObj(i -> new TransferRunner(alice, bob, i * 5, source))
                .collect(Collectors.toList());
        try {
            pool.invokeAll(tasks);
            pool.shutdown();
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}

