class InsufficientFundsException extends Exception {}

class TransferHelper implements Runnable {
    private final Account sourceAccount, targetAccount;
    private final DollarAmount amount;

    TransferHelper(Account sourceAccount, Account targetAccount, DollarAmount amount) {
        this.sourceAccount = sourceAccount;
        this.targetAccount = targetAccount;
        this.amount = amount;
    }

    @Override
    public void run() {
        int sourceBalance = sourceAccount.getBalance();
        if (sourceBalance < amount.getAmount()) {
