        int updatedSourceBalance = sourceBalance - amount.getAmount();
        sourceAccount.setBalance(updatedSourceBalance);
        int targetBalance = targetAccount.getBalance() + amount.getAmount();
        targetAccount.setBalance(targetBalance);
    }
