import java.util.*;
import java.util.concurrent.*;

interface DollarAmount {
    int getDollars();
}

class Account implements Runnable {
    private final int id;
    private int balance = 0;
    private Lock lock = new ReentrantLock(id.hashCode());

    public Account(int id) {
        this.id = id;
    }

    void deposit(DollarAmount amount) {
        try {
            lock.lock();
            balance += amount.getDollars();
        } finally {
            lock.unlock();
        }
    }

    boolean withdraw(int dollars, Account recipient) throws InsufficientFundsException {
        DollarAmount diff = new Money(dollars);
        try {
            lock.lock();
            if (balance >= dollars) {
                balance -= dollars;
                recipient.deposit(diff);
                return true;
            } else {
                throw new InsufficientFundsException("Insufficient funds.");
            }
        } finally {
            lock.unlock();
        }
    }

    int getBalance() {
        try {
            lock.lock();
            return balance;
        } finally {
            lock.unlock();
        }
    }

    void transfer(Account recipient, int dollars) throws InsufficientFundsException, InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<?> aFuture = pool.submit(() -> withdraw(dollars, recipient));
        Future<?> bFuture = pool.submit(() -> recipient.deposit(new Money(dollars)));
        try {
            boolean success = aFuture.get();
            bFuture.get();
            if (!success) {
                throw new InsufficientFundsException("Transfer failed due to insufficient funds.");
            }
        } finally {
            pool.shutdown();
            while (!pool.isTerminated()) {
                Thread.sleep(1);
            }
        }
    }

    @Override
    public void run() {
        System.out.println("Thread: " + Thread.currentThread().getId() + ", Account: " + id + ", Balance: " + getBalance());
    }

    static class Money implements DollarAmount {
        private int dollars;

        Money(int dollars) {
            this.dollars = dollars;
        }

        @Override
        public int getDollars() {
            return dollars;
        }
    }

    static class InsufficientFundsException extends Exception {
        InsufficientFundsException(String message) {
            super(message);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Account a = new Account(1);
        Account b = new Account(2);
        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<?> aFuture = pool.submit(() -> a.transfer(b, 2));
        Future<?> bFuture = pool.submit(() -> {
            try {
                Thread.sleep(10);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            return b.transfer(a, 5);
        });
        try {
            boolean success = aFuture.get();
            bFuture.get();
            if (!success) {
                throw new InsufficientFundsException("Transfer failed due to insufficient funds.");
            }
            System.out.println("Account " + a.getId() + ": " + a.getBalance());
            System.out.println("Account " + b.getId() + ": " + b.getBalance());
        } finally {
            pool.shutdown();
            while (!pool.isTerminated()) {
                Thread.sleep(1);
            }
        }
    }
}

