public final class MonitorVehicleTracker {
    private static final int MAX_THREADS = 3;
    private final Map<String, MutablePoint> vehicleLocations;
    private final ExecutorService executorService = Executors.newFixedThreadPool(MAX_THREADS);
    private final UnaryOperator<Map<String, MutablePoint>> deepCopy = this::deepCopy;

    /**
     * Creates a new instance of the MonitorVehicleTracker class with the given initial synchronized map.
     */
    public MonitorVehicleTracker(Map<String, MutablePoint> vehicleLocations) {
        Objects.requireNonNull(vehicleLocations);
        this.vehicleLocations = Collections.unmodifiableMap(deepCopy.apply(Collections.synchronizedMap(vehicleLocations)));
    }

    /**
     * Returns an unmodifiable deep copy of the entire map.
     */
    public Map<String, MutablePoint> getLocations() {
        return vehicleLocations;
    }

    /**
     * Returns a new deep copy of the location for the given ID or null if not found.
     */
    public MutablePoint getLocation(String id) {
        return deepCopy.andThen(Collections::synchronizedMap).andThen(map -> map.getOrDefault(id, new MutablePoint())).apply(vehicleLocations);
    }

    /**
     * Updates the coordinates for the specified vehicle ID and throws an exception if not present.
     */
    public void setLocation(String id, int x, int y) {
        BiFunction<Map<String, MutablePoint>, String, MutablePoint> updateLocation = (map, id) -> new MutablePoint(x, y);
        Supplier<ConcurrentMap<String, MutablePoint>> createCopySupplier = this::deepCopy;
        Consumer<Map<String, MutablePoint>> updateAndSetConsumer = map -> {
            MutablePoint currentLocation = map.get(id);
            if (currentLocation != null) {
                MutablePoint updatedLocation = updateLocation.apply(map, id);
                map.put(id, updatedLocation);
            } else {
                map.put(id, new MutablePoint(x, y));
            }
        };
        Runnable updaterRunnable = () -> {
            ConcurrentMap<String, MutablePoint> copy = createCopySupplier.get();
            updateAndSetConsumer.accept(copy);
            vehicleLocations.putAll(copy);
        };
        executorService.submit(updaterRunnable).get();
    }

    /**
     * Creates a new deep copy of the given map, recursively invoking itself to copy nested maps.
     */
    private Map<String, MutablePoint> deepCopy(Map<? extends Object, ? extends Object> original) {
        LinkedHashMap<String, MutablePoint> result = new LinkedHashMap<>();
        for (Map.Entry<? extends String, ? extends Map<? extends Object, ? extends Object>> entry : original.entrySet()) {
            result.put(entry.getKey(), deepCopyMap((Map<? extends Object, ? extends Object>) entry.getValue()));
        }
        return Collections.unmodifiableMap(result);
    }

    /**
     * Creates a new deep copy of the given map, recursively invoking itself to copy nested maps.
     */
    private Map<String, MutablePoint> deepCopyMap(Map<? extends Object, ? extends Object> original) {
        LinkedHashMap<String, MutablePoint> result = new LinkedHashMap<>();
        for (Map.Entry<? extends String, ? extends Map<? extends Object, ? extends Object>> entry : original.entrySet()) {
            result.put(entry.getKey(), deepCopyPoint((MutablePoint) entry.getValue()));
        }
        return Collections.unmodifiableMap(result);
    }

    /**
     * Creates a new deep copy of the given mutable point.
     */
    private MutablePoint deepCopyPoint(MutablePoint original) {
        return new MutablePoint(original.getX(), original.getY());
    }
}

