import java.util.*;

class Node {
    int item;
    Node next;

    Node(int item) {
        this.item = item;
    }
}

class MyStack {
    private AtomicReference<Node> topRef;
    private int capacity;

    public MyStack(int capacity) {
        topRef = new AtomicReference<>(null);
        this.capacity = capacity;
    }

    public boolean isEmpty() {
        return topRef.get() == null;
    }

    public boolean isFull() {
        Node last = topRef.get();
        while (last != null) {
            if (last.next == null) {
                return false;
            }
            last = last.next;
        }
        return last == null || last.next != null;
    }

    public int push(int item) {
        Node newNode = new Node(item);
        Node last, newLast;
        do {
            last = topRef.get();
            newLast = new Node(item, last);
        } while (!topRef.compareAndSet(last, newLast));
        return item;
    }

    public int pop() {
        Node last, temp;
        int item;
        do {
            last = topRef.get();
            temp = last;
            if (last != null) {
                do {
                    temp = temp.next;
                } while (!topRef.compareAndSet(last, temp));
                item = last.item;
            } else {
                throw new NoSuchElementException();
            }
        } while (temp != null);
        return item;
    }
}

