class Stack {
    private static class Nodes extends LinkedBlockingQueue<Node> {}
    private final int maxSize;
    private final Nodes nodes = new Nodes();
    private final AtomicReference<Node> top = new AtomicReference<>(null);
    private final ExecutorService threadPool = Executors.newFixedThreadPool(2);

    Stack(int maxSize) {
        this.maxSize = maxSize;
    }

    void push(int item) throws InterruptedException, TimeoutException {
        Node newNode = new Node(item);
        while (true) {
            Node currentTop = top.get();
            Node nextTop = new Node(item, currentTop);
            if (nodes.offer(nextTop)) {
                boolean success = top.compareAndSet(currentTop, nextTop);
                if (success && nodes.size() == maxSize) {
                    nodes.drainTo(new LinkedBlockingQueue<>(), 1, TimeUnit.SECONDS);
                }
                return;
            } else {
                Thread.sleep(10); // prevent busy waiting
            }
        }
    }

    int pop() throws InterruptedException, TimeoutException {
        Node currentTop = top.get();
        Node nextTop;
        while (true) {
            if ((nextTop = currentTop.next.get()) != null && nodes.remove(currentTop)) {
                boolean success = top.compareAndSet(currentTop, nextTop);
                return currentTop.item;
            } else {
                Thread.sleep(10); // prevent busy waiting
            }
        }
    }

    int peek() throws InterruptedException, TimeoutException {
        Node topNode = top.get();
        while (topNode == null && !nodes.isEmpty()) {
            Thread.sleep(10); // prevent busy waiting
            topNode = top.get();
        }
        return topNode != null ? topNode.item : -1;
    }

    boolean isEmpty() {
        return nodes.isEmpty() && top.get() == null;
    }

    boolean isFull() {
        return nodes.size() == maxSize;
    }

    void clear() {
        while (true) {
            Node currentTop = top.get();
            List<Node> toRemove = new ArrayList<>(nodes.drainTo(new LinkedBlockingQueue<>(), maxSize, TimeUnit.SECONDS));
            boolean success = top.compareAndSet(currentTop, null);
            nodes.clear();
            if (success && !toRemove.isEmpty()) {
                toRemove.forEach(node -> threadPool.execute(() -> nodes.add(node)));
            }
            return;
