    private static final List<Thread> THREADS = new ArrayList<>();
    private static final BlockingQueue<Runnable> QUEUE = new LinkedBlockingQueue<>(DEFAULT_SIZE);
    private static final ExecutorService SERVICE = Executors.newFixedThreadPool(POOL_SIZE.get());
