            try {
                QUEUE.put(Stack::popTask);
                QUEUE.put(Stack::pushTask);
                QUEUE.put(Stack::popTask);
                QUEUE.put(Stack::pushTask);
                QUEUE.put(Stack::popTask);
                QUEUE.put(Stack::pushTask);
                QUEUE.take();
            } catch (InterruptedException | ExecutionException e) {
                // Ignore and continue with cleanup
            }

            THREADS.add(Thread.currentThread());
            SERVICE.execute(() -> {
                try {
                    while (!THREADS.remove(Thread.currentThread())) {}
                    QUEUE.drainTo(null);
                } catch (Exception e) {
