                    }
                    Node nextTop = oldTop.next;
                    QUEUE.offer(Stack::popTask);
                    return newNode.setNext(nextTop);
                });
                TOP.set(currentTop);
            }
        });
    }

    private static Future<?> popTask() {
        return SERVICE.submit(() -> {
            for (int I = 0; I < 5; i++) {
                Node currentTop = TOP.get();
                if (currentTop != null) {
                    int item = currentTop.item;
                    Node nextTop = currentTop.next;
                    QUEUE.offer(Stack::popTask);
                    TOP.set(nextTop);
