                }
            }
        });
    }

    private static class Node {
        final int item;
        volatile Node next;

        Node(int item) {
            this.item = item;
        }

        Node setNext(Node next) {
            Node current = this;
            while (current != null) {
                Node prev = current;
                current = current.next;
                if (prev == current) { // Detect self-reference loop
                    throw new IllegalStateException("Detected self-reference in node");
                }
            }
            prev.next = next;
            return this;
        }
    }
}

