import java.util.function.Consumer;

import static java.lang.Thread.currentThread;
import static java.util.Collections.newConcurrentLinkedQueue;
import static java.util.Objects.requireNonNull;

public class Secrets {
    private static final Set<Secret> knownSecrets = initialize();

    // A queue of secrets that are being discovered
    private static final ConcurrentLinkedQueue<Secret> discoveries = newConcurrentLinkedQueue<>();

    // A thread pool for discovering secrets concurrently
    private static final ExecutorService discoveryPool = Executors.newFixedThreadPool(2, r -> {
        Thread t = Executors.defaultThreadFactory().newThread(r);
        t.setDaemon(true);
        return t;
    });

    // A thread pool for printing discovered secrets concurrently
    private static final ExecutorService printPool = Executors.newFixedThreadPool(1, r -> {
        Thread t = Executors.defaultThreadFactory().newThread(r);
        t.setDaemon(true);
        return t;
    });

    // Add a secret to both the known secrets set and the discoveries queue
    public static void addSecret(Secret secret) {
        requireNonNull(secret, "secret");
        knownSecrets.add(secret);
        discoveries.offer(secret);
    }

    // Called by the main thread to start discovering secrets concurrently
    public static void discover() {
        Consumer<List<Secret>> printResult = result -> {
            System.out.println("Found " + result.size() + " secrets:");
            result.forEach(System.out::println);
        };

        // Start a new discovery task in the thread pool and wait for its result
        Future<List<Secret>> future = discoveryPool.submit(() -> {
            List<Secret> foundSecrets = new ArrayList<>();
            while (!discoveries.isEmpty()) {
                Secret secret = discoveries.poll();
                if (isDiscovered(secret)) {
                    foundSecrets.add(secret);
                } else {
                    // Add secret back to the queue for further processing
                    discoveries.offer(secret);
                }
            }
            return foundSecrets;
        });

        // Wait for the discovery task to complete and print its result
        try {
            List<Secret> results = future.get();
            printPool.submit(() -> printResult.accept(results));
        } catch (InterruptedException | ExecutionException e) {
            System.err.println("Error discovering secrets: " + e);
        } finally {
            // Shut down the thread pools and terminate the JVM if all tasks are done
            discoveryPool.shutdownNow();
            printPool.shutdownNow();
            if (currentThread() == Thread.currentThread()) {
                System.exit(0);
            }
        }
    }

    // Check whether a secret has already been discovered or not
    private static boolean isDiscovered(Secret secret) {
        return knownSecrets.contains(secret);
    }

    // Initialize the set of known secrets with a few examples
    private static Set<Secret> initialize() {
        List<Secret> secrets = newArrayList<>();
        secrets.add(new Secret("1st secret", 1));
        secrets.add(new Secret("2nd secret", 2));
        secrets.add(new Secret("3rd secret", 3));
        return Collections.unmodifiableSet(new LinkedHashSet<>(secrets));
    }

    // A simple data class representing a secret
    static class Secret {
        private final String name;
        private final int id;

        public Secret(String name, int id) {
            this.name = requireNonNull(name, "name");
            this.id = id;
        }

        @Override
        public String toString() {
            return "Secret{" +
                    "name='" + name + "'" +
                    ", id=" + id +
                    '}';
        }
    }

    // A static inner class representing a factory for creating ThreadPoolExecutor instances
    private static final class ThreadFactory implements ExecutorService {
        private final ThreadFactory delegate;

        public ThreadFactory(ThreadFactory delegate) {
            this.delegate = requireNonNull(delegate, "delegate");
        }

        @Override
        public void execute(Runnable command) {
            delegate.execute(command);
        }

        @Override
        public <T> Future<T> submit(Callable<T> task) {
            return delegate.submit(task);
        }

        @Override
        public <T> Future<T> submit(Runnable task, T result) {
            return delegate.submit(task, result);
        }

        @Override
        public void shutdown() {
            delegate.shutdown();
        }

        @Override
        public List<Runnable> shutdownNow() {
            return delegate.shutdownNow();
        }

        @Override
        public boolean isShutdown() {
            return delegate.isShutdown();
        }

        @Override
        public boolean isTerminated() {
            return delegate.isTerminated();
        }

        @Override
        public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
            return delegate.awaitTermination(timeout, unit);
        }
    }
}

