    public void addUser(String userId, String name, String location) {
        int dotIndex = userId.indexOf('.');
        String usersKey = "users." + userId.substring(0, dotIndex);
        String userKey = usersKey + ".user";
        String locationKey = userKey + ".location";
        userAttributes.putIfAbsent(usersKey, "");
        userAttributes.putIfAbsent(userKey, "");
        userAttributes.put(locationKey, location);
    }

    public void removeUser(String userId) {
        int dotIndex = userId.indexOf('.');
        String usersKey = "users." + userId.substring(0, dotIndex);
        String userKey = usersKey + ".user";
        String[] keysToRemove = {usersKey, userKey};
        for (String key : keysToRemove) {
            userAttributes.remove(key);
            List<String> keyPaths = userAttributes.keySet().stream()
                    .filter(keyPath -> keyPath.startsWith(key))
                    .collect(Collectors.toList());
            for (String path : keyPaths) {
                int lastDotIndex = path.lastIndexOf('.');
                String parentKey = path.substring(0, lastDotIndex);
                userAttributes.remove(parentKey);
            }
        }
    }

    public boolean userLocationMatches(String userId, String regexp) {
        int dotIndex = userId.indexOf('.');
        String usersKey = "users." + userId.substring(0, dotIndex);
        String locationKey = usersKey + ".location";
        return getLocation(userId).filter(Objects::nonNull).map(String::trim)
                .filter(s -> Pattern.matches(regexp, s)).isPresent();
    }

    private String getLocation(String userId) {
        int dotIndex = userId.indexOf('.');
        String usersKey = "users." + userId.substring(0, dotIndex);
        String userKey = usersKey + ".user";
        String locationKey = userKey + ".location";
        return userAttributes.computeIfAbsent(locationKey, k -> {
            List<String> keyPaths = userAttributes.keySet().stream()
                    .filter(keyPath -> keyPath.startsWith(usersKey) && keyPath.contains("." + locationKey))
                    .map(path -> path.substring(path.lastIndexOf('.') + 1))
                    .collect(Collectors.toList());
            if (keyPaths.isEmpty()) {
                return null;
            } else {
                Collections.shuffle(keyPaths);
                return keyPaths.get(Math.min(2, keyPaths.size()));
            }
        });
    }

