import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public class DelegatingVehicleTracker {
    private final Map<String, Point> locations;
    private final ExecutorService executor = Executors.newFixedThreadPool(3);

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        this.locations = new ConcurrentHashMap<>(initialLocations);
    }

    /**
     * Get the location of a vehicle. This method returns a function that will compute the current location when invoked. 
     */
    public Function<String, Point> getLocation() {
        return locations::get;
    }

    /**
     * Set the new location of a vehicle. This method returns a future for an asynchronous operation that updates the location and returns nothing. 
     */
    public Future<?> setLocation(String id, Point newLocation) {
        return executor.submit(() -> locations.putIfAbsent(id, newLocation));
    }

    /**
     * Return an unmodifiable view of all current vehicle locations. This method returns a snapshot map, so it's safe to use from concurrent threads. 
     */
    public Map<String, Point> getAllLocations() {
        return Collections.unmodifiableMap(locations);
    }

    /**
     * Return an unmodifiable view of all current vehicle locations. This method returns a live map backed by the original data, so it's not safe to use concurrently. 
     */
    public Map<String, Point> getAllLocationsLive() {
        return locations;
    }
}
public static void main(String[] args) {
    Map<String, Point> initialLocations = new HashMap<>();
    initialLocations.put("A", new Point(1, 1));
    initialLocations.put("B", new Point(2, 2));
    DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

    Function<String, Point> getA = tracker.getLocation();
    Function<String, Point> getB = tracker.getLocation();

    System.out.println("Initial locations:");
    System.out.printf("%s: %s%n", "A", getA.apply("A"));
    System.out.printf("%s: %s%n", "B", getB.apply("B"));

    Future<?> setB = tracker.setLocation("B", new Point(3, 3));
    System.out.println("Waiting for location update...");
    try {
        setB.get();
    } catch (InterruptedException | ExecutionException e) {
        // Ignore exceptions and continue
    }

    System.out.printf("%s: %s%n", "A", getA.apply("A"));
    System.out.printf("%s: %s%n", "B", getB.apply("B"));

    Map<String, Point> allLocations = tracker.getAllLocations();
    System.out.println("Current locations (snapshot):");
    for (Map.Entry<String, Point> entry : allLocations.entrySet()) {
        String id = entry.getKey();
        Point location = entry.getValue();
        System.out.printf("%s: %s%n", id, location);
    }

    Map<String, Point> liveLocations = tracker.getAllLocationsLive();
    System.out.println("Current locations (live):");
    for (Map.Entry<String, Point> entry : liveLocations.entrySet()) {
        String id = entry.getKey();
        Point location = entry.getValue();
        System.out.printf("%s: %s%n", id, location);
    }

    // Do some work that may take a long time...
    for (int I = 0; I < 1_000_000; i++) {
        int x = ThreadLocalRandom.current().nextInt(1, 5);
        int y = ThreadLocalRandom.current().nextInt(1, 5);
        Point randomLocation = new Point(x, y);
        setB.cancel(true); // Cancel previous location update request
        setLocation("C", randomLocation).get(); // Start a new one
    }

    System.out.printf("%s: %s%n", "B", getB.apply("B"));
    System.out.println("Final locations (snapshot):");
    for (Map.Entry<String, Point> entry : allLocations.entrySet()) {
        String id = entry.getKey();
        Point location = entry.getValue();
        System.out.printf("%s: %s%n", id, location);
    }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.stream.*;

class DelegatingVehicleTracker implements VehicleTracker {
    private final Map<Long, Point> vehicles = new ConcurrentHashMap<>();

    @SafeVarargs
    public DelegatingVehicleTracker(long... initialLocations) {
        Arrays.stream(initialLocations).forEach(id -> vehicles.put(id, new Point()));
    }

    @Override
    public Point getLocation(Long id) {
        return vehicles.get(id);
    }

    @Override
    public void setLocation(Long id, Point location) {
        Point prev = vehicles.putIfAbsent(id, location);
        if (prev != null) {
            // We tried to replace a non-existing vehicle with the new one, but some other thread updated it in the meantime
            throw new ConcurrentModificationException("Vehicle " + id + " was moved by another thread");
        }
    }

    @Override
    public Collection<Point> getAllLocations() {
        return new ArrayList<>(vehicles.values());
    }

    @Override
    public Collection<Point> snapshot() {
        return new CopyOnWriteArrayList<>(new ArrayList<>(vehicles.values()));
    }
}

