import java.util.Objects;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Consumer;
import java.util.stream.Collectors;

public class DelegatingVehicleTracker {
    private final Map<String, Point> locations = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(3);

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        locations.putAll(initialLocations);
    }

    /**
     * Returns the current location of the specified vehicle. If the vehicle is not found in the map, returns null.
     */
    public Point getLocation(String id) {
        return locations.get(Objects.requireNonNull(id));
    }

    /**
     * Sets the new location of the specified vehicle. Returns true if the vehicle was already present in the map and the update succeeded; false otherwise (if the vehicle ID is not found or the update failed).
     */
    public boolean setLocation(String id, Point location) {
        return locations.computeIfPresent(id, (k, oldValue) -> location) == location;
    }

    /**
     * Returns an unmodifiable view of all current vehicle locations. The returned map is backed by the original one and can be safely modified elsewhere while this method returns a snapshot.
     */
    public Map<String, Point> getLocations() {
        return Collections.unmodifiableMap(locations);
    }

    /**
     * Returns an unmodifiable snapshot of all current vehicle locations at the time of the call. The returned map is a live view until it's replaced by another one in subsequent calls, but can't be modified through this instance.
     */
    public Map<String, Point> getSnapshot() {
        return new Snapshot<>(locations);
    }

    /**
     * Updates the location of all vehicles concurrently using a provided function that takes an iterator over all current vehicle locations. The resulting map is returned as an unmodifiable view.
     */
    public Map<String, Point> updateLocations(Consumer<Iterator<Map.Entry<String, Point>>> updater) {
        executor.submit(() -> {
            Iterator<Map.Entry<String, Point>> iterator = locations.entrySet().iterator();
            updater.accept(iterator);
            iterator.close(); // Close the iterator to prevent memory leaks in case the provided consumer does not close it.
        }).join(); // Wait for the submitted task to complete before returning.
        return Collections.unmodifiableMap(locations);
    }

    /**
     * Simple wrapper around a map that returns a snapshot as an unmodifiable view, but updates the delegate automatically whenever requested.
     */
    private static final class Snapshot<K, V> implements Map<K, V>, Cloneable {
        private final Map<K, V> delegate;

        Snapshot(Map<K, V> delegate) {
            this.delegate = Objects.requireNonNull(delegate);
        }

        @Override
        public int size() {
            return delegate.size();
        }

        @Override
        public boolean isEmpty() {
            return delegate.isEmpty();
        }

        @Override
        public boolean containsKey(Object key) {
            return delegate.containsKey(key);
        }

        @Override
        public boolean containsValue(Object value) {
            return delegate.containsValue(value);
        }

        @Override
        public V get(Object key) {
            return delegate.get(key);
        }

        @Override
        public V put(K key, V value) {
            throw new UnsupportedOperationException("This method is not supported in snapshots.");
        }

        @Override
        public V remove(Object key) {
            throw new UnsupportedOperationException("This method is not supported in snapshots.");
        }

        @Override
        public void putAll(Map<? extends K, ? extends V> m) {
            delegate.putAll(m);
        }

        @Override
        public void clear() {
            throw new UnsupportedOperationException("This method is not supported in snapshots.");
        }

        @Override
        public Set<K> keySet() {
            return Collections.unmodifiableSet(delegate.keySet());
        }

        @Override
        public Collection<V> values() {
            return Collections.unmodifiableCollection(delegate.values());
        }

        @Override
        public Set<Entry<K, V>> entrySet() {
            return Collections.unmodifiableSet(new AbstractSet<Entry<K, V>>() {
                @Override
                public Iterator<Entry<K, V>> iterator() {
                    return delegate.entrySet().iterator();
                }

                @Override
                public int size() {
                    return delegate.size();
                }
            });
        }

        @Override
        protected Object clone() throws CloneNotSupportedException {
            return new Snapshot<>(Objects.requireNonNull(delegate.clone()));
        }
    }
}

