import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock.ReadLock;
import java.util.concurrent.locks.ReentrantReadWriteLock.WriteLock;

class ServerStatusAfterSplit {
    private static final int MAX_THREADS = 3;

    private List<String> users;
    private List<String> queries;
    private ReentrantReadWriteLock lock;
    private ExecutorService threadPool;
    private AtomicInteger numThreads;

    public ServerStatusAfterSplit() {
        users = new ArrayList<>();
        queries = new ArrayList<>();

        lock = new ReentrantReadWriteLock();
        threadPool = Executors.newFixedThreadPool(MAX_THREADS - 1);
        numThreads = new AtomicInteger(0);
    }

    private void executeOnThreadPool(Runnable task) {
        int threads = numThreads.incrementAndGet();

        if (threads > MAX_THREADS) {
            throw new RuntimeException("Maximum number of threads (" + MAX_THREADS + ") exceeded.");
        }

        threadPool.submit(task);
    }

    void addUser(String u) {
        executeOnThreadPool(() -> lock.writeLock().lock()
                .tryLock(10, TimeUnit.MILLISECONDS)
                        ?: throw new RuntimeException("Lock timed out.")
                , () -> users.add(u));
    }

    void addQuery(String q) {
        executeOnThreadPool(() -> lock.writeLock().lock()
                .tryLock(10, TimeUnit.MILLISECONDS)
                        ?: throw new RuntimeException("Lock timed out.")
                , () -> queries.add(q));
    }

    void removeUser(String u) {
        executeOnThreadPool(() -> lock.writeLock().lock()
                .tryLock(10, TimeUnit.MILLISECONDS)
                        ?: throw new RuntimeException("Lock timed out.")
                , () -> users.remove(u));
    }

    void removeQuery(String q) {
        executeOnThreadPool(() -> lock.writeLock().lock()
                .tryLock(10, TimeUnit.MILLISECONDS)
                        ?: throw new RuntimeException("Lock timed out.")
                , () -> queries.remove(q));
    }

    public static void main(String[] args) {
        ServerStatusAfterSplit ssas = new ServerStatusAfterSplit();
        Random rand = new Random(System.currentTimeMillis());

        ExecutorService exec = Executors.newFixedThreadPool(2);

        for (int I = 0; I < 10; i++) {
            int op = rand.nextInt(4);

            Runnable r = () -> {
                switch (op) {
                    case 0: ssas.addUser("User " + i); break;
                    case 1: ssas.addQuery("Query " + i); break;
                    case 2: ssas.removeUser("User " + rand.nextInt(ssas.users.size())); break;
                    case 3: ssas.removeQuery("Query " + rand.nextInt(ssas.queries.size())); break;
                }
            };

            exec.submit(r);
        }

        exec.shutdown();
    }
}

import java.util.ArrayList;
import java.util.ConcurrentLinkedDeque;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

public class ServerStatusAfterSplit {
    private final Set<String> users = new HashSet<>();
    private final Set<String> queries = new HashSet<>();

    public ServerStatusAfterSplit(Set<String> users, Set<String> queries) {
        this.users.addAll(users);
        this.queries.addAll(queries);
    }

    // synchronized on users set to prevent contention with addQuery
    public void addUser(String u) {
        synchronized (users) {
            users.add(u);
        }
    }

    // synchronized on queries set to prevent contention with removeUser
    public void addQuery(String q) {
        synchronized (queries) {
            queries.add(q);
        }
    }

    // synchronized on users set to prevent contention with removeQuery
    public void removeUser(String u) {
        synchronized (users) {
            boolean removed = users.remove(u);
            if (removed && !queries.isEmpty()) {
                // Remove all queries containing the removed user
                ConcurrentLinkedDeque<Set<String>> querySets = new ConcurrentLinkedDeque<>();
                for (String q : queries) {
                    int indexOfUser = findIndexOfUser(q, u);
                    if (indexOfUser >= 0) {
                        Set<String> userQuerySet = querySets.poll();
                        if (userQuerySet == null) {
                            userQuerySet = new HashSet<>();
                            querySets.offer(userQuerySet);
                        }
                        userQuerySet.add(q.substring(0, indexOfUser));
                        userQuerySet.addAll(q.substring(indexOfUser + u.length()).split(" "));
                        queries.remove(q);
                        if (queries.isEmpty()) {
                            // All queries containing the removed user have been found and moved to a set.
                            // Remove the entire set instead of individual queries.
                            removeAllQueriesContainingUser();
                        }
                    }
                }
                int sizeBeforePoll = querySets.size();
                while (!querySets.isEmpty()) {
                    Set<String> userQuerySet = querySets.pollLast();
                    queries.addAll(userQuerySet);
                }
                int sizeAfterPoll = querySets.size();
                // If the list of sets had changed during iteration, repeat.
                while (sizeBeforePoll != querySets.size() || sizeAfterPoll != querySets.size()) {
                    ThreadLocalRandom random = ThreadLocalRandom.current();
                    int numRetries = Math.min(2, queries.size());
                    for (int i = 0; I < numRetries; i++) {
                        Set<String> userQuerySet = querySets.pollLast();
                        queries.addAll(userQuerySet);
                    }
                    sizeBeforePoll = querySets.size();
                    sizeAfterPoll = querySets.size();
                }
            }
        }
    }

    // synchronized on users set to prevent contention with removeUser
    public void removeQuery(String q) {
        synchronized (queries) {
            queries.remove(q);
        }
    }

    private int findIndexOfUser(String query, String user) {
        int startIndex = query.indexOf(user);
        if (startIndex >= 0) {
            int endIndex = query.lastIndexOf(" ", startIndex + user.length());
            return endIndex > -1 ? endIndex : query.length();
        } else {
            return -1;
        }
    }

    private void removeAllQueriesContainingUser() {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        LinkedList<Future<Set<String>>> tasks = new LinkedList<>();
        for (String q : queries) {
            int indexOfUser = findIndexOfUser(q, users.iterator().next());
            if (indexOfUser >= 0 && !queryContainsOnlyUser(q)) {
                Set<String> userQuerySet = new HashSet<>();
                userQuerySet.addAll(q.substring(0, indexOfUser).split(" "));
                userQuerySet.addAll(q.substring(indexOfUser + users.iterator().next().length()).split(" "));
                tasks.addLast(pool.submit(() -> {
                    queries.removeAll(userQuerySet);
                    return userQuerySet;
                }));
            }
        }
        while (!tasks.isEmpty()) {
            Future<Set<String>> task = tasks.poll();
            try {
                queries.addAll(task.get());
            } catch (Exception e) {
                // Ignore exceptions, they should not happen.
            } finally {
                tasks.remove(task);
            }
        }
        pool.shutdown();
        try {
            pool.awaitTermination(10, TimeUnit.SECONDS);
        } catch (Exception e) {
            // Ignore exceptions, they should not happen.
        }
    }

    private boolean queryContainsOnlyUser(String query) {
