import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Random;
import java.util.concurrent.*;

enum Gender { MALE, FEMALE }

class Animal {
    private final Species species;
    private final Gender gender;

    public Animal(Species species, Gender gender) {
        this.species = species;
        this.gender = gender;
    }

    public Species getSpecies() { return species; }
    public Gender getGender() { return gender; }
}

enum Species { LION, ELEPHANT, ZEBRA }

class Pair<T extends Animal> {
    private final T first;
    private final T second;

    public Pair(T first, T second) {
        this.first = first;
        this.second = second;
    }

    public T getFirst() { return first; }
    public T getSecond() { return second; }
}

class Ark {
    private final List<Pair<? extends Animal>> pairs = new ArrayList<>();

    synchronized void addPairs(List<Pair<? extends Animal>> newPairs) {
        pairs.addAll(newPairs);
    }

    int getLoadedPairs() { return pairs.size(); }
}

class PairComparator implements Comparator<Pair<? extends Animal>> {
    @Override
    public int compare(Pair<? extends Animal> o1, Pair<? extends Animal> o2) {
        int speciesCompare = o1.getFirst().getSpecies().compareTo(o2.getFirst().getSpecies());
        if (speciesCompare != 0) return speciesCompare;
        int genderCompare = o1.getFirst().getGender().compareTo(o2.getFirst().getGender());
        return genderCompare == 0 ? 0 : genderCompare;
    }
}

class AnimalPairer implements Callable<List<Pair<? extends Animal>>> {
    private final List<Animal> candidates;

    public AnimalPairer(List<Animal> candidates) {
        this.candidates = candidates;
    }

    @Override
    public List<Pair<? extends Animal>> call() throws Exception {
        List<Pair<? extends Animal>> pairs = new ArrayList<>();
        Set<Class<? extends Animal>> seenSpecies = Sets.newHashSet();

        Comparator<Animal> animalComparator = new PairComparator().thenComparing(Animal::getGender);
        candidates.sort(animalComparator);

        int index = 0;
        boolean foundPair = false;
        while (index < candidates.size()) {
            Animal currentAnimal = candidates.get(index++);
            Species species = currentAnimal.getSpecies();

            if (!seenSpecies.contains(species.getClass())) {
                seenSpecies.add(species.getClass());
                int oppositeGenderIndex = Arrays.binarySearch(candidates, index, candidates.size(), (a) -> {
                    Gender oppositeGender;
                    switch (currentAnimal.getGender()) {
                        case MALE: oppositeGender = Gender.FEMALE; break;
                        case FEMALE: oppositeGender = Gender.MALE; break;
                        default: throw new AssertionError("Unknown gender: " + currentAnimal.getGender());
                    }
                    return a.getSpecies().equals(species) && a.getGender() == oppositeGender ? 0 : 1;
                }, Comparator.reverseOrder());

                if (oppositeGenderIndex >= 0 && oppositeGenderIndex < candidates.size()) {
                    Animal oppositeAnimal = candidates.get(oppositeGenderIndex);
                    foundPair = true;
                    pairs.add(new Pair<>(currentAnimal, oppositeAnimal));
                    index--; // remove current animal to maintain loop invariant
                }
            }
        }

        if (!foundPair) {
            throw new RuntimeException("Could not find a pair for species: " + species);
        }

        return pairs;
    }
}

