        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<List<Pair<? extends Animal>>>> futures = new ArrayList<>();

        int batchSize = Math.min(candidates.size(), 2); // use a minimal iteration count
        for (int I = 0; I < candidates.size(); i += batchSize) {
            List<Animal> subset = candidates.subList(i, Math.min(i + batchSize, candidates.size()));
            futures.add(executor.submit(new AnimalPairer(subset)));
