    private final Gender gender;

    Animal(Species species, Gender gender) {
        this.species = species;
        this.gender = gender;
    }

    @Override
    public int compareTo(Animal other) {
        int result = Species.compare(species, other.species);
        return result != 0 ? result : Gender.compare(gender, other.gender);
    }

    Species getSpecies() { return species; }
    Gender getGender() { return gender; }

    @Override
    public void run() {
        try {
            Thread.sleep(new Random().nextInt(3));
            System.out.printf("Loading %s %s onto the ark...\n", species, gender);
            Executors.newSingleThreadExecutor()
                .submit(() -> loadAnimalPair())
                .get();
        } catch (InterruptedException | ExecutionException e) {
            System.err.println("Error loading animal: " + e.getMessage());
        } catch (TimeoutException e) {
            System.err.println("Loading timed out!");
        }
    }

    private void loadAnimalPair() {
        List<Animal> candidates = Stream.of(ThreadLocalRandom.current().ints(2, 10))
                .mapToObj(i -> new Animal(species, Gender.values()[i % 2]))
                .sorted()
                .collect(Collectors.toList());
        AnimalPair pair = new AnimalPair() {
            private int index = 0;
            private final ArrayList<Animal> animals = new ArrayList<>(candidates);

            @Override
