    }

    public String getName() { return name; }

    @Override
    public int hashCode() {
        return Objects.hash(name);
    }

    @Override
    public boolean equals(Object other) {
        if (other instanceof Species) {
            return name.equals(((Species)other).getName());
        } else {
            return false;
        }
    }
