class Pair {
    private final Animal male;
    private final Animal female;

    public Pair(Animal male, Animal female) {
        this.male = male;
        this.female = female;
    }

    public Animal getMale() { return male; }
    public Animal getFemale() { return female; }
}

class Ark {
    private final Map<Species, List<Pair>> pairsBySpecies = new ConcurrentHashMap<>();

    public int countPairs() {
        int pairCount = 0;
        for (List<Pair> speciesPairs : pairsBySpecies.values()) {
            pairCount += speciesPairs.size();
        }
        return pairCount;
    }

    public void addPair(Animal male, Animal female) {
        Species species = male.getSpecies();
        List<Pair> pairs = pairsBySpecies.computeIfAbsent(species, k -> new ArrayList<>());
        pairs.add(new Pair(male, female));
    }
}

class LoadTheArk implements Callable<Integer> {
    private final List<Animal> candidates;
    private final Random random = ThreadLocalRandom.current();
    private final Ark ark;

    public LoadTheArk(List<Animal> candidates, Ark ark) {
        this.candidates = candidates;
        this.ark = ark;
    }

    @Override
    public Integer call() throws Exception {
        List<Animal> remainingCandidates = new ArrayList<>(candidates);
        int pairCount = 0;

        ExecutorService pool = Executors.newFixedThreadPool(2);
        List<Future<Pair>> pendingPairs = new ArrayList<>();

        while (!remainingCandidates.isEmpty()) {
            int size = Math.min(remainingCandidates.size(), 2);
            List<Animal> batch = remainingCandidates.subList(0, size);
            batch.sort((a, b) -> Integer.compare(a.compareTo(b), 0)); // sort by compareTo result to group animals of same species together

            for (int I = 0; I < size / 2; i++) { // first half are males
                Animal male = batch.get(i);
                List<Animal> potentialFemales = remainingCandidates.stream()
                        .filter(female -> female.getSpecies().equals(male.getSpecies()) && genderIsCompatibleWith(male, female))
                        .collect(Collectors.toList());
                if (!potentialFemales.isEmpty()) { // find a compatible female from the remaining candidates
                    int index = random.nextInt(Math.min(potentialFemales.size(), 1));
                    Animal female = potentialFemales.get(index);
                    pendingPairs.add(pool.submit(() -> { // submit pair creation task to pool
                        ark.addPair(male, female);
                        pairCount++;
                        return new Pair(male, female);
                    }));
                }
            }

            remainingCandidates = batch.subList(size / 2, batch.size()); // remove males from candidates and continue with females
        }

        int stillPending = pendingPairs.size();
        while (stillPending > 0) {
            Future<Pair> future = null;
            try {
                future = pool.take().get(1, TimeUnit.SECONDS); // block for a second if take returns an empty queue
            } catch (InterruptedException | ExecutionException e) {
                // ignore interrupts and completion exceptions
            } finally {
                pendingPairs.remove(future); // remove finished task from list
                stillPending--;
            }
        }

        pool.shutdown(); // shutdown executor service
        return pairCount;
    }

    private static boolean genderIsCompatibleWith(Animal male, Animal female) {
        return male.getGender() == Gender.FEMALE ^ female.getGender() == Gender.FEMALE; // opposite genders should be paired
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        List<Animal> candidates = Arrays.asList(
                new Animal(new Species("lion"), Gender.MALE),
                new Animal(new Species("lion"), Gender.FEMALE),
                new Animal(new Species("zebra"), Gender.MALE),
                new Animal(new Species("zebra"), Gender.FEMALE)
        );
        Ark ark = new Ark();

        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<Integer> futurePairCount = pool.submit(new LoadTheArk(candidates, ark));
        int totalPairCount = futurePairCount.get(); // get pair count from completed task

        System.out.println("Loaded " + totalPairCount + " pairs onto the ark!");
    }
}

