import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

public class ConcurrentPerformanceTester {
    private static final int CORE_THREADS = 2;
    private static final int TASK_COUNT = 10_000;
    private static final AtomicInteger counter = new AtomicInteger();
    private static final AtomicBoolean interruptFlag = new AtomicBoolean(false);
    private static final Supplier<Runnable> taskSupplier = () -> {
        int id = counter.incrementAndGet();
        return () -> {
            for (int I = 0; I < TASK_COUNT; i++) {
                Thread.yield(); // Yield CPU to other threads
            }
            System.out.println("Thread " + id + " completed.");
        };
    };

    private static final ExecutorService executor = Executors.newFixedThreadPool(CORE_THREADS + 1);
    private static final CountDownLatch startGate = new CountDownLatch(CORE_THREADS);
    private static final CountDownLatch endGate = new CountDownLatch(TASK_COUNT * CORE_THREADS);

    public static void main(String[] args) {
        long startTime = System.nanoTime();
        try (ThreadFactory threadFactory = Executors.defaultThreadFactory()) {
            for (int I = 0; I < CORE_THREADS; i++) {
                executor.execute(() -> {
                    Thread.currentThread().setDaemon(true); // Set non-main threads as daemon threads to avoid thread termination issues
                    try {
                        startGate.await(); // Wait for the "start gate" to open
                        while (!interruptFlag.get()) {
                            executor.execute(() -> {
                                Runnable task = taskSupplier.get();
                                task.run();
                                interruptFlag.set(true); // Set the flag when a task completes
                                endGate.countDown(); // Decrement the "end gate" countdown value for this completed task
                            });
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    } finally {
                        executor.shutdownNow(); // Shut down the thread pool at the end of the program
                    }
                }, threadFactory);
            }
            startGate.countDown(); // Decrement the "start gate" countdown value for this thread (the main thread)
            endGate.await(); // Wait for all threads to complete and release the "end gate"
