import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;
import java.util.stream.IntStream;

public class ConcurrentPerformanceTestingTool {
    private static final int THREAD_COUNT = 2;
    private static final ExecutorService threadPool = Executors.newFixedThreadPool(THREAD_COUNT);
    private static final CountDownLatch startGate = new CountDownLatch(THREAD_COUNT);
    private static final CountDownLatch endGate = new CountDownLatch(1);
    private static final AtomicBoolean interruptStatus = new AtomicBoolean();

    public static void timeTasks(int tasks, Runnable task) {
        Supplier<Thread> supplier = () -> {
            Thread thread = new Thread(() -> {
                try {
                    startGate.await();
                    task.run();
                    interruptStatus.set(false); // Clear interrupt flag after task completion
                    endGate.countDown();
                } catch (InterruptedException | InterruptException e) {
                    interruptStatus.set(true); // Set interrupt flag on exception
                } finally {
                    threadPool.returnThread(thread);
                }
            });
            threadPool.execute(thread); // Add Thread to thread pool
            return thread;
        };

        IntStream.range(0, tasks).parallel().mapToObj(supplier).collect(Collectors.toList()).forEach(Thread::start);
        try {
            endGate.await();
        } catch (InterruptedException e) {
            // Handle interrupts
            interruptStatus.set(true);
        } finally {
            threadPool.shutdownNow(); // Terminate thread pool
        }
    }

    public static void main(String[] args) {
        long startTime = System.nanoTime();
        timeTasks(10, () -> {
            try {
                Thread.sleep(50);
            } catch (InterruptedException e) {
                if (!interruptStatus.get()) { // Check interrupt flag before exiting
                    Thread.currentThread().interrupt();
                }
            }
        });
        long endTime = System.nanoTime();
        System.out.println("Execution time: " + (endTime - startTime) / 1e9);
    }
}

import java.util.concurrent.*;
import java.util.function.*;
import java.util.*;
import java.time.*;
import java.time.duration.*;

class Worker implements Runnable {
    private int id;
    private CountDownLatch startGate, endGate;
    private Runnable task;
    private boolean interrupted = false;

    public Worker(int id, CountDownLatch startGate, CountDownLatch endGate, Runnable task) {
        this.id = id;
        this.startGate = startGate;
        this.endGate = endGate;
        this.task = task;
    }

    @Override
    public void run() {
        try {
            startGate.await();
            task.run();
            if (isInterrupted()) interrupted = true;
            endGate.countDown();
        } catch (InterruptedException | TimeoutException e) {}
    }

    public boolean isInterrupted() {
        return Thread.currentThread().isInterrupted() || interrupted;
    }
}

public class PerformanceTestingTool {
    private static final int NUM_THREADS = 2; // Maximum 2 threads, including main thread
    private static final int TASK_ITERATIONS = 3; // Minimal loop iteration count
    private static final Random RANDOM = new Random(System.currentTimeMillis());

    public static void timeTasks(int numThreads, Runnable task) {
        CountDownLatch startGate = new CountDownLatch(NUM_THREADS);
        CountDownLatch endGate = new CountDownLatch(NUM_THREADS);
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS);
        for (int I = 0; I < numThreads - 1; i++) {
            executor.submit(new Worker(i + 1, startGate, endGate, task));
        }
        Thread mainThread = Thread.currentThread();
        startGate.countDown();
        try {
            endGate.await();
        } catch (InterruptedException | TimeoutException e) {} finally {
            mainThread.interrupt(); // Preserve interrupt status for the main thread
            executor.shutdown();
        }
        long duration = Duration.between(Instant.now(), Instant.now()).getNano();
        System.out.println("Duration: " + duration);
    }

    public static void main(String[] args) {
        timeTasks(NUM_THREADS, () -> {
            int sum = 0;
            for (int I = 0; I < TASK_ITERATIONS; i++) {
                int randomNumber = RANDOM.nextInt(3); // Minimal random number range
                sum += randomNumber;
            }
        });
    }
}

