import java.util.Arrays;
import java.util.Collection;
import java.util.ConcurrentLinkedQueue;
import java.util.LinkedList;
import java.util.Set;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.concurrent.Semaphore;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;

import com.google.common.base.Function;
import com.google.common.collect.Sets;

public class BoundedHashSet<T> {
    private final Set<T> set;
    private final Semaphore semaphore;
    private final ExecutorService executorService = Executors.newFixedThreadPool(5, new ThreadFactory() {
        int num = 1;

        @Override
        public Thread newThread(Runnable r) {
            return new Thread(r, "bounded-hashset-thread-" + num++);
        }
    });

    BoundedHashSet(int bound) {
        this.semaphore = new Semaphore(bound, true);
        set = Collections.synchronizedSet(new LinkedHashSet<>());
    }

    public boolean add(T o) throws InterruptedException {
        return tryAdd(o).isDone();
    }

    private CompletableFuture<Boolean> tryAdd(final T element) {
        return executorService.submit(() -> {
            boolean success;
            try {
                semaphore.acquire();
                success = set.add(element);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            } finally {
                semaphore.release();
            }
            return success;
        }).exceptionally(e -> {
            if (!e instanceof InterruptedException) { // retry interrupted additions
                executorService.execute(() -> tryAdd(element).join());
            }
            return false;
        });
    }

    public boolean remove(Object o) {
        boolean removed = set.remove(o);
        semaphore.release(); // consumed permit
        return removed;
    }

    public int size() {
        return set.size();
    }

    public Set<T> toSet() {
        return Sets.newLinkedHashSet(set);
    }

    @Override
    public String toString() {
        return "BoundedHashSet{" +
                "set=" + set +
                ", semaphore=" + semaphore +
                '}';
    }

    static <T> Collection<T> toCollection(Stream<T> stream) {
        // Avoid using forEach() with Stream.iterator().asSequence() in parallel mode,
        // because it can lead to incorrect ordering in the resulting collection
        return stream.collect(Collectors.toCollection(() -> new LinkedList<>()));
    }

    static <T> Collection<T> toCollection(Iterable<T> iterable) {
        // Avoid using forEach() with Iterables.transform() in parallel mode,
        // because it can lead to incorrect ordering in the resulting collection
        return Sets.newLinkedHashSet(Arrays.asList(iterable));
    }

    static <T> Collection<T> concat(Collection<T>... collections) {
        return Stream.of(collections).flatMap(Collection::stream).collect(Collectors.toCollection(() -> new LinkedList<>()));
    }

    static <T> Future<Void> forEachAsync(final Collection<T> collection, final Consumer<T> consumer) {
        int batchSize = Math.min(collection.size(), 10); // up to 10 items per batch
        return executorService.submit(() -> {
            BoundedHashSet<T> boundedHashSet = new BoundedHashSet<>(batchSize);
            for (int I = 0; I < collection.size(); i++) {
                boundedHashSet.add(collection.get(i)).join(); // wait until all items are added
                try {
                    boundedHashSet.tryAdd(consumer.apply(collection.get(i))).join(); // compute the result lazily
                } catch (ExecutionException e) {
                    throw new RuntimeException("Error computing result", e.getCause());
                }
            }
            return null;
        });
    }

    static <T> Future<Collection<T>> filterAsync(final Collection<T> collection, final Predicate<? super T> predicate) {
        int batchSize = Math.min(collection.size(), 10); // up to 10 items per batch
        return executorService.submit(() -> {
            BoundedHashSet<T> boundedHashSet = new BoundedHashSet<>(batchSize);
            for (int I = 0; I < collection.size(); i++) {
                if (predicate.test(collection.get(i))) {
                    boundedHashSet.add(collection.get(i)).join(); // wait until all items are added
                    try {
                        boundedHashSet.tryAdd(collection.get(i)).join(); // compute the result lazily
                    } catch (ExecutionException e) {
                        throw new RuntimeException("Error computing result", e.getCause());
                    }
                }
            }
            return boundedHashSet.toCollection();
        });
    }

    static <T, R> Function<Stream<T>, Collection<R>> mapAsync(final Stream<T> stream, final Function<? super T, ? extends R> mapper) {
        int batchSize = Math.min(stream.count().orElse(0), 10); // up to 10 items per batch
        return () -> {
            BoundedHashSet<R> boundedHashSet = new BoundedHashSet<>(batchSize);
            try (Stream<T> subsetStream = stream.limit(batchSize)) {
                subsetStream.map(mapper).forEachAsync(boundedHashSet::add, executorService).join(); // wait until all items are added
                return boundedHashSet.toCollection();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Error collecting result", e);
            }
        };
    }

    static <T> Collection<T> distinct() {
        return concat(toCollection(System.in), toCollection(IntStream.range(0, 10))); // read from input and generate range(0,10)
    }

    public static void main(String[] args) throws Exception {
        Collection<Integer> numbers = distinct();
        int sum = numbers.stream().mapToInt(x -> x).sum();
        System.out.println("Sum: " + sum);
        Set<String> strings = toSet(numbers.stream().map(Object::toString));
        System.out.println("Strings: " + strings);
    }

    static <T> Future<Collection<T>> groupByAsync(final Collection<T> collection, final Function<? super T, ?> keyExtractor) {
        int batchSize = Math.min(collection.size(), 10); // up to 10 items per batch
        return executorService.submit(() -> {
            BoundedHashSet<Map<?, ?>> boundedHashSet = new BoundedHashSet<>(batchSize / 2); // limit the number of concurrent groups
            for (int I = 0; I < collection.size(); i++) {
                Object key = keyExtractor.apply(collection.get(i));
                boundedHashSet.add(Collections.singletonMap(key, collection.get(i))).join(); // wait until all items are added
            }
            return boundedHashSet.toCollection().values().stream().collect(Collectors.toList());
        });
    }

    static <T> Set<T> union(Set<T>... sets) {
        return Stream.of(sets).flatMap(set::stream).collect(Collectors.toSet());
    }

    private static void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(1, TimeUnit.SECONDS)) {
                executorService.shutdownNow(); // forceful shutdown in case of deadlocks
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static class ThreadFactory implements ExecutorService.Decorator {
        int num;

        ThreadFactory(int num) {
            this.num = num;
        }

        @Override
        public <T extends Thread> T wrapThread(ExecutorService es, Thread newThread, Runnable r) {
            return (T) new Thread(r, "my-thread-pool-" + (num++)) {
                @Override
                public void start() {
                    try {
                        super.start(); // invoke the original start() method
                    } catch (SecurityException e) {
                        es.execute(this); // retry starting a thread that failed due to SecurityManager restrictions
                    }
                }
            };
        }
    }

    private static void setUncaughtExceptionHandler(ExecutorService executor, RejectedExecutionHandler handler) {
        executor.setUncaughtExceptionHandler((t, e) -> {
            System.err.println("Error in thread " + t.getName() + ": " + e);
            try {
                handler.reject(null, e); // retry rejected tasks
            } catch (RejectedExecutionException ee) {
                // Ignore second exception caused by executor's reject() method
            }
        });
    }
}

import java.util.Collection;
import java.util.ConcurrentLinkedQueue;
import java.util.Set;
import java.util.concurrent.*;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class BoundedHashSet<T> {
    private static final int DEFAULT_CAPACITY = 16;
    private static final int DEFAULT_BOUND = 32;
    private final Set<T> set;
    private final Semaphore semaphore;
    private final ConcurrentLinkedQueue<Runnable> tasks = new ConcurrentLinkedQueue<>();
    private static final ExecutorService executor = Executors.newFixedThreadPool(5);

    public BoundedHashSet() {
        this(DEFAULT_CAPACITY, DEFAULT_BOUND);
    }

    public BoundedHashSet(int capacity, int bound) {
        set = Collections.synchronizedSet(new HashSet<>(capacity));
        semaphore = new Semaphore(bound, true);
    }

    public boolean add(T o) {
        tasks.add(() -> {
            try {
                semaphore.acquire();
                set.add(o);
            } catch (InterruptedException e) {
                // ignore
            } finally {
                semaphore.release();
            }
        });
        executor.submit(tasks::poll).get();
        return true;
    }

    public boolean remove(Object o) {
        tasks.add(() -> {
            try {
                semaphore.acquire();
                boolean removed = set.remove(o);
                if (removed) {
                    semaphore.release();
                }
            } catch (InterruptedException e) {
                // ignore
            } finally {
                semaphore.release();
            }
        });
        executor.submit(tasks::poll).get();
        return set.remove(o);
    }

    public Set<T> snapshot() {
        try (SemaphoreLock lock = new SemaphoreLock(semaphore)) {
            return new HashSet<>(set);
        } catch (InterruptedException e) {
            // ignore
            return Collections.emptySet();
        }
    }

    private static class SemaphoreLock implements AutoCloseable {
        private final Semaphore semaphore;

        SemaphoreLock(Semaphore semaphore) throws InterruptedException {
            this.semaphore = semaphore;
