public class BoundedHashSet<T> {
    private int bound;
    private Semaphore semaphore;
    private Set<T> set = Collections.synchronizedSet(new HashSet<>());

    public BoundedHashSet(int bound) {
        this.bound = bound;
        this.semaphore = new Semaphore(bound);
    }

    public boolean add(T t) throws InterruptedException {
        semaphore.acquire();
        try {
            return set.add(t);
        } finally {
            if (!set.contains(t)) {
                semaphore.release();
            }
        }
    }

    public boolean remove(Object o) {
        boolean removed = set.remove(o);
        semaphore.release();
        return removed;
    }

    public int size() {
        return set.size();
    }

    public Stream<T> stream() {
        return set.stream().onClose(() -> {
            try {
                while (semaphore.availablePermits() > 0) {
                    semaphore.release();
                }
            } catch (InterruptedException e) {
                // Ignore interrupts here, they should not happen.
            }
        });
    }

    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        BoundedHashSet<Integer> set = new BoundedHashSet<>(5);

        IntStream.range(0, 10).parallel().mapToObj(i -> {
            try {
                return set.add((int) (Math.random() * 3));
            } catch (InterruptedException e) {
                throw new RuntimeException("Thread interrupted: " + e);
            }
        }).forEachOrdered(System.out::println).subscribe(() -> executor.shutdown());

        IntStream.range(0, 5).parallel().mapToObj(i -> set.stream().filter(rnd -> rnd % 2 == 0)).findFirst()
                .ifPresentOrElse(System.out::println, () -> System.out.println("Set is empty"));

        IntStream.rangeClosed(1, 5).parallel().mapToObj(i -> {
            try {
                return set.remove((int) (Math.random() * 3));
            } catch (InterruptedException e) {
                throw new RuntimeException("Thread interrupted: " + e);
            }
        }).forEachOrdered(System.out::println).subscribe(() -> executor.shutdown());

        System.out.println("Size: " + set.size());
        System.out.println("Set: " + set.stream().mapToInt(i -> i).sum() + " (" + set.stream().count() + ")");
        System.out.println("Stream:");
        try (Stream<Integer> stream = set.stream()) {
            stream.forEachOrdered(System.out::println);
        }

        executor.awaitTermination(1, TimeUnit.SECONDS);
    }
}

