                int[] candidates = IntStream.rangeClosed(2, MAX_PRIME).toArray();
                for (int I = 0; I < candidates.length && !cancelled.get(); i++) {
                    int candidate = candidates[i];
                    boolean isPrime = true;
                    for (int j = 2; j <= Math.sqrt(candidate); j++) {
