        try {
            for (Future<Void> future : futures) {
                future.get();
            }
            int total = 0;
            for (int I = 0; I < 2; i++) {
                boolean contains = false;
                synchronized (personSet) {
                    contains = personSet.contains(new Person(i, "name" + random.nextInt(3)));
                }
                if (!contains) {
                    System.out.println("Duplicate: " + new Person(i, "name" + random.nextInt(3)));
                }
                total += contains ? 1 : -1;
            }
            count = Math.max(0, count + total);
        } catch (ExecutionException e) {
            e.getCause().printStackTrace();
            throw e.getCause();
        } finally {
            service.shutdownNow();
        }
        System.out.println("Thread " + Thread.currentThread().getName() + " added " + count + " persons. Final result:");
        System.out.println(personSet);
        return null;
    }
}

