import java.util.function.Consumer;
import java.util.function.IntFunction;
import java.util.function.Predicate;

class Prime {
    static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int I = 2; I * I <= n; i++) {
            if (n % I == 0) return false;
        }
        return true;
    }
}

class Producer extends Thread {
    private BlockingQueue<Integer> queue;
    private IntFunction<Integer> generator;
    private AtomicBoolean interrupted = new AtomicBoolean(false);
    private int count;

    Producer(BlockingQueue<Integer> queue, IntFunction<Integer> generator, int count) {
        this.queue = queue;
        this.generator = generator;
        this.count = count;
    }

    @Override
    public void run() {
        try {
            for (int I = 0; I < count && !interrupted.get(); i++) {
                int num = generator.apply(i);
                while (!queue.offer(num)) {
                    Thread.yield();
                }
                if (i % 2 == 0) {
                    System.out.println("Produced: " + num);
                }
            }
        } catch (InterruptedException e) {
            interrupted.set(true);
        } catch (Exception e) {
            // Ignore exceptions from offer()
        }
    }
}

class Consumer implements Runnable {
    private BlockingQueue<Integer> queue;
    private Predicate<Integer> filter;
    private AtomicBoolean interrupted = new AtomicBoolean(false);
    private int count;

    Consumer(BlockingQueue<Integer> queue, Predicate<Integer> filter, int count) {
        this.queue = queue;
        this.filter = filter;
        this.count = count;
    }

    @Override
    public void run() {
        try {
            for (int I = 0; I < count && !interrupted.get(); i++) {
                int num = queue.poll();
                if (!filter.test(num)) {
                    continue;
                }
                System.out.println("Consumed: " + num);
            }
        } catch (InterruptedException e) {
            interrupted.set(true);
        }
    }
}

class PrimeProducer extends Producer implements Runnable {
    private int count;

    PrimeProducer(BlockingQueue<Integer> queue, IntFunction<Integer> generator, int count) {
        super(queue, (int I) -> Prime.generateNextPrime(), count);
        this.count = count;
    }

    @Override
    public void run() {
        super.run();
    }
}

class PrimeConsumer extends Consumer implements Runnable {
    private int count;

