    }
}

public class ProducerConsumerApp {
    private static final int PRIME_COUNT = 5;

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(3);
        BlockingQueue<Integer> queue = new LinkedBlockingDeque<>(2);

        executor.execute(new PrimeProducer(queue, Prime::generateNextPrime, PRIME_COUNT));
        Runnable consumerTask = () -> {
            List<Future<?>> tasks = new ArrayList<>();
            int batchSize = 10;
            for (int I = 0; I < batchSize; i++) {
                tasks.add(executor.submit(new Consumer(queue, n -> true, batchSize)));
            }
            try {
                for (Future<?> task : tasks) {
                    task.get();
                }
            } catch (InterruptedException | ExecutionException e) {
                // Ignore exceptions from get() and interrupt of consumers
            } finally {
                executor.shutdownNow(); // Stop all threads, including producer
            }
        };
        executor.execute(consumerTask);

        try {
            consumerTask.get(); // Wait for completion of consumer task
            queue.put(Prime.generateNextPrime()); // Generate one more prime after all others are consumed
            TimeUnit.SECONDS.sleep(1); // Wait briefly to ensure the last put() completes
        } catch (Exception e) {
            // Ignore exceptions from get() and interrupt of consumer, as well as from sleep()
        } finally {
            queue.clear(); // Clear remaining elements from queue
            executor.shutdownNow(); // Stop all threads, including producer
            try {
                consumerTask.get(10, TimeUnit.SECONDS); // Wait for producer to stop, up to 10 seconds
                if (!queue.isEmpty()) {
                    System.out.println("Primes remaining in queue: " + queue.size());
                }
            } catch (Exception e) {
                // Ignore exceptions from get() and interrupt of producer
            }
        }
    }
}

