    private int stop;

    public PrimeProducer(BlockingQueue<Integer> queue, int stop) {
        this.queue = queue;
        this.stop = stop;
    }

    @Override
    public void run() {
        try (var generator = new PrimeGenerator()) {
            while (!isInterrupted() && !queue.isEmpty() || queue.size() + 2 < stop) {
                int prime = generator.next();
                queue.put(prime);
                if (queue.size() + 1 >= stop) {
                    interrupt();
                    break;
                }
            }
        } catch (InterruptedException | Exception e) {
            System.err.println("Producer interrupted: " + e);
        }
    }

    private static class PrimeGenerator implements Supplier<Integer> {
        int p = 2;
        boolean[] isComposite = new boolean[100];
        List<Integer> primes = new ArrayList<>();

        @Override
        public Integer getAsInt() {
            while (true) {
                if (isComposite[p]) {
                    p++;
                    continue;
                }
                int candidate = p;
                isComposite[candidate] = true;
                for (int I = candidate * 2; I <= 100; I += candidate) {
                    isComposite[i] = true;
                }
                primes.add(p);
                return p++;
            }
        }
    }
}

