    // Producer Thread Class
    private static class PrimeProducer extends Thread {
        private static final int MIN_PRIME = 2;
        private boolean stopRequested;

        PrimeProducer() {
            setName("PrimeProducer");
            this.stopRequested = false;
        }

        @Override
        public void run() {
            while (!stopRequested) {
                int[] primes = generatePrimes();
                try {
                    PRIMENUMBERQUEUE.putAll(Arrays.stream(primes).boxed().collect(Collectors.toList()));
                } catch (InterruptedException | RejectedExecutionException e) {
                    // Handle Interruption and Queue Overflow Errors
                    stopRequested = true;
                    interrupt();
                }
            }
        }

        private int[] generatePrimes() {
            List<Integer> primesList = new ArrayList<>();
            int n = RANDOM.nextInt(10);
            for (int I = MIN_PRIME; I <= n; i++) {
                boolean isPrime = true;
                for (int j = 2; j * i <= n; j++) {
                    if (n % i == 0) {
                        isPrime = false;
                        break;
                    }
                }
                if (isPrime) {
                    primesList.add(i);
                }
            }
            return IntStream.of(primesList).toArray();
        }
    }

    // Consumer Thread Class
    private static class PrimeConsumer implements Runnable {
        private boolean stopRequested;

        @Override
        public void run() {
            while (!stopRequested) {
