                try {
                    prime = PRIMENUMBERQUEUE.take();
                    System.out.println("Consuming: " + prime);
                } catch (InterruptedException | EmptyQueueException e) {
                    // Handle Interruption and Queue Underflow Errors
                    stopRequested = true;
                    interrupt();
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        ExecutorService executorService = Executors.newFixedThreadPool(PRODUCER_COUNT + CONSUMER_COUNT);

        AtomicInteger producedPrimesCount = new AtomicInteger();
        PrimeProducer[] producers = new PrimeProducer[PRODUCER_COUNT];
        for (int I = 0; I < PRODUCER_COUNT; i++) {
            producers[i] = new PrimeProducer();
            executorService.submit(producers[i]);
            producedPrimesCount.incrementAndGet();
        }

        AtomicBoolean allProduced = new AtomicBoolean(false);
        int targetPrimes = Math.min(MAX_PRIMES, PRODUCER_COUNT * 2);
        PrimeConsumer consumer = new PrimeConsumer();
        executorService.submit(() -> {
            while (producedPrimesCount.get() < targetPrimes || !allProduced.get()) {
                // Wait for Producer to produce Target Primes or All Producers to Stop
            }
            allProduced.set(true);
            executorService.shutdown();
        });

        consumer.run();
        for (int I = 0; I < PRODUCER_COUNT; i++) {
            producers[i].stopRequested = true;
            // Join Producers to Wait for Interruption and Thread Termination
            executorService.execute(() -> {
                try {
                    Thread.sleep(10);
                    while (!producers[i].isInterrupted()) {
                        // Wait for Producer to Stop or Interrupt Signal
                    }
                } catch (InterruptedException | AWTException e) {
                    // Ignore Interruption Errors
                }
            });
        }

        executorService.shutdownNow();
        // Join Executor Service to Wait for Thread Termination
    }
