import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Function;
import java.util.*;

class SafePoint {
    private int x, y;

    public SafePoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() { return x; }
    public int getY() { return y; }

    @Override
    public String toString() {
        return "SafePoint [x=" + x + ", y=" + y + "]";
    }
}

class VehicleLocation {
    private String id;
    private SafePoint location;

    public VehicleLocation(String id, int x, int y) {
        this.id = id;
        this.location = new SafePoint(x, y);
    }

    public String getId() { return id; }
    public SafePoint getLocation() { return location; }
}

class PublishingVehicleTracker {
    private Map<String, VehicleLocation> locations = new ConcurrentHashMap<>();
    private static Lock lock = new ReentrantLock();
    private static final int MAX_THREADS = 3;
    private static ExecutorService pool = Executors.newFixedThreadPool(MAX_THREADS);

    public void publishLocation(String id, int x, int y) {
        Runnable task = () -> {
            VehicleLocation location = locations.get(id);
            SafePoint newLocation = new SafePoint(x, y);
            if (location != null && !Objects.equals(newLocation, location)) {
                throw new RuntimeException("Invalid location update: " + id);
            }
            lock.lock();
            try {
                locations.put(id, new VehicleLocation(id, x, y));
            } finally {
                lock.unlock();
            }
        };
        pool.execute(task);
    }

    public Map<String, SafePoint> getLocations() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(locations) {
            @Override
            public SafePoint put(String key, SafePoint value) {
                throw new UnsupportedOperationException("Internal error: Cannot modify vehicle locations");
            }
        });
    }

    public SafePoint getLocation(String id) {
        SafePoint location = null;
        lock.lock();
        try {
