public class PublishingVehicleTracker {
    private final Map<String, SafePoint> locations = new ConcurrentHashMap<>();

    public void publishLocation(String id, int x, int y) {
        locations.computeIfAbsent(id, k -> new SafePoint(x, y)).publish();
    }

    public SafePoint getLocation(String id) {
        return locations.get(id);
    }

    public Collection<SafePoint> getAllLocations() {
        return Collections.unmodifiableCollection(locations.values());
    }

    private static class SafePoint implements Runnable {
        final int x, y;
        private boolean published = false;

        SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        void publish() {
            if (published) return;
            System.out.printf("Publishing location (%d, %d)%n", x, y);
            published = true;
        }

        @Override
        public void run() {
            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            publish();
        }
    }

    private static class LocationTracker implements Runnable, Callable<Void> {
        final String id;
        final int x, y;
        private boolean started = false;
        private ExecutorService threadPool = Executors.newFixedThreadPool(2);
        private volatile boolean stopRequested = false;

        LocationTracker(String id, int x, int y) {
            this.id = id;
            this.x = x;
            this.y = y;
            threadPool.submit(this);
        }

        @Override
        public void run() {
            if (started) return;
            started = true;
            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            System.out.printf("Updating location of %s (%d, %d)%n", id, x, y);
            threadPool.submit(() -> publishingVehicle(id));
        }

        @Override
        public Void call() throws Exception {
            while (!stopRequested) {
                Thread.sleep(1000);
                publishingVehicle(id);
            }
            threadPool.shutdownNow();
            return null;
        }

        private void publishingVehicle(String id) {
            PublishingVehicleTracker tracker = PublishingVehicleTracker.this;
            Runnable runnable = () -> tracker.publishLocation(id, x, y);
            if (tracker.locations.computeIfPresent((k, oldValue) -> {
                if (!oldValue.published && k.equals(id)) {
                    return new SafePoint(x, y).publish();
                } else {
                    oldValue.x = x;
                    oldValue.y = y;
                    return oldValue;
                }
            }) == null) {
                throw new IllegalStateException("Unknown vehicle: " + id);
            }
            threadPool.execute(runnable);
        }
    }

    public static void main(String[] args) throws Exception {
        PublishingVehicleTracker tracker = new PublishingVehicleTracker();
        LocationTracker loc1 = new LocationTracker("1", 42, 69);
        new LocationTracker("2", 7, 8).call();
        while (true) {
            Collection<SafePoint> locations = tracker.getAllLocations();
            int count = 0;
            for (SafePoint location : locations) {
                if (!location.published) {
                    System.out.printf("Location (%d, %d) not yet published%n", location.x, location.y);
                } else {
                    count++;
                }
            }
            System.out.printf("%d locations published%n", count);
            Thread.sleep(1000);
        }
    }
}

