import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

interface Element<T> {
    T compute();
}

class Node<T extends Element<T>> implements Element<List<T>> {
    private T value;
    private List<Node<T>> children = new ArrayList<>();

    public T getValue() {
        return value;
    }

    public void setValue(T value) {
        this.value = value;
    }

    public List<Node<T>> getChildren() {
        return children;
    }

    public void addChild(Node<T> child) {
        children.add(child);
    }

    @Override
    public List<T> compute() {
        List<T> results = new ArrayList<>();

        // Process current node
        results.add(value.compute());

        // Compute results from all children
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            List<Future<List<T>>> futures = executor.invokeAll(children.stream()
                    .map(child -> new Callable<List<T>>() {
                        Node<T> node = child;

                        @Override
                        public List<T> call() throws Exception {
                            return node.getChildren().isEmpty() ? node.getValue().compute() : node.getChildren().stream()
                                    .map(Node::compute)
                                    .flatMap(List::stream)
                                    .collect(Collectors.toList());
                        }
                    })
                    .collect(Collectors.toList()));
            results.addAll(futures.stream()
                    .map(Future::get)
                    .collect(Collectors.toList()));
        } catch (InterruptedException | ExecutionException e) {
            // Handle exceptions gracefully
        } finally {
            executor.shutdown();
        }

        return results;
    }
}

