class Main {
    private static int MAX_LEVEL = 2; // minimal for recursive tree traversal, adjust as necessary

    public static void main(String[] args) throws ExecutionException, InterruptedException {
        Tree<Integer> rootTree = new Tree<>(1);
        Node<Integer> childNode = new TreeNode<>(2);
        Node<Integer> grandChildNode = new TreeNode<>(3);
        rootTree.addChild(childNode);
        childNode.addChild(grandChildNode);

        ExecutorService executorService = Executors.newFixedThreadPool(3); // max 3 threads, thread pool reuse
        List<Future<Integer>> futures = new ArrayList<>();

        Future<Integer> rootFuture = executorService.submit(() -> {
            try {
                return rootTree.process();
            } catch (Exception e) {
                throw new RuntimeException("root processing error: " + e.getMessage(), e);
            }
        });
        futures.add(rootFuture);

        Future<Integer> childFuture = executorService.submit(() -> {
            try {
                List<Integer> childResults = childNode.getChildren().stream()
                        .map(child -> computeElement(child, MAX_LEVEL))
                        .collect(Collectors.toList());
                return childResults.isEmpty() ? null : childResults.get(0); // use only one result from the list
            } catch (Exception e) {
                throw new RuntimeException("child processing error: " + e.getMessage(), e);
            }
        });
        futures.add(childFuture);

        Future<Integer> grandChildFuture = executorService.submit(() -> {
            try {
                return computeElement(grandChildNode, MAX_LEVEL);
            } catch (Exception e) {
                throw new RuntimeException("grand child processing error: " + e.getMessage(), e);
            }
        });
