        List<Integer> results = executorService.invokeAll(futures).stream()
                .map(Future::get)
                .filter(Objects::nonNull)
                .collect(Collectors.toList());
        executorService.shutdown(); // thread pool shutdown, all pending tasks will be executed first

        int result = results.isEmpty() ? null : results.get(0); // use only one result from the list
        System.out.println("Final result: " + result);
    }

    private static <T extends Element<T>> T computeElement(T element, int maxLevel) {
        try {
            Thread.sleep(1_000); // simulate long-running computation
        } catch (InterruptedException e) {
            throw new RuntimeException("Thread sleep interrupted: " + e.getMessage(), e);
        }

        if (element instanceof Node && ((Node<T>) element).getChildrenNodes().isEmpty()) {
            return null; // leaf node, no need to recurse
        } else if (maxLevel > 0) {
            List<Future<Integer>> childFutures = new ArrayList<>();
            for (Node<T> child : ((Node<T>) element).getChildrenNodes()) {
                Future<Integer> future = executorService.submit(() -> computeElement(child, --maxLevel)); // recurse with decremented maxLevel
                childFutures.add(future);
            }
            List<Integer> results = executorService.invokeAll(childFutures).stream()
                    .map(Future::get)
                    .filter(Objects::nonNull)
                    .collect(Collectors.toList());
            return results.isEmpty() ? null : results.get(0); // use only one result from the list
        } else {
            try {
                return element.process();
            } catch (Exception e) {
                throw new RuntimeException("Element processing error: " + e.getMessage(), e);
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.stream.*;

interface Element<T extends Element<T>> {
    T compute();
    List<T> getChildren();
}

interface Node<T extends Node<T>> extends Element<T> {
    @Override
    default List<T> getChildren() {
        return new ArrayList<>();
    }

    abstract void addChild(Node<? extends T> node);

    abstract T compute();
}

class Leaf implements Element<Leaf> {
    private final int value;

    public Leaf(int value) {
        this.value = value;
    }

    @Override
    public List<Leaf> getChildren() {
        return new ArrayList<>();
    }

    @Override
    public Leaf compute() {
        return new Leaf(value);
    }
}

class NodeImpl implements Node<Leaf> {
    private final int value;
    private final List<Node<? extends Leaf>> children = new ArrayList<>();

    public NodeImpl(int value) {
        this.value = value;
    }

    @Override
    public void addChild(Node<? extends Leaf> node) {
        children.add(node);
    }

    @Override
    public List<Leaf> getChildren() {
        return children.stream()
                .map(Node::compute)
                .collect(Collectors.toList());
    }

    @Override
    public Leaf compute() {
        return new Leaf(value);
    }
}

class TreeBuilder {
    private int depth;

    public TreeBuilder(int depth) {
        this.depth = depth;
    }

    public List<Leaf> buildTree() {
        ExecutorService pool = Executors.newFixedThreadPool(3);
        List<Node<? extends Leaf>> roots = new ArrayList<>();
        for (int I = 0; I < Math.pow(2, depth); i++) {
            NodeImpl root = new NodeImpl(i);
            roots.add(root);
            for (int j = 0; j < Math.pow(2, depth - 1); j++) {
                NodeImpl child = new NodeImpl(j);
                root.addChild(child);
                pool.submit(() -> computeNode(depth - 1, child));
            }
        }
        pool.shutdown();
        return roots.stream()
                .map(Node::compute)
                .collect(Collectors.toList());
    }

    private Leaf computeNode(int depth, Node<? extends Leaf> node) {
        if (depth == 0) {
            return node.compute();
        } else {
            ExecutorService pool = Executors.newSingleThreadExecutor();
            List<Leaf> leaves = node.getChildren().stream()
                    .map(child -> computeNode(depth - 1, child))
                    .collect(Collectors.toList());
            pool.shutdown();
            return new Leaf(leaves.stream().reduce(0, (a, b) -> a + b).getAsInt());
        }
    }
}

public class ConcurrentTreeComputation {
    public static void main(String[] args) {
        List<Leaf> leaves = new TreeBuilder(3).buildTree();
        System.out.println(leaves.stream().reduce(0, (a, b) -> a + b).getAsInt());
    }
}

