public class ReadWriteMap {
    private Map<?, ?> data;
    private ReentrantReadWriteLock rwl = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<?, ?> map) {
        this.data = map;
    }

    public void put(K key, V value) {
        rwl.writeLock().lock();
        try {
            data.put(key, value);
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public void remove(Object key) {
        rwl.writeLock().lock();
        try {
            data.remove(key);
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public void putAll(Map<?, ?> m) {
        rwl.writeLock().lock();
        try {
            data.putAll(m);
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public void clear() {
        rwl.writeLock().lock();
        try {
            data.clear();
        } finally {
            rwl.writeLock().unlock();
        }
    }

    public Collection<? extends K> keySet() {
        return rwl.readLock().lock(() -> data.keySet());
    }

    public Collection<? extends V> values() {
        return rwl.readLock().lock(() -> new ArrayList<>(data.values()));
    }

    public Set<Entry<?, ?>> entrySet() {
        return rwl.readLock().lock(() -> new ArrayList<>(data.entrySet()));
    }

    public int size() {
        return rwl.readLock().lock(() -> data.size());
    }

    public boolean isEmpty() {
        return rwl.readLock().lock(() -> data.isEmpty());
    }

    public boolean containsKey(Object key) {
        return rwl.readLock().lock(() -> data.containsKey(key));
    }

    public boolean containsValue(Object value) {
        return rwl.readLock().lock(() -> data.containsValue(value));
    }

    public Map<?, ?> getCopy() {
        Map<K, V> copy = new LinkedHashMap<>();
        data.forEach((k, v) -> copy.put(k, v));
        return copy;
    }

    private class ReadWriteRunnable implements Runnable {
        private Runnable task;

        public ReadWriteRunnable(Runnable task) {
            this.task = task;
        }

        @Override
        public void run() {
            rwl.readLock().lock();
            try {
                task.run();
            } finally {
                rwl.readLock().unlock();
            }
        }
    }

    private static final ExecutorService threadPool = Executors.newFixedThreadPool(3);

    public <R> R executeOnThreadPool(Callable<R> callable) throws Exception {
        return threadPool.submit(callable).get();
    }
}

